INSERT INTO `schemes` (`id`, `scheme_code`, `name`, `short_name`, `slug`, `description`, `scheme_level`, `state_id`, `theme_id`, `service_approach_id`, `priority_id`, `feasibility_id`, `ministry_id`, `department_id`, `ministry_name`, `department_name`, `scheme_status`, `active_enrollment`, `launch_year`, `target_group_summary`, `eligibility_summary`, `benefit_type`, `benefit_description`, `benefit_amount`, `benefit_amount_text`, `benefit_mode`, `benefit_frequency`, `benefit_conditions`, `application_mode`, `application_process`, `application_instructions`, `portal_url`, `csc_available`, `physical_office`, `helpline_number`, `source_url`, `source_website`, `last_verified_date`, `verified_by`, `keywords`, `view_count`, `is_active`, `source_row_no`) VALUES
  (1, 'JK-SCH-0001', 'Pradhan Mantri Matru Vandana Yojana (PMMVY)', 'PMMVY', 'pradhan-mantri-matru-vandana-yojana-pmmvy', NULL, 'National', NULL, 1, 2, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, '18 - 59 years old, pregnant and lactating women', '1. Proof of pregnancy (e.g., pregnancy test results).\n2. Aadhaar card.\n3. Bank account details (for direct transfers).\n4. Proof of age and residence (e.g., birth certificate, address proof).\n5. Medical records related to pregnancy and vaccination', 'Cash Benefit', 'Cash incentive of ₹5,000 in three installments: ₹1,000 on early pregnancy registration, ₹2,000 after six months, and ₹2,000 post-birth for meeting health requirements', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'In instalments', NULL, 'Offline', '1. Visit the nearest Anganwadi center or health facility.\n2. Register your pregnancy and complete the application process.\n3. Provide required documents and follow up with the center to receive the installments', NULL, NULL, 0, NULL, NULL, 'https://wcd.delhi.gov.in/wcd/pradhan-mantri-matru-vandana-yojana-pmmvy', 'wcd.delhi.gov.in', NULL, NULL, 'Health Women PMMVY', 0, 1, 1),
  (2, 'JK-SCH-0002', 'Integrated Child Development Scheme(ICDS)', 'ICDS', 'integrated-child-development-scheme-icds', NULL, 'National', NULL, 1, 2, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, '0-6 years for Children, pregnant, and lactating mothers', 'Photograph. signature, educational certificates, age proof, caste certificate (if applicable), ID proof, and experience certificate (if applicable)', 'In-kind / Material', 'Supplementary Nutrition (SNP),\nHealth & Nutrition Check-Up,\nImmunization,\nNon-Formal Education for Children in Pre-School,\nHealth and Nutrition Education,\nReferral services', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'visit your local Anganwadi center, provide necessary documents, and submit the required application forms', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-children/', 'wcdhry.gov.in', NULL, NULL, 'Health and Education Children, Women ICDS', 0, 1, 2),
  (3, 'JK-SCH-0003', 'Improving Infant & Young Child feeding (IYCF)', 'IYCF', 'improving-infant-young-child-feeding-iycf', NULL, 'National', NULL, 1, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, 'Infants(2 years), young children (6 months-2years), pregnant women, breastfeeding mothers', 'Birth Certificate, Proof of Income, Residence Proof,\nSchool Records, Identity Proof', 'Training', 'To give training to grass root level ICDS functionaries on Infant and young child feeding practices.\nTo generate awareness on Infant Young Child Feeding Practices', NULL, NULL, NULL, NULL, NULL, 'Offline', 'submit an application with required documents to your local health department or Anganwadi center, following their specific procedures', NULL, NULL, 0, NULL, NULL, 'https://nhm.gov.in/New_Updates_2018/NHM_Components/RMNCHA/CH/Schemes/Maa/TRAINERS', 'nhm.gov.in', NULL, NULL, 'Health Women, Children IYCF', 0, 1, 3),
  (4, 'JK-SCH-0004', 'Apki Beti Hamari Beti (ABHB)', 'ABHB', 'apki-beti-hamari-beti-abhb', NULL, 'National', NULL, 1, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Adolescent girls(11 & 14 years), Families with low or below-poverty-line income, Residents of the specific state or region where the scheme is implemented', 'Birth Certificate, Proof of Income, Residence Proof,\nSchool Records, Identity Proof', 'In-kind / Material', 'health services, nutritional support, educational support, and awareness programme', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Submit an application with the required documents to the local health department or designated implementation agency, such as Anganwadi centers or school authorities', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-children/', 'wcdhry.gov.in', NULL, NULL, 'Health and Education Children ABHB', 0, 1, 4),
  (5, 'JK-SCH-0005', 'Working Women Hostel / Sakhi Niwas', NULL, 'working-women-hostel-sakhi-niwas', NULL, 'National', NULL, 30, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, '1.working women (single, widowed, divorced, separated, or married but living away from their husbands or relatives).\n2.The income limit is ₹50,000 per month in metro cities and ₹35,000 in other areas\n3.Students and trainees can also apply, though they should not exceed 30% of hostel capacity.\n4.Preference is given to women under 45 years of age', 'Identity proof\nAddress proof\nIncome Proof.\nEmployment Proof', NULL, '1. Safe Accommodation\n2. Affordable Rent\n3.Additional facilities\n4. Empowerment', NULL, NULL, NULL, NULL, NULL, 'Online', '1. Get the application form from the hostel management, state government websites, or designated authorities.\n2. Fill out the form and submit it with the required documents.\n3.Applications are reviewed, and selected candidates are notified', NULL, NULL, 0, NULL, NULL, 'https://wcd.nic.in/sites/default/files/Working%20Women%20Hostel_about_revised_about.pdf', 'wcd.nic.in', NULL, NULL, 'Rehabilitation Women', 0, 1, 5),
  (6, 'JK-SCH-0006', 'PM Poshan Abhiyan', NULL, 'pm-poshan-abhiyan', NULL, 'National', NULL, 1, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, 'children(0-6 years), adolescent girls, pregnant women, lactating mothers', 'identity proof, address proof, proof of age, medical records', 'In-kind / Material', 'Prevent and reduce Stunting in children (0- 6 years)\nPrevent and reduce under-nutrition (underweight prevalence) in children (0-6 years)\nReduce the prevalence of anemia among young Children(6-59 months)\nReduce the prevalence of anemia among Women and Adolescent Girls in the age group of 15-49 years\nReduce Low Birth Weight (LBW)', NULL, NULL, NULL, NULL, NULL, 'Offline', 'visit your local Anganwadi centre with the required documents and complete the application process as guided by the centre staff', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-children/poshan-abhiyan/', 'wcdhry.gov.in', NULL, NULL, 'Health Children, Women', 0, 1, 6),
  (7, 'JK-SCH-0007', 'Domestic Violence Scheme', NULL, 'domestic-violence-scheme', NULL, 'National', NULL, 26, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, '1. Victims of domestic violence, which includes physical, emotional, or psychological abuse by a family member or intimate partner.\n2. The victim must be a resident of India.\n3. The case should ideally be reported to the police or a legal authority, although immediate assistance can also be provided based on the situation', '1. Proof of identity (e.g., Aadhaar card, passport).\n2. Proof of residence.\n3. Medical reports (if applicable).\n4. Police complaint or FIR copy (if available).\n5. Any additional documentation supporting the claim of abuse (e.g., photographs of injuries, witness statements)', 'Cash Benefit', '1. Immediate financial assistance or relief to cover urgent needs.\n2. Access to shelter and temporary accommodation.\n3. Legal aid and counseling services.\n4. Medical support and access to healthcare facilities.\n5. Assistance with filing complaints and navigating the legal system', NULL, NULL, NULL, NULL, NULL, 'Offline', '1. Contact the nearest Women’s Helpline or Domestic Violence Cell in the local police station.\n2. Visit a local NGO or legal aid center that specializes in domestic violence issues.\n3. Submit the required documents and provide a statement detailing the abuse and the need for assistance', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/domestic-violence-scheme/', 'wcdhry.gov.in', NULL, NULL, 'Women\'s Safety Women, Children', 0, 1, 7),
  (8, 'JK-SCH-0008', 'Women Helpline Number 181 scheme', NULL, 'women-helpline-number-181-scheme', NULL, 'National', NULL, 26, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, '1. Any woman facing emergency situations related to violence, harassment, or abuse.\n2. The service is available to women across all age groups and socio-economic backgrounds', 'No specific documents are required to access the helpline. However, if further assistance or legal action is pursued, documentation such as identity proof, medical reports, and complaint records might be needed', 'Service Delivery', '1. Immediate emergency assistance and support.\n2. Access to counseling and guidance for dealing with distressing situations.\n3. Connection to local services such as police, legal aid, and medical facilities.\n4. Support for filing complaints and obtaining protection if necessary', NULL, NULL, NULL, NULL, NULL, 'Offline', '1. Dial the helpline number 181 from any phone.\n2. Provide details of the emergency or issue to the operator or counselor.\n3. Follow the instructions provided by the helpline staff for further assistance', NULL, NULL, 0, NULL, '181', 'https://wcdhry.gov.in/women-helpline-number-181/', 'wcdhry.gov.in', NULL, NULL, 'Women\'s Safety Women', 0, 1, 8),
  (9, 'JK-SCH-0009', 'Beti Bachao Beti Padhao ( BBBP)', 'BBBP', 'beti-bachao-beti-padhao-bbbp', NULL, 'National', NULL, 27, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, '1. The scheme primarily targets girl children and their families across India.\n2. Special emphasis is placed on areas with a low Child Sex Ratio and higher instances of gender-based discrimination', '1. Birth certificate of the girl child.\n2. Proof of residence.\n3. Proof of income (if applying for specific benefits related to economic status).\n4. Identity proof of parents or guardians (e.g., Aadhaar card)', 'In-kind / Material', '1. Financial incentives and support for the education of girl children.\n2. Awareness programs and community outreach to improve attitudes towards the education and well-being of girls.\n3. Health and nutrition support for girls.\n4. Support for ensuring the safety and protection of girls from gender-based violence and discrimination', NULL, NULL, NULL, NULL, NULL, 'Offline', '1. The scheme is often implemented through local government offices, schools, and healthcare centers.\n2. Families do not usually need to apply directly. Instead, they are provided support through community programs and outreach initiatives.\n3. For specific financial or educational benefits, families may need to contact the local District Social Welfare Office or Anganwadi center', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-women/beti-bachao-beti-padhao/', 'wcdhry.gov.in', NULL, NULL, 'Girl Child Safety and Education Children BBBP', 0, 1, 9),
  (10, 'JK-SCH-0010', 'One Stop Centre Scheme', NULL, 'one-stop-centre-scheme', NULL, 'National', NULL, 26, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, '1. Women and girls who are survivors of violence or abuse.\n2. The violence must be reported or documented to access the scheme\'s services', '1. Proof of identity (e.g., Aadhaar card, passport).\n2. Proof of residence.\n3. Medical reports (if applicable).\n4. Police complaint or FIR copy (if available).\n5. Any documentation supporting the claim of abuse or violence', 'Service Delivery', '1. Medical Assistance\n2. Legal Aid\n3. Counseling Services\n4. Shelter\n5. Referral Services', NULL, NULL, NULL, NULL, NULL, 'Offline', '1. Visit the nearest One Stop Centre or contact the local helpline number for immediate assistance.\n2. Access services directly at the center or through referral from police stations, hospitals, or NGOs.\n3. Provide the necessary documents and information as required by the center staff', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-women/onestop-centre/', 'wcdhry.gov.in', NULL, NULL, 'Women\'s Safety Women', 0, 1, 10),
  (11, 'JK-SCH-0011', 'State Resource Centre for Women Scheme', NULL, 'state-resource-centre-for-women-scheme', NULL, 'National', NULL, 26, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, '1. Women residing in the state where the SRCW is operational.\n2. The scheme serves all women, but certain programs within the SRCW may target specific groups such as survivors of violence, economically disadvantaged women, or women from marginalized communities', '1. Proof of identity (e.g., Aadhaar card, voter ID).\n2. Proof of residence (e.g., utility bills, rent agreement).\n3. Income certificate (if applying for financial assistance or specific programs).\n4. Any relevant documentation related to the specific services sought (e.g., medical records, legal documents)', 'Training', '1. Information and Counseling\n2. Training and Capacity Building\n3. Support Services\n4. Coordination of Services\n5. Awareness Programs', NULL, NULL, NULL, NULL, NULL, 'Offline', '1. Contact the nearest State Resource Centre for Women or visit their office.\n2. Reach out to local women’s organizations or NGOs associated with the SRCW for guidance.\n3. Submit the required documents and fill out the application forms for specific services or programs offered by the SRCW', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-women/kishori-shakti-yojna/', 'wcdhry.gov.in', NULL, NULL, 'Women\'s Safety Women', 0, 1, 11),
  (12, 'JK-SCH-0012', 'Compensation Scheme for Women Victims/Survivors of Sexual Assault/Other Crimes - 2018', NULL, 'compensation-scheme-for-women-victims-survivors-of-sexual-assault-other-crimes-2018', NULL, 'National', NULL, 26, 3, NULL, NULL, 16, NULL, 'Ministry of Law and Justice', NULL, 'Active', 1, NULL, '1. Women who are survivors of sexual assault, trafficking, or other severe crimes.\n2. The crime must be reported to the police, and an FIR (First Information Report) should be filed.\n3. The compensation is provided based on the severity of the crime and its impact on the victim’s life', '1. FIR or police complaint copy.\n2. Medical report detailing the injuries or trauma sustained.\n3. Proof of identity (e.g., Aadhaar card, passport).\n4. Proof of residence.\n5. Bank account details for compensation transfer.\n6. Any other documentation required by state authorities for processing the claim', 'Service Delivery', '1. Financial Compensation\n2. Medical Support\n3. Legal Aid\n4. Rehabilitation Support\n5. Counseling Services', NULL, NULL, NULL, NULL, NULL, 'Offline', '1. Report the crime to the police and obtain an FIR or complaint copy.\n2. Approach the District Legal Services Authority (DLSA) or State Legal Services Authority (SLSA) to apply for compensation.\n3. Submit the required documents along with the application form at the relevant legal services authority or district office', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-women/compensation-scheme-for-women-victims-survivors-of-sexual-assault-other-crimes-2018/', 'wcdhry.gov.in', NULL, NULL, 'Women\'s Safety Women', 0, 1, 12),
  (13, 'JK-SCH-0013', 'Improving Infant & Young Child Feeding Scheme', NULL, 'improving-infant-young-child-feeding-scheme', NULL, 'National', NULL, 1, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, '1. Infants and young children up to the age of 2 years.\n2. Pregnant and lactating women as primary caregivers.\n3. The scheme generally targets families from economically weaker sections or marginalized communities', '1. Proof of identity for the mother or caregiver (e.g., Aadhaar card).\n2. Birth certificate of the child.\n3. Proof of residence.\n4. Income certificate (if applicable, for accessing specific financial or nutritional support).\n5. Health records or immunization records of the child', 'In-kind / Material', '1. Nutritional Support\n2. Breastfeeding Promotion\n3. Complementary Feeding\n4. Health Monitoring\n5. Counseling and Education', NULL, NULL, NULL, NULL, NULL, 'Offline', '1. Visit the nearest Anganwadi center or Integrated Child Development Services (ICDS) center.\n2. Consult with the Anganwadi worker or ICDS staff to understand the available services and application process.\n3. Submit the necessary documents and complete any required forms as directed by the center', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-women/improving-infant-young-child-feeding/', 'wcdhry.gov.in', NULL, NULL, 'Health Women, Children', 0, 1, 13),
  (14, 'JK-SCH-0014', 'Kishori Shakti Yojana Scheme', NULL, 'kishori-shakti-yojana-scheme', NULL, 'National', NULL, 1, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, '1. Adolescent girls aged 11 to 18 years.\n2. Priority is given to girls from economically weaker sections and marginalized communities.\n3. The scheme generally targets rural and semi-urban areas where access to resources and support may be limited', '1. Proof of age (e.g., birth certificate, school certificate).\n2. Proof of residence.\n3. Identity proof (e.g., Aadhaar card).\n4. Income certificate (for those applying for additional support based on economic status).\n5. Any additional documents as required by the local implementing authority', 'Training', '1. Nutritional Support\n2. Health Services\n3. Educational Support\n4. Skill Development\n5. Awareness Programs', NULL, NULL, NULL, NULL, NULL, 'Offline', '1. Visit the nearest Anganwadi center or Integrated Child Development Services (ICDS) office.\n2. Fill out the application form provided at the center.\n3. Submit the required documents along with the completed application form', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-women/kishori-shakti-yojna/', 'wcdhry.gov.in', NULL, NULL, 'Health, Education, and Skill Development Children', 0, 1, 14),
  (15, 'JK-SCH-0015', 'Scheme for Relief and Rehabilitation of Women Acid Victims', NULL, 'scheme-for-relief-and-rehabilitation-of-women-acid-victims', NULL, 'National', NULL, 26, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, '1. The victim must be a woman who has suffered an acid attack.\n2. The incident must be reported to the police, and an FIR (First Information Report) should be filed.\n3. The compensation is usually provided based on the severity of injuries and impact on the victim’s life', '1. FIR or police complaint copy.\n2. Medical report detailing the injuries sustained.\n3. Identity proof (e.g., Aadhaar card, passport).\n4. Proof of residence.\n5. Bank account details for compensation transfer.\n6. Any other documents as specified by the relevant authorities', 'Training', '1. Financial compensation to cover medical expenses, rehabilitation, and other related costs.\n2. Support for reconstructive surgery and long-term medical treatment.\n3. Assistance with psychological counseling and support services.\n4. Aid for reintegration into society, including vocational training and education if required', NULL, NULL, NULL, NULL, NULL, 'Offline', '1. Report the incident to the police and obtain an FIR.\n2. Contact the District Legal Services Authority (DLSA) or the State Legal Services Authority (SLSA) to apply for compensation.\n3. Submit the necessary documents along with the application form at the relevant legal services authority or district office handling the scheme', NULL, NULL, 0, NULL, NULL, 'https://wcdhry.gov.in/schemes-for-women/scheme-for-relief-and-rehabilitation-of-women-acid-victims/', 'wcdhry.gov.in', NULL, NULL, 'Women\'s Safety Women', 0, 1, 15),
  (16, 'JK-SCH-0016', 'NALSA’s Compensation Scheme for Women Victims/Survivors of Sexual Assault/other Crimes – 2018', NULL, 'nalsa-s-compensation-scheme-for-women-victims-survivors-of-sexual-assault-other-crimes-2018', NULL, 'National', NULL, 26, 3, NULL, NULL, 16, NULL, 'Ministry of Law and Justice', NULL, 'Active', 1, NULL, '‘Woman Victim/ survivor of other crime’ means a woman who has suffered physical or mental injury as a result of any offence mentioned in the attached Schedule including Sections 304 B or Section 80 BNS Section 326A or Section 124 BNS Section 498A IPC or Section 85 BNS (in case of physical injury of the nature specified in the schedule) including the attempts and abetment. ‘Sexual Assault Victims” means female who has suffered mental or physical injury or both as a result of sexual offence including Sections 376 (A) to (E) or Section 64 (A to m) of the Bhartiya Nyaya Sanhita Section 354 (A) to (D), or Sections 65, 66, 67, 68, 69, 70, 71,72,74, 75, 76,77, 78 of the Bhartiya Nyaya Sanhita Section 509 IPC or Section 79 of the Bhartiya Nyaya Sanhita', 'Form ‘I’/First Information Report (FIR) or criminal complaint/Medical Report, Death Certificate,\nwherever applicable, copy of judgment/ recommendation of court if the trial is over', NULL, 'Compensation/immediate first-aid facility or medical benefits/any other interim relief (including interim monetary compensation)', NULL, NULL, NULL, NULL, NULL, 'Offline', 'An application for the award of interim/ final compensation can be filed by the Victim and/or her Dependents or the SHO of the area before concerned SLSA or DLSA. It shall be submitted in Form ‘I’ along with a copy of the First Information Report (FIR) or criminal complaint of which cognizance is taken by the Court and if available Medical Report, Death Certificate, wherever applicable, copy of judgment/ recommendation of court if the trial is over', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Women\'s Safety Women', 0, 1, 16),
  (17, 'JK-SCH-0017', 'Prime Minister\'s National Relief Fund (PMNRF)', 'PMNRF', 'prime-minister-s-national-relief-fund-pmnrf', NULL, 'National', NULL, 31, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'acid attack victims', 'FIR (First Information Report), medical reports, and a written application', NULL, 'Compensation/Free Legal Aid', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'To apply, the survivor or their representative needs to approach the District Legal Services Authority (DLSA) and submit necessary documents like the FIR (First Information Report), medical reports, and a written application. The DLSA evaluates the case and recommends a suitable compensation amount. Survivors can also receive free legal aid to help with the application process. This compensation plays a vital role in helping survivors regain stability and live with dignity after such a traumatic experience', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Compensation and Rehabilitation Universal PMNRF', 0, 1, 17),
  (18, 'JK-SCH-0018', 'E Shram Scheme', NULL, 'e-shram-scheme', NULL, 'National', NULL, 9, 1, NULL, NULL, 4, NULL, 'Ministry of Labour and Employment', NULL, 'Active', 1, NULL, 'Unorganized Workers above 18 with an active Adhaar and Pan card and mobile number linked with Adhaar', 'Adhaar, Pan, active mobile number linked with Adhaar', 'Training', 'Ministry of Labour & Employment has developed eShram portal for creating a National Database of Unorganized Workers (NDUW), which will be seeded with Aadhaar. It will have details of name, occupation, address, occupation type, educational qualification, skill types etc. for optimum realization of their employability and extend the benefits of the social security schemes to them. It is the first-ever national database of unorganised workers including migrant workers, construction workers, gig and platform workers, etc', NULL, NULL, NULL, NULL, NULL, 'Online', 'About e-Shram Portal | e-Shram', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Universal', 0, 1, 18),
  (19, 'JK-SCH-0019', 'Pradhan Mantri Shram Yogi Maan-Dhan Yojana (PM-SYM) (Old Age Protection)', 'PM-SYM', 'pradhan-mantri-shram-yogi-maan-dhan-yojana-pm-sym-old-age-protection', NULL, 'National', NULL, 18, 2, NULL, NULL, 4, NULL, 'Ministry of Labour and Employment', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nUnorganised Workers (working as street vendors, agriculture related work, construction site workers, workers in industries of leather, handloom, mid-day meal, rickshaw or auto wheelers, rag picking, carpenters, fisherman’s etc.\nAge group of 18-40 years\nMonthly income is below Rs.15000 and not a member of EPFO/ESIC/NPS (Govt. funded)', 'Aadhaar card\nSavings bank account or Jan Dhan account details (with IFSC)\nMobile phone number\nFirst month\'s contribution amount', 'Pension', 'The scheme provides a minimum pension of ₹3,000 per month after age 60, with the Central Government contributing an equal amount to your monthly contribution', 3000.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Visit your nearest Common Service Centre (CSC).\nProvide your Aadhaar and bank account details.\nComplete self-certification of eligibility.\nPay the first month\'s contribution.\nSign the auto-debit mandate form for future monthly contributions.\nReceive your pension account details/registration confirmation', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Old Age Protection Elderly PM-SYM', 0, 1, 19),
  (20, 'JK-SCH-0020', 'National Pension Scheme for Traders and The Self-employed Persons (NPS)', 'NPS', 'national-pension-scheme-for-traders-and-the-self-employed-persons-nps', NULL, 'National', NULL, 18, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nShopkeepers or owners who have petty or small shops, restaurants, hotels, real estate brokers etc.\nAge of 18-40 years\nNot covered in EPFO/ESIC/PM-SYM\nAnnual turnover not more then 1.5 Crore in rupees', 'Aadhaar card\nSavings/Jan Dhan bank account details\nIFSC code\nMobile number', 'Pension', 'Under the schemes, beneficiaries are entitled to receive monthly assured pension of Rs.3000/- after attaining the age of 60 years', 3000.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Visit your nearest Common Service Centre (CSC) Complete self-certification of eligibility.\nPay the first month\'s contribution.\nSign the auto-debit mandate for future contributions', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Old Age Protection Elderly NPS', 0, 1, 20),
  (21, 'JK-SCH-0021', 'Pradhan Mantri Jeevan Jyoti Yojana (PMJJBY)', 'PMJJBY', 'pradhan-mantri-jeevan-jyoti-yojana-pmjjby', NULL, 'National', NULL, 2, 2, NULL, NULL, 10, NULL, 'Ministry of Finance', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nIn the age group 18 to 50 years\nHaving Jandhan or saving bank account with Aadhaar.\nAuto-debit from bank account on consent', 'Having Jandhan or saving bank account with Aadhaar', 'Cash Benefit', 'Rs.2 lakh on death due to any cause\nPremium @ Rs.436/- year', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Offline', 'You can enroll through:\n\nYour bank branch\nNet banking/mobile banking (if your bank supports PMJJBY enrollment)\nParticipating post offices', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Insurance Universal PMJJBY', 0, 1, 21),
  (22, 'JK-SCH-0022', 'Pradhan Mantri Suraksha Bima Yojana (PMSBY)', 'PMSBY', 'pradhan-mantri-suraksha-bima-yojana-pmsby', NULL, 'National', NULL, 2, 2, NULL, NULL, 10, NULL, 'Ministry of Finance', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nIn the age group 18 to 70 years\nHaving Jandhan or saving bank account with Aadhaar.\nAuto-debit from bank account on consent', 'Having Jandhan or saving bank account with Aadhaar', 'Insurance Cover', 'The risk coverage under the scheme is Rs. 2 lakh for accidental death and full disability and Rs. 1 lakh for partial disability.\nPremium @ 20/- year', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Offline', 'You can enroll through:\n\nYour bank branch\nBanking correspondent (BC)\nNet banking/mobile banking (if offered by your bank)\nParticipating post offices', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Insurance Universal PMSBY', 0, 1, 22),
  (23, 'JK-SCH-0023', 'Atal Pension Yojana', NULL, 'atal-pension-yojana', NULL, 'National', NULL, 18, 2, NULL, NULL, 4, NULL, 'Ministry of Labour and Employment', NULL, 'Active', 1, NULL, 'Should be an Indian citizen\nBetween the age of 18-40 years\nHaving bank account linked with Aadhaar', 'Having bank account linked with Aadhaar', 'Pension', 'The contributor on his choice, can attain a pension of 1000-5000 rupees, or he can also get an accumulated sum of the pension after his death.\nThe accumulated amount will be given to the spouse or if the spouse is dead as well then to the nominee', NULL, NULL, 'Recurring', NULL, NULL, 'Offline', 'Visit your bank branch or post office.\nFill out the APY enrollment form.\nProvide:\nAadhaar (recommended)\nSavings bank/post office account details\nMobile number\nNominee details\nChoose your desired pension amount (₹1,000–₹5,000).\nAuthorize auto-debit of contributions from your account', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Old Age Protection Elderly', 0, 1, 23),
  (24, 'JK-SCH-0024', 'PDS', NULL, 'pds', NULL, 'National', NULL, 14, 3, NULL, NULL, 8, NULL, 'Ministry of Consumer Affairs, Food and Public Distribution', NULL, 'Active', 1, NULL, 'Should be an Indian citizen\nAll families below the poverty line is eligible.\nAny family which does not have a member between ages 15 and 59 years of age.\nAny family which has a disabled member is also eligible to avail of benefits under Pradhan Mantri Awas Gramin Yojana\nThose who do not have a permanent job and only engage in casual labour', 'Aadhaar card\nProof of residence\nFamily details\nMobile number\nPassport-size photographs (requirements vary by state)', 'In-kind / Material', '35 kg of rice or wheat every month, while a household above the poverty line is entitled to 15 kg of food grain on a monthly basis', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Apply for a ration card through your State Food & Civil Supplies Department.\nComplete Aadhaar and family member verification as required by your state.\nReceive a ration card (physical or electronic).\nCollect your monthly ration from the designated Fair Price Shop', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Food Security Universal', 0, 1, 24),
  (25, 'JK-SCH-0025', 'Pradhan Mantri Awaas Yojana – Gramin (PMAY-G)', 'PMAY-G', 'pradhan-mantri-awaas-yojana-gramin-pmay-g', NULL, 'National', NULL, 15, 3, NULL, NULL, 5, NULL, 'Ministry of Rural Development', NULL, 'Active', 1, NULL, 'Should be an Indian citizen\nAny family including workers, which does not have a member between ages 15 and 59 years of age.\nAny family which has a disabled member is also eligible to avail of benefits under Pradhan Mantri Awas Gramin Yojana\nThose who do not have a permanent job and only engaged in casual labour', 'Aadhaar card\nAadhaar-linked bank account\nMobile number\nLand/property details (where applicable)\nVerification by local authorities/Gram Sabha\nOther documents required by the state government', NULL, 'Assistance provided to the Beneficiary to the tune of 1.2 Lakhs in plain areas and 1.3 Lakhs in Hilly Areas', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Check your eligibility through the PMAY-G system or local Gram Panchayat.\nVisit the Gram Panchayat, Block Development Office, or a Common Service Centre (CSC).\nSubmit the required details and documents.\nYour application is verified by local authorities and the Gram Sabha.\nIf approved, assistance is released in installments directly to your bank account', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Housing Universal PMAY-G', 0, 1, 25);
INSERT INTO `schemes` (`id`, `scheme_code`, `name`, `short_name`, `slug`, `description`, `scheme_level`, `state_id`, `theme_id`, `service_approach_id`, `priority_id`, `feasibility_id`, `ministry_id`, `department_id`, `ministry_name`, `department_name`, `scheme_status`, `active_enrollment`, `launch_year`, `target_group_summary`, `eligibility_summary`, `benefit_type`, `benefit_description`, `benefit_amount`, `benefit_amount_text`, `benefit_mode`, `benefit_frequency`, `benefit_conditions`, `application_mode`, `application_process`, `application_instructions`, `portal_url`, `csc_available`, `physical_office`, `helpline_number`, `source_url`, `source_website`, `last_verified_date`, `verified_by`, `keywords`, `view_count`, `is_active`, `source_row_no`) VALUES
  (26, 'JK-SCH-0026', 'National Social Assistance Programme (NSAP) -Old age Protection', 'NSAP', 'national-social-assistance-programme-nsap-old-age-protection', NULL, 'National', NULL, 18, 3, NULL, NULL, 9, NULL, 'Ministry of Social Justice and Empowerment', NULL, 'Active', 1, NULL, 'Should be an Indian citizen\nAny person who has little or no regular means of subsistence from his/her own source of income or through financial support from family members or other sources', 'Aadhaar card\nAge proof\nBPL card/certificate or proof of eligibility\nBank or post office account details\nPassport-size photograph\nMobile number (if available)', 'Pension', 'Central Contribution @ Rs 300 to Rs 500 for different age group.\nMonthly pension ranges from Rs 1000 to rs 3000/ depending upon state’s contribution', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 'Offline', 'Visit your Gram Panchayat, Block Office, Tehsildar Office, Municipal Office, or designated welfare office.\nSubmit the application form and required documents.\nComplete verification by local authorities.\nIf approved, the pension is credited directly to your bank account through Direct Benefit Transfer (DBT)', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Old Age Protection Elderly NSAP', 0, 1, 26),
  (27, 'JK-SCH-0027', 'Ayushman Bharat-Pradhan Mantri Jan Arogya Yojana (AB-PMJAY)', 'AB-PMJAY', 'ayushman-bharat-pradhan-mantri-jan-arogya-yojana-ab-pmjay', NULL, 'National', NULL, 1, 1, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'Those living in scheduled caste and scheduled tribe households.\nFamilies with no male member aged 16 to 59 years.\nBeggars and those surviving on alms. Elderly above 70 years of age', 'Aadhaar card\nRation card / family ID (if available)\nMobile number\nBasic KYC for verification', 'Insurance Cover', 'Health coverage of Rs. 5 lakhs per family per year for secondary and tertiary care hospitalization free of cost', 500000.0, NULL, 'Recurring', 'Annual', NULL, 'Both', 'Common Service Centre (CSC / Jan Seva Kendra)\nAyushman Bharat hospital help desk\nOnline portal / Ayushman app (BIS system)', NULL, NULL, 1, NULL, NULL, 'https://eshram.gov.in/social-security-welfare-schemes', 'eshram.gov.in', NULL, NULL, 'Health Universal AB-PMJAY', 0, 1, 27),
  (28, 'JK-SCH-0028', 'Health Insurance Scheme for Weavers (HIS)', 'HIS', 'health-insurance-scheme-for-weavers-his', NULL, 'National', NULL, 23, 3, NULL, NULL, 11, NULL, 'Ministry of Textiles', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nThe weaver should be earning at least 50% of his income from handloom weaving\nAll weavers, whether male or female, are eligible to be covered under the “Health Insurance Scheme”', 'Aadhaar card\nWeaver ID / certificate (if available)\nBank account details\nMobile number\nFamily details (for dependent coverage)', 'Insurance Cover', 'The beneficiaries would avail a package of Rs 15,000 that includes both pre-existing diseases and new diseases. The division in terms of disbursement of the amount according to the medical conditions stands as- Maternity benefits (per child for the first two)- Rs 2500, Eye treatment – Rs 75, Spectacles – Rs 250, Domiciliary Hospitalisation- Rs 4000, Ayurvedic/Unnani/Homeopathic/Siddha- Rs 4000, Hospitalization (including pre and post)- Rs 15000, Baby coverage-500, OPD and limit per illness- Rs 7500', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Offline', 'Visit your nearest Common Service Centre (CSC / Jan Seva Kendra)\nProvide:\nAadhaar card\nBank account details\nWeaver identity proof (if available)\nComplete e-KYC verification\nApply through the State Handloom Department / Weaver Card System\nRegister as a certified handloom weaver\nGet included in the official weaver welfare database', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Aid Universal HIS', 0, 1, 28),
  (29, 'JK-SCH-0029', 'Pradhan Mantri Kisan Mandhan Yojana', NULL, 'pradhan-mantri-kisan-mandhan-yojana', NULL, 'National', NULL, 18, 3, NULL, NULL, 7, NULL, 'Ministry of Agriculture and Farmers Welfare', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nFor Small and Marginal Farmers\nEntry Age between 18 to 40 years\nCultivable land up to 2 hectares as per land records of the concerned State/UT', 'Aadhaar card\nBank passbook details\nLandholding documents (Khatauni / land record)', 'Pension', 'Assured pension of Rs. 3000/- month\nVoluntary and Contributory Pension Scheme\nMatching Contribution by the Government of India', 3000.0, NULL, 'Recurring', NULL, NULL, 'Both', 'Visit your nearest Common Service Centre (CSC / Jan Seva Kendra)\nProvide:\nAadhaar card\nBank passbook details\nLandholding documents (Khatauni / land record)\nCSC operator completes online registration and e-KYC\nChoose auto-debit for monthly contribution from bank account', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Old Age Pension Farmers', 0, 1, 29),
  (30, 'JK-SCH-0030', 'Self Employment Scheme for Rehabilitation of Manual Scavengers', NULL, 'self-employment-scheme-for-rehabilitation-of-manual-scavengers', NULL, 'National', NULL, 23, 3, NULL, NULL, 9, NULL, 'Ministry of Social Justice and Empowerment', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nIdentified manual scavengers, one from each family, (as defined in para 2.3.1) would be eligible for One Time Cash Assistance (OTCA) of Rs. 40,000/- or any such amount as OTCA as revised from time to time', 'Aadhaar Card (identity proof)\nProof of Address (Ration Card / Voter ID / Electricity bill, etc.)\nAge Proof (Birth certificate / School certificate / other valid document)\nManual Scavenger Identification Certificate issued by:\nState Government / Urban Local Body / Gram Panchayat\nBank Account Details (copy of passbook with IFSC code)\nPassport-size photographs\nCaste Certificate (if applicable, as per state requirements)\nMobile number linked for communication and verification', 'Scholarship / Fee Support', 'The manual scavenger and the dependents (as defined in para 2.3.2) shall be provided, free of cost, skill training of their choice from the list of such trainings organized by the National Safai Karmacharis Finance and Development Corporation (NSKFDC) from time to time . A monthly stipend of Rs. 3000/-(Rupees three thousand only) or any such amount as may be decided from time to time to shall be remitted by NSKFDC', 3000.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'You generally cannot apply directly like a normal scheme. The process is:\n\nIdentification through government survey / local authority list\nRegistration via State Urban Local Bodies or Gram Panchayat\nAssistance through NSKFDC (National Safai Karamcharis Finance & Development Corporation)\nThen selection for:\ncash assistance\ntraining\nloan/self-employment support', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Aid Universal', 0, 1, 30),
  (31, 'JK-SCH-0031', 'National Safai Karamcharis Finance and Development Corporation (NSKFDC)', 'NSKFDC', 'national-safai-karamcharis-finance-and-development-corporation-nskfdc', NULL, 'National', NULL, 23, 3, NULL, NULL, 9, NULL, 'Ministry of Social Justice and Empowerment', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nPeople involved as Safai karmacharis and manual scavengers', 'Scheme provides financial assistance to the Safai Karamcharis, Manual Scavengers and their dependants through SCAs/RRBs/Nationalized Banks for any viable income generating schemes including sanitation related activities and for education in India and Abroad', 'Scholarship / Fee Support', 'NSKFDC gives low-interest loans through banks/State agencies for income activities such as:\n\nSmall business / shop / vending\nSanitation-related machinery or services\nE-rickshaw / green business\nAny viable self-employment activity/"Skill development training programs\nStipend during training (as per scheme rules)\nAwareness camps and job fairs\nSupport for rehabilitation activities', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Does not give money directly in most cases\nWorks through:\nState Channelising Agencies (SCAs)\nRegional Rural Banks (RRBs)\nNationalised banks', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Aid Universal NSKFDC', 0, 1, 31),
  (32, 'JK-SCH-0032', 'MGNREGA', NULL, 'mgnrega', NULL, 'National', NULL, 10, 3, NULL, NULL, 5, NULL, 'Ministry of Rural Development', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nAny person who is above the age of 18 and resides in rural areas is entitled to apply for work', 'MGNREGA Job Card\nIssued by the Gram Panchayat\nContains family details and work history\nUsed to apply for work and receive wages', 'In-kind / Material', 'Any applicant is entitled to work within 15 days, for as many as he/she has applied, subject to a limit of 100 days per household per year.\nWage rate (220) has been increased and to be incorporated', NULL, NULL, 'Recurring', 'Annual', NULL, 'Offline', 'Visit your Gram Panchayat office\nSubmit application for a Job Card\nProvide basic documents:\nAadhaar card\nAddress proof\nPassport-size photo\nAfter verification, Job Card is issued (usually free of cost)\nThen you can directly demand work anytime', NULL, NULL, 0, NULL, NULL, 'https://eshram.gov.in/employment-schemes', 'eshram.gov.in', NULL, NULL, 'Employment Universal', 0, 1, 32),
  (33, 'JK-SCH-0033', 'Deen Dayal Upadhyay – Gramin Kaushalya Yojana (DDU-GKY)', 'DDU-GKY', 'deen-dayal-upadhyay-gramin-kaushalya-yojana-ddu-gky', NULL, 'National', NULL, 6, 1, NULL, NULL, 5, NULL, 'Ministry of Rural Development', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nBetween the ages of 15 and 35 years, are eligible for the training programs.\nFor women and other vulnerable groups like persons with disabilities, the upper age limit is relaxed to 45 years', 'Identity & Age Proof\n\nAadhaar Card or other government photo ID\nBirth Certificate or proof of date of birth\n\nEligibility/Household Documents (any applicable document)\n\nBPL Card\nMGNREGA Job Card (where eligible)\nRSBY Card\nAntyodaya Anna Yojana (AAY) Card\nBPL PDS Card\nNRLM Self-Help Group membership proof\n\nCategory Certificates (if applicable)\n\nSC/ST Certificate\nDisability Certificate (PwD candidates)\nOther category-related certificates as required by the state authority', 'Training', 'Deen Dayal Upadhyaya Grameen Kaushalya Yojana (DDU-GKY) aims to skill rural youth who are poor and provide them with jobs having regular monthly wages or above the minimum wages', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Both', 'Visit the official DDU-GKY/Kaushal Panjee portal:\nKaushal Panjee Registration Portal\nSelect Candidate Registration.\nChoose New Registration.\nFill in your personal, educational, and contact details.\nUpload the required documents.\nSubmit the application and save the registration/reference number', NULL, NULL, 0, NULL, NULL, 'https://eshram.gov.in/employment-schemes', 'eshram.gov.in', NULL, NULL, 'Skill Development Youth DDU-GKY', 0, 1, 33),
  (34, 'JK-SCH-0034', 'Deen Dayal Updhyaya Antyodaya Yojana (Day)', NULL, 'deen-dayal-updhyaya-antyodaya-yojana-day', NULL, 'National', NULL, 34, 3, NULL, NULL, 5, NULL, 'Ministry of Rural Development', NULL, 'Active', 1, NULL, 'Rural and Urban Poor Households', 'Aadhaar Card\nIdentity proof\nAddress proof\nBank account details\nPassport-size photographs\nIncome/BPL certificate (where applicable)\nSHG-related documents (for group-based benefits)', 'Credit / Subsidy', 'Organizing poor women into Self-Help Groups (SHGs).\nProviding access to bank loans and financial services.\nSkill development and livelihood promotion.\nSupport for entrepreneurship and income-generating activities.\nSpecial focus on vulnerable groups and women\'s economic empowerment./"Urban poor obtain skill training and wage employment.\nIndividuals and groups start micro-enterprises through bank-linked loans.\nUrban homeless access shelters and support services.\nStreet vendors access credit, social security, and livelihood support', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Contact your Gram Panchayat, Block Development Office, or local Self-Help Group federation./Apply through your local Urban Local Body (Municipality/Municipal Corporation)', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Poverty Alleviation Universal', 0, 1, 34),
  (35, 'JK-SCH-0035', 'PM SVANidhi', NULL, 'pm-svanidhi', NULL, 'National', NULL, 9, 3, NULL, NULL, 6, NULL, 'Ministry of Housing and Urban Affairs', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nStreet vendors in possession of Certificate of Vending / Identity Card issued by Urban Local Bodies (ULBs);\nThe vendors, who have been identified in the survey but have not been issued Certificate of Vending / Identity Card', 'Aadhaar Card\nMobile number linked to Aadhaar\nVoter ID/other ID proof (if required)\nCertificate of Vending (CoV), Identity Card, or Letter of Recommendation (LoR)\nBank account details/passbook\nPassport-size photograph (if requested by the lending institution)', 'Credit / Subsidy', 'To facilitate working capital loan up to 10,000.\nTo incentivize regular repayment.\nTo reward digital transactions', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Obtain or verify your CoV/ID Card/LoR through your municipality or Town Vending Committee.\nApply through a participating bank, microfinance institution, or Common Service Centre (CSC).\nSubmit the required documents and complete e-KYC.\nAfter approval, the loan is credited directly to your bank account', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Entrepreneurs', 0, 1, 35),
  (36, 'JK-SCH-0036', 'Pradhan Mantri Kaushal Vikas Yojana (PMKVY)', 'PMKVY', 'pradhan-mantri-kaushal-vikas-yojana-pmkvy', NULL, 'National', NULL, 6, 1, NULL, NULL, 13, NULL, 'Ministry of Skill Development and Entrepreneurship', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\n12th class dropouts or 10th pass students can enroll in PMKVY to develop their skill set.\nApplicable for any candidate of Indian nationality who is of age between 18-45 years', 'Aadhaar Card\nPassport-size photograph\nProof of Date of Birth (10th certificate, birth certificate, etc.)\nEducational qualification certificates/marksheets\nMobile number\nCaste certificate (if applicable)', 'Training', 'Free skill training\nGovernment-recognized certification\nTraining in sectors such as IT, electronics, healthcare, retail, construction, AI, cybersecurity, drones, and more.\nCareer guidance and industry-relevant skills', NULL, NULL, 'In-kind', NULL, NULL, 'Online', 'Register on the official Skill India platform:\nSkill India Digital Portal\nCreate your profile using Aadhaar and mobile number.\nSearch for PMKVY training courses near you or online.\nSelect a training center and course.\nUpload required documents and complete enrollment.\nAttend training and appear for assessment/certification', NULL, NULL, 0, NULL, NULL, 'https://eshram.gov.in/employment-schemes', 'eshram.gov.in', NULL, NULL, 'Skill Development Youth PMKVY', 0, 1, 36),
  (37, 'JK-SCH-0037', 'Prime Minister Employment Generation Programme (PMEGP)', 'PMEGP', 'prime-minister-employment-generation-programme-pmegp', NULL, 'National', NULL, 9, 1, NULL, NULL, 14, NULL, 'Ministry of Micro, Small and Medium Enterprises', NULL, 'Active', 1, NULL, 'Should be an Indian Citizen\nAny individual, above 18 years of age.\nAt least VIII standard pass for projects costing above Rs.10 lakh in the manufacturing sector and above Rs. 5 lakh in the business / service sector', 'Aadhaar Card\nPAN Card\nPassport-size photograph\nProject Report/Business Plan\nEducational qualification certificate (if applicable)\nCaste/Category certificate (if applicable)\nRural area certificate (if applicable)\nSkill development or EDP training certificate (if available)\nBank account details', 'Credit / Subsidy', 'PMEGP (Prime Minister Employment Generation Programme) helps individuals start a new business or micro-enterprise by providing a bank loan with a government subsidy of up to 35% of the project cost. It supports self-employment, entrepreneurship, and job creation in both rural and urban areas', NULL, NULL, NULL, NULL, NULL, 'Both', 'Apply through the official PMEGP portal:\nPMEGP e-Portal\nSelect Individual Application.\nComplete Aadhaar verification.\nFill in personal, project, and bank details.\nUpload required documents.\nSubmit the application.\nAfter scrutiny by KVIC/KVIB/DIC and the bank, the loan proposal is processed', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Universal PMEGP', 0, 1, 37),
  (38, 'JK-SCH-0038', 'Indira Gandhi National Old Age Pension Scheme (IGNOAPS)', 'IGNOAPS', 'indira-gandhi-national-old-age-pension-scheme-ignoaps', NULL, 'National', NULL, 18, 1, NULL, NULL, 9, NULL, 'Ministry of Social Justice and Empowerment', NULL, 'Active', 1, NULL, 'The applicant should be a citizen of India.\nThe applicant should be living Below Poverty Line.\nThe applicant should be at least 60 years of age', 'Aadhaar Card\nAge proof (Birth Certificate, Voter ID, School Certificate, etc.)\nBPL Card / BPL Certificate\nIncome Certificate (if required by the state)\nResidence Proof\nBank Passbook (account linked with Aadhaar)\nPassport-size photographs\nMobile number (for communication)', 'Pension', 'A monthly pension of ₹ 200 up to 79 years and ₹ 500 thereafter', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 'Both', 'One can download UMANG App or visit website https://web.umang.gov.in/web_new/home\nThe citizen can login using mobile number and OTP.\nOnce logged In, citizen can search for NSAP.\nClick on “Apply Online”\nFill the basic details, choose the mode of payment of pension, upload photo and click on “Submit”', NULL, 'https://web.umang.gov.in/web_new/home', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Old Age Protection Elderly IGNOAPS', 0, 1, 38),
  (39, 'JK-SCH-0039', 'Indira Gandhi National Widow Pension Scheme (IGNWPS)', 'IGNWPS', 'indira-gandhi-national-widow-pension-scheme-ignwps', NULL, 'National', NULL, 25, 1, NULL, NULL, 9, NULL, 'Ministry of Social Justice and Empowerment', NULL, 'Active', 1, NULL, 'The applicant must be a widow in the age group of 40-79 years.\nThe applicant should belong to a household living below the poverty line according to the criteria prescribed by the Govt. of India', 'Death Certificate of husband – With the name of the surviving wife(widow).\nBPL Card.\nAge Proof - For age, the birth certificate or school certificate may be relied on. In their absence ration card and EPIC may be considered. If there is no valid document, any Medical Officer of any government hospital may be authorized to issue the age certificate', 'Pension', 'A pension of Rs.300/- per month is provided to Widows between 40 years and 79 years. For persons who are 80 years and above the pension is Rs.500/- per month', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 'Both', 'One can download UMANG App or visit website https://web.umang.gov.in/web_new/home\nThe citizen can login using mobile number and OTP.\nOnce logged In, citizen can search for NSAP.\nClick on “Apply Online”\nFill the basic details, choose the mode of payment of pension, upload photo and click on “Submit”', NULL, 'https://web.umang.gov.in/web_new/home', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Women Empowerment Women IGNWPS', 0, 1, 39),
  (40, 'JK-SCH-0040', 'ABHA', NULL, 'abha', NULL, 'National', NULL, 1, 1, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'Indian Citizen', 'Adhaar card and active phone number linked with Adhaar', 'Insurance Cover', 'Establish unique identity across different healthcare providers within the healthcare ecosystem/Link all healthcare benefits ranging from public health programmes to insurance schemes to your unique ABHA number/Avoid long lines for registration in healthcare facilities across the country/Seamless sign up for PHR (Personal Health Records) applications such as ABDM application for health data sharing', NULL, NULL, NULL, NULL, NULL, 'Both', 'Visit the official ABHA portal:\nABHA Registration Portal\nSelect "Create ABHA Number".\nChoose Aadhaar or Driving Licence.\nVerify using OTP.\nCreate your ABHA address (for example: yourname@abdm).\nDownload or save your ABHA card', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Universal', 0, 1, 40),
  (41, 'JK-SCH-0041', 'JSY (Janani Suraksha Yojana)', NULL, 'jsy-janani-suraksha-yojana', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'Pregnant women from BPL (Below Poverty Line) families.\nSC/ST women.\nDelivery should take place in a government or accredited private health facility to receive institutional delivery benefits.\nIn some states/categories, age and parity conditions may appl', 'Aadhaar Card\nMother and Child Protection (MCP) Card\nBPL Card (if applicable)\nSC/ST Certificate (if applicable)\nBank Account Passbook\nJSY Card / Registration details from the health facility\nMobile Number\nResidence Proof (if required locally)', 'Cash Benefit', 'The assistance amount depends on the state and whether the area is rural or urban. Common benefits include:\n\nCash assistance for institutional delivery.\nSupport through ASHA workers.\nAssistance for eligible home deliveries in certain cases', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Register your pregnancy at the nearest:\nSub-Centre\nPrimary Health Centre (PHC)\nCommunity Health Centre (CHC)\nGovernment Hospital\nObtain an MCP Card and JSY registration.\nAttend antenatal check-ups.\nDeliver at a government or accredited private facility.\nSubmit bank account and Aadhaar details for Direct Benefit Transfer (DBT).\nThe incentive amount is credited directly to the beneficiary\'s bank account after verification', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Women, Minorities', 0, 1, 41),
  (42, 'JK-SCH-0042', 'NFSA (National Food Security Act, 2013)', NULL, 'nfsa-national-food-security-act-2013', NULL, 'National', NULL, 14, 1, NULL, NULL, 8, NULL, 'Ministry of Consumer Affairs, Food and Public Distribution', NULL, 'Active', 1, NULL, 'Priority Household (PHH) or Antyodaya Anna Yojana (AAY) households', 'Aadhaar Card of family members\nProof of residence\nIdentity proof\nMobile number\nPassport-size photographs\nExisting ration card surrender certificate (if transferring from another state/district)\nIncome or eligibility-related documents, where applicable', 'In-kind / Material', 'Highly subsidized food grains through ration shops.\nPHH beneficiaries: 5 kg food grains per person per month.\nAAY households: 35 kg food grains per household per month', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Both', 'Visit the official NFSA portal:\nNFSA Apply for Ration Card\nSelect your State/UT Food Department portal.\nRegister/login on the state portal.\nFill in family details and address details.\nUpload required documents.\nSubmit the application and note the acknowledgment/reference number.\nTrack the application status on the state portal', NULL, NULL, 0, NULL, NULL, 'https://nfsa.gov.in', 'nfsa.gov.in', NULL, NULL, 'Food Security Universal', 0, 1, 42),
  (43, 'JK-SCH-0043', 'UDID (Unique Disability ID) Card', NULL, 'udid-unique-disability-id-card', NULL, 'National', NULL, 20, 1, NULL, NULL, 9, NULL, 'Ministry of Social Justice and Empowerment', NULL, 'Active', 1, NULL, 'Any person with a disability who wishes to obtain:\n\nA disability certificate, or\nA UDID card linked to an existing disability certificate', 'Aadhaar Card (or other identity proof)\nPassport-size photograph\nAddress proof\nDisability-related medical documents/reports\nMobile number\nExisting disability certificate (if already issued)', 'Pension', 'Single national disability identity card.\nEasier access to disability-related schemes and benefits.\nOnline verification of disability certificates.\nReduces the need to carry multiple documents.\nFacilitates access to pensions, scholarships, assistive devices, travel concessions, and other government programs', NULL, NULL, NULL, NULL, NULL, 'Both', 'Visit the official UDID portal:\nUDID Portal Registration Page\nClick "Apply for Disability Certificate & UDID Card".\nCreate an account and fill in the application form.\nUpload the required documents.\nSubmit the application.\nTrack the application status online.\nAttend medical assessment if required by the designated medical authority.\nOnce approved, the disability certificate and UDID card are issued digitally', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Disability Certification PwD/Chronic Diseases', 0, 1, 43),
  (44, 'JK-SCH-0044', 'Pradhan Mantri Ujjwala Yojana (PMUY)', 'PMUY', 'pradhan-mantri-ujjwala-yojana-pmuy', NULL, 'National', NULL, 16, 3, NULL, NULL, 15, NULL, 'Ministry of Petroleum and Natural Gas', NULL, 'Active', 1, NULL, 'A woman of the household.\n\nAt least 18 years old.\n\nBelonging to an eligible poor household (as identified under government criteria).\n\nNot already having an LPG connection in the same household', 'Aadhaar Card\n\nRation Card / Family composition document\n\nBank account details / passbook\n\nAddress proof\n\nPassport-size photograph\n\nMobile number', 'Cash Benefit', 'Free LPG connection for eligible women.\nFinancial assistance for LPG connection setup.\nReduced indoor air pollution and smoke exposure.\nImproved health outcomes for women and children.\nCleaner and safer cooking fuel.\nTime saved from collecting traditional fuels.\nEnhanced convenience in cooking.\nWomen\'s empowerment through ownership of the LPG connection.\nReduced dependence on firewood, coal, and biomass fuels.\nEnvironmental benefits through cleaner energy use.\nAccess to subsidized LPG refills as per government policy', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest LPG distributor (Indane, Bharat Gas, or HP Gas).\n\nAsk for the PMUY application form.\n\nFill in the details and attach the required documents.\n\nSubmit the application.\n\nAfter verification, an LPG connection is sanctioned.\n\nThe beneficiary receives the connection and related support as per the scheme rules', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Energy Women PMUY', 0, 1, 44),
  (45, 'JK-SCH-0045', 'Sukanya Samriddhi Yojana (SSY)', 'SSY', 'sukanya-samriddhi-yojana-ssy', NULL, 'National', NULL, 27, 3, NULL, NULL, 10, NULL, 'Ministry of Finance', NULL, 'Active', 1, NULL, 'The account can be opened in the name of a girl child below 10 years of age.\nThe account may be opened by a parent or legal guardian.\nA maximum of two girl children per family are generally eligible (exceptions apply for twins/triplets)', 'Birth Certificate of the girl child\nAadhaar Card (where applicable)\nIdentity proof of parent/guardian\nAddress proof of parent/guardian\nPassport-size photographs (if required by the bank/post office)', 'Credit / Subsidy', 'Government-backed savings scheme.\nAttractive interest rate notified by the Government from time to time.\nTax benefits under applicable provisions of the Income Tax Act.\nDeposits can be made until the account completes 15 years from opening.\nThe account matures 21 years from the date of opening or upon eligible closure conditions', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Visit a:\nIndia Post post office, or\nAuthorized bank branch offering SSY accounts.\nObtain and fill out the SSY account opening form.\nSubmit the required documents.\nMake the initial deposit (minimum amount as per current scheme rules).\nThe account will be opened, and a passbook will be issued', NULL, NULL, 0, NULL, NULL, 'https://www.nsiindia.gov.in', 'www.nsiindia.gov.in', NULL, NULL, 'Girl Child Empowerment Children SSY', 0, 1, 45),
  (46, 'JK-SCH-0046', 'Swadhar Greh - A Scheme for women in difficult circumstances', NULL, 'swadhar-greh-a-scheme-for-women-in-difficult-circumstances', NULL, 'National', NULL, 26, 2, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, 'Homeless and shelter less BPL', 'Deserted women without social or economic support\nVictims of domestic violence or family disputes\nWomen rendered homeless due to natural disasters\nWomen released from prison without family support\nTrafficked women rescued from exploitation\nWomen affected by HIV/AIDS who lack social and economic support\nOther women in distress who need institutional support and rehabilitation', 'Training', 'Safe shelter/accommodation\nFood and clothing\nMedical care and health services\nPsychological counseling\nLegal aid and guidance\nVocational training and skill development\nEconomic and social rehabilitation support', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Approach the nearest:\nDistrict Women & Child Development Office\nDistrict Social Welfare Office\nOne Stop Centre (OSC)\nPolice Station (for referral in emergency cases)\nSwadhar Greh Home directly\nSubmit the application/referral along with available documents.\nThe authorities verify the case and assess eligibility.\nIf approved, the woman is admitted to a Swadhar Greh and provided support services and rehabilitation assistance', NULL, NULL, 0, NULL, NULL, 'https://transformingindia.mygov.in', 'transformingindia.mygov.in', NULL, NULL, 'Women\'s Safety and Rehabilitation Women', 0, 1, 46),
  (47, 'JK-SCH-0047', 'Scheme for Adolescent Girls (SAG)', 'SAG', 'scheme-for-adolescent-girls-sag', NULL, 'National', NULL, 1, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, 'Out-of-school adolescent girls aged 11–14 years.\nGirls registered with the local Anganwadi Centre', 'Aadhaar Card (if available)\nBirth Certificate/Age Proof\nResidence Proof\nAnganwadi Registration Details\nSchool non-attendance proof (where applicable)', 'Training', 'Nutritional support (Take Home Ration/Hot Cooked Meal, depending on local implementation)\nIron and Folic Acid (IFA) supplementation\nHealth check-ups and referral services\nNutrition and health education\nLife skills education\nGuidance on public services, education, hygiene, and vocational skills', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Visit the nearest Anganwadi Centre (AWC).\nRegister the eligible adolescent girl with the Anganwadi worker.\nSubmit the required documents.\nAfter verification, the beneficiary is enrolled and starts receiving services under the scheme', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health and Education Children SAG', 0, 1, 47),
  (48, 'JK-SCH-0048', 'Rashtriya Krishi Vikas Yojana – Remunerative Approaches for Agriculture and Allied Sector Rejuvenation (RKVY-RAFTAAR)', 'RKVY-RAFTAAR', 'rashtriya-krishi-vikas-yojana-remunerative-approaches-for-agriculture-and-allied-sector-rejuvenation-rkvy-raftaar', NULL, 'National', NULL, 12, 3, NULL, NULL, 7, NULL, 'Ministry of Agriculture and Farmers Welfare', NULL, 'Active', 1, NULL, 'Farmers\nFarmer Producer Organizations (FPOs)\nSelf-Help Groups (SHGs)\nAgri-entrepreneurs and startups\nAgricultural institutions and universities\nState government agencies implementing agricultural projects', 'Aadhaar Card\nIdentity Proof\nAddress Proof\nBank Account Details\nLand ownership/lease documents (for farmer components)\nProject proposal (for startup or infrastructure projects)\nMobile number\nPassport-size photograph', 'Training', 'Agricultural infrastructure development\nFarm machinery support\nCapacity building and training\nIrrigation and watershed development\nPost-harvest management facilities\nStartup incubation, mentoring, and funding support for agri-innovations', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Contact the nearest Agriculture Department office.\nMeet the Agriculture Development Officer (ADO) or District Agriculture Officer.\nSubmit an application with required documents.\nThe proposal is evaluated and approved based on local priorities and fund availability./"Apply through an approved RKVY-RAFTAAR Agri-Business Incubator (R-ABI).\nSubmit an innovation/business proposal.\nParticipate in screening, mentoring, and incubation.\nEligible startups may receive incubation support and funding assistance', NULL, NULL, 0, NULL, NULL, 'https://rkvy.da.gov.in', 'rkvy.da.gov.in', NULL, NULL, 'Agriculture Farmers RKVY-RAFTAAR', 0, 1, 48),
  (49, 'JK-SCH-0049', 'Pradhan Mantri Fasal Bima Yojana (PMFBY)', 'PMFBY', 'pradhan-mantri-fasal-bima-yojana-pmfby', NULL, 'National', NULL, 12, 1, NULL, NULL, 7, NULL, 'Ministry of Agriculture and Farmers Welfare', NULL, 'Active', 1, NULL, 'Farmers growing notified crops in notified areas.\n\nSharecroppers and tenant farmers may also be eligible as per state guidelines', 'Aadhaar Card\nIdentity Proof\nBank Account Passbook\nLand ownership records or cultivation proof\nSowing/Crop details\nMobile Number\nPassport-size photograph', 'Insurance Cover', 'Insurance coverage for notified crops.\nFinancial assistance in case of crop loss due to drought, flood, cyclone, hailstorm, pest attack, disease, and other covered risks.\nStabilizes farmers\' income and encourages continued farming', NULL, NULL, 'Service', NULL, NULL, 'Both', 'Visit the PMFBY portal:\nPMFBY Farmer Registration\nRegister as a farmer.\nEnter land and crop details.\nUpload the required documents.\nPay the applicable premium.\nSubmit the application and save the acknowledgment number', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Agriculture Farmers PMFBY', 0, 1, 49),
  (50, 'JK-SCH-0050', 'National Food Security Mission (NFSM)', 'NFSM', 'national-food-security-mission-nfsm', NULL, 'National', NULL, 12, 3, NULL, NULL, 7, NULL, 'Ministry of Agriculture and Farmers Welfare', NULL, 'Active', 1, NULL, 'Farmers cultivating notified crops under NFSM.\nSmall and marginal farmers are given priority.\nWomen farmers and SC/ST farmers receive earmarked allocations under the scheme guidelines.\nAssistance is generally available up to a specified area limit per season', 'Aadhaar Card\nIdentity Proof\nAddress Proof\nBank Account Details\nLand Ownership Records / Cultivation Proof\nPassport-size Photograph\nMobile Number\nCrop Details and Area under Cultivation', 'Training', 'Distribution of certified and quality seeds.\nCluster demonstrations and technology demonstrations.\nFarm machinery and agricultural implements.\nMicronutrients and soil amendments.\nPlant protection measures.\nTraining and capacity building programs', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Visit the nearest Agriculture Department office.\nContact the Agriculture Development Officer (ADO), Agriculture Extension Officer, or Block Agriculture Officer.\nSubmit the application along with the required documents.\nAfter verification, assistance is provided under the relevant NFSM component', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Agriculture Farmers, Women, Minorities NFSM', 0, 1, 50);
INSERT INTO `schemes` (`id`, `scheme_code`, `name`, `short_name`, `slug`, `description`, `scheme_level`, `state_id`, `theme_id`, `service_approach_id`, `priority_id`, `feasibility_id`, `ministry_id`, `department_id`, `ministry_name`, `department_name`, `scheme_status`, `active_enrollment`, `launch_year`, `target_group_summary`, `eligibility_summary`, `benefit_type`, `benefit_description`, `benefit_amount`, `benefit_amount_text`, `benefit_mode`, `benefit_frequency`, `benefit_conditions`, `application_mode`, `application_process`, `application_instructions`, `portal_url`, `csc_available`, `physical_office`, `helpline_number`, `source_url`, `source_website`, `last_verified_date`, `verified_by`, `keywords`, `view_count`, `is_active`, `source_row_no`) VALUES
  (51, 'JK-SCH-0051', 'Soil Health Card Scheme (SHC)', 'SHC', 'soil-health-card-scheme-shc', NULL, 'National', NULL, 12, 3, NULL, NULL, 7, NULL, 'Ministry of Agriculture and Farmers Welfare', NULL, 'Active', 1, NULL, 'All farmers, including small, marginal, and large farmers.\nIndividual landowners and cultivators can avail of soil testing services', 'Aadhaar Card\nIdentity Proof\nLand ownership records or cultivation proof\nMobile Number\nBank details (if required by the state)', NULL, 'Free or subsidized soil testing.\nPersonalized fertilizer recommendations.\nInformation on soil amendments such as lime, gypsum, and organic manure.\nBetter crop yields and reduced input costs.\nLong-term improvement in soil health', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest Agriculture Department office, Krishi Vigyan Kendra (KVK), or Soil Testing Laboratory.\nSubmit a request for soil testing.\nSoil samples are collected from the farm or brought by the farmer as per guidelines.\nThe sample is tested in an authorized laboratory.\nThe Soil Health Card is generated and issued to the farmer', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Agriculture Farmers SHC', 0, 1, 51),
  (52, 'JK-SCH-0052', 'Pradhan Mantri Krishi Sinchayee Yojana (PMKSY)', 'PMKSY', 'pradhan-mantri-krishi-sinchayee-yojana-pmksy', NULL, 'National', NULL, 13, 3, NULL, NULL, 7, NULL, 'Ministry of Agriculture and Farmers Welfare', NULL, 'Active', 1, NULL, 'Individual farmers.\nFarmer groups and Farmer Producer Organizations (FPOs).\nFarmers owning or cultivating agricultural land.\nEligibility and subsidy rates may vary by state and component', 'Aadhaar Card\nIdentity Proof\nAddress Proof\nLand Ownership Records / Land Lease Documents\nBank Account Details\nPassport-size Photograph\nMobile Number\nDetails of proposed irrigation system/project', NULL, 'Har Khet Ko Pani (HKKP) – Bringing irrigation water to every farm.\nPer Drop More Crop (PDMC) – Promoting efficient irrigation systems.\nWatershed Development – Soil and water conservation in rainfed areas.\nAccelerated Irrigation Benefit Programme (AIBP) – Completion of major and medium irrigation projects', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Visit the nearest Agriculture Department office.\nContact the Agriculture Officer or Block Agriculture Officer.\nSubmit the application with the required documents.\nAfter verification, assistance/subsidy is sanctioned under the relevant PMKSY component', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Irrigation Farmers PMKSY', 0, 1, 52),
  (53, 'JK-SCH-0053', 'National Means-cum-Merit Scholarship Scheme (NMMS / NMMSS)', 'NMMS / NMMSS', 'national-means-cum-merit-scholarship-scheme-nmms-nmmss', NULL, 'National', NULL, 5, 3, NULL, NULL, 3, NULL, 'Ministry of Education', NULL, 'Active', 1, NULL, 'A student must:\n\nBe studying in Class VIII in a Government, Government-aided, or Local Body school.\nHave parental income from all sources not exceeding ₹3.5 lakh per year.\nQualify the State-Level NMMS Examination (MAT and SAT).\nHave secured the minimum marks prescribed by the State/UT in the qualifying examination (usually Class VII)', 'Class VII mark sheet\nIncome Certificate of parents/guardian\nAadhaar Card\nBank Account details\nCaste Certificate (if applicable)\nDisability Certificate (if applicable)\nDomicile Certificate (as required by the State)\nPassport-size photograph', 'Scholarship / Fee Support', '₹12,000 per year (₹1,000 per month) for selected students.\nThe scholarship is awarded from Class IX and can be renewed up to Class XII, subject to eligibility and academic performance', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 'Offline', 'Apply through your school when the State Education Department announces NMMS applications.\nAppear for the State-level NMMS examination', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Children NMMS / NMMSS', 0, 1, 53),
  (54, 'JK-SCH-0054', 'Samagra Shiksha Abhiyan (Samagra Shiksha)', NULL, 'samagra-shiksha-abhiyan-samagra-shiksha', NULL, 'National', NULL, 5, 3, NULL, NULL, 3, NULL, 'Ministry of Education', NULL, 'Active', 1, NULL, 'Students in Government and Government-aided schools.\nTeachers and teacher educators.\nSchools requiring infrastructure and academic support.\nChildren from disadvantaged and vulnerable groups', 'Depending on the benefit component:\n\nSchool admission records\nAadhaar Card (where required)\nCaste Certificate (if applicable)\nDisability Certificate (for inclusive education benefits)\nIncome-related documents (for certain student support components)', 'Training', 'Free textbooks and uniforms for eligible students.\nConstruction of classrooms, toilets, drinking water facilities, and other school infrastructure.\nTeacher recruitment, training, and capacity building.\nInclusive education for children with special needs.\nICT and digital learning initiatives.\nVocational education from secondary classes onwards', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'There is no direct application by students for Samagra Shiksha itself. Benefits are delivered through schools and State Education Departments', NULL, NULL, 0, NULL, NULL, 'https://samagra.education.gov.in', 'samagra.education.gov.in', NULL, NULL, 'Education Children', 0, 1, 54),
  (55, 'JK-SCH-0055', 'National Overseas Scholarship (NOS)', 'NOS', 'national-overseas-scholarship-nos', NULL, 'National', NULL, 5, 1, NULL, NULL, 3, NULL, 'Ministry of Education', NULL, 'Active', 1, NULL, 'Scheduled Castes (SC)\nDenotified, Nomadic and Semi-Nomadic Tribes (DNTs)\nLandless Agricultural Labourers\nTraditional Artisans', 'Aadhaar Card\nCaste Certificate (if applicable)\nIncome Certificate\nEducational certificates and mark sheets\nAdmission/offer letter from a foreign university (as per scheme requirements)\nPassport\nPassport-size photograph\nBank account details\nOther documents specified in the annual guidelines', 'Insurance Cover', 'Tuition fees\nLiving/maintenance allowance\nVisa fees\nMedical insurance\nAirfare and related travel expenses\nOther approved academic expenses', NULL, NULL, NULL, NULL, NULL, 'Both', 'Visit the official NOS portal:\nApply for National Overseas Scholarship\nRegister and create an account.\nFill in the online application form.\nUpload the required documents.\nSubmit the application before the notified deadline.\nTrack application status and results on the portal', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Minorities NOS', 0, 1, 55),
  (56, 'JK-SCH-0056', 'PM CARES for Children Scheme', NULL, 'pm-cares-for-children-scheme', NULL, 'National', NULL, 28, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Children who:\n\nLost both parents due to COVID-19.\nLost a surviving parent due to COVID-19.\nLost a legal guardian/adoptive parent due to COVID-19.\nWere below 18 years of age on the date of death of the parent/guardian.\nWere identified and registered under the scheme within the prescribed period', 'Birth Certificate\nAadhaar Card (if available)\nDeath certificate(s) of parent(s)/guardian indicating COVID-19-related death\nResidence proof\nBank account details (where applicable)\nSchool records\nPassport-size photograph\nAny other documents required by the District Administration', 'Insurance Cover', 'Corpus fund created for each eligible child.\nLump-sum financial support provided when the child reaches 23 years of age.\nMonthly stipend from age 18 to 23 years for personal needs./Admission in nearest Government or Kendriya Vidyalaya school.\nPayment of school fees, uniforms, books, and educational expenses where applicable.\nSupport for higher education through scholarships and educational loans./Coverage under Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana (AB-PMJAY).\nHealth insurance cover of ₹5 lakh per year.\nPremium paid by PM CARES', 500000.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'The scheme is generally administered through the District Administration', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Child Welfare and Protection Children', 0, 1, 56),
  (57, 'JK-SCH-0057', 'Sponsorship under Mission Vatsalya', NULL, 'sponsorship-under-mission-vatsalya', NULL, 'National', NULL, 28, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, 'Children below 18 years of age who are in difficult circumstances, including:\n\nOrphaned children.\nChildren with a single parent.\nChildren whose parents are unable to care for them due to illness, disability, destitution, imprisonment, or other crises.\nChildren rescued from child labour, trafficking, abuse, neglect, or exploitation.\nChildren living in vulnerable families at risk of abandonment.\nChildren affected by natural disasters, conflict, or emergencies', 'Birth Certificate/Age Proof\nAadhaar Card (child and parent/guardian, if available)\nResidence Proof\nIncome Certificate\nBank Account Details of parent/guardian\nDeath Certificate of parent(s) (if applicable)\nMedical records (if applicable)\nSchool certificate/enrollment proof\nChild Welfare Committee (CWC) or District Child Protection Unit (DCPU) assessment documents', 'Cash Benefit', 'Financial assistance of up to ₹4,000 per month per child (subject to state implementation and assessment).\nSupport for:\nEducation expenses\nNutrition\nHealthcare\nClothing and basic needs\nRehabilitation and family strengthening', 4000.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Contact the District Child Protection Unit (DCPU)', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Child Welfare and Protection Children', 0, 1, 57),
  (58, 'JK-SCH-0058', 'Scheme for Care and Support to Victims under Sections 4 & 6 of the POCSO Act, 2012 (Nirbhaya Fund)', NULL, 'scheme-for-care-and-support-to-victims-under-sections-4-6-of-the-pocso-act-2012-nirbhaya-fund', NULL, 'National', NULL, 28, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Minor girl children (below 18 years of age) who are pregnant due to offences under:\n\nSection 4 – Punishment for penetrative sexual assault.\nSection 6 – Punishment for aggravated penetrative sexual assault under the POCSO Act', 'The scheme guidelines emphasize that benefits should not be denied due to lack of documents, and a copy of the FIR is not mandatory for availing support. The responsibility for ensuring FIR registration lies with the authorities', 'Training', 'Prenatal and postnatal healthcare.\nInstitutional delivery services.\nMedical examinations and treatment.\nNutrition support during pregnancy and after childbirth./Trauma counseling.\nMental health support.\nFamily counseling and rehabilitation services./Safe accommodation where required.\nPlacement in appropriate child care institutions if necessary./Legal aid and assistance during investigation and trial.\nSupport persons to assist the child through the judicial process./Continuation of schooling.\nVocational training and skill development where appropriate.\nSocial reintegration support./Financial support for care and rehabilitation needs as per approved norms and case assessment', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Report the case to the police, Special Juvenile Police Unit (SJPU), or Childline/child protection authorities.\nThe child is produced before the Child Welfare Committee (CWC).\nA care plan is prepared by the District Child Protection Unit (DCPU) and relevant authorities.\nMedical, legal, educational, and rehabilitation services are arranged.\nFinancial and support services are provided through the designated implementing agencies', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Child Welfare and Protection Children', 0, 1, 58),
  (59, 'JK-SCH-0059', 'Shakti Sadan', NULL, 'shakti-sadan', NULL, 'National', NULL, 26, 3, NULL, NULL, 1, NULL, 'Ministry of Women and Child Development', NULL, 'Active', 1, NULL, 'Women in difficult circumstances.\nVictims/survivors of trafficking.\nDestitute and abandoned women.\nWidows without support.\nWomen affected by violence or abuse.\nWomen requiring temporary or long-term shelter and rehabilitation', 'Aadhaar Card (if available)\nIdentity Proof\nAddress Proof\nPassport-size photographs\nMedical reports (if applicable)\nPolice report/FIR (for trafficking or violence cases, where applicable)\nCourt orders or referral documents (if any)\nWidow certificate/death certificate of spouse (for widows, if applicable)\nAny referral from:\nOne Stop Centre (OSC)\nPolice Station\nDistrict Administration\nChild Welfare Committee (where relevant)\nNGO or Social Welfare Department', 'Training', 'Safe accommodation and shelter.\nFood and clothing.\nMedical care and health services.\nPsychological counseling.\nLegal aid and support.\nEducation and skill development.\nVocational training and livelihood assistance.\nAssistance in opening bank accounts and accessing social security schemes', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Approach the nearest:\nOne Stop Centre (OSC)\nWomen Helpline (181)\nPolice Station\nDistrict Social Welfare Office\nWomen & Child Development Department\nA referral is made to the nearest Shakti Sadan.\nEligibility and need assessment are conducted.\nAdmission is granted and rehabilitation services begin', NULL, NULL, 0, NULL, '181', NULL, NULL, NULL, NULL, 'Women\'s Safety Women', 0, 1, 59),
  (60, 'JK-SCH-0060', 'National Mental Health Programme (NMHP)', 'NMHP', 'national-mental-health-programme-nmhp', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'Mental health services are available to all citizens through public health facilities', 'For availing treatment under NMHP/DMHP, hospitals may typically ask for:\n\nAadhaar Card or other ID proof\nAddress proof\nMobile number\nPrevious medical records or prescriptions (if available)\nReferral slip (if referred from another facility)\n\nEmergency counseling and Tele-MANAS services generally do not require extensive documentation', 'Service Delivery', 'Free or affordable mental health consultations.\nCounseling and psychological support.\nDiagnosis and treatment of mental illnesses.\nMedicines for mental health conditions through public health facilities.\nDistrict Mental Health Programme (DMHP) services at district hospitals.\nReferral to specialist psychiatric care when needed.\nCommunity awareness and mental health promotion activities.\n24×7 tele-counseling through Tele-MANAS (14416).\nRehabilitation and follow-up support for persons with mental illness.\nMental health services integrated with primary healthcare facilities', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest:\nPrimary Health Centre (PHC)\nCommunity Health Centre (CHC)\nDistrict Hospital\nMedical College Hospital\nAsk for mental health or psychiatry services under the District Mental Health Programme.\nUndergo assessment and receive counseling/treatment./Dial 14416 or 1-800-89-14416 from anywhere in India.\nReceive free tele-counseling and referral support', NULL, NULL, 0, NULL, '14416', NULL, NULL, NULL, NULL, 'Health Universal NMHP', 0, 1, 60),
  (61, 'JK-SCH-0061', 'Janani Shishu Suraksha Karyakram (JSSK)', 'JSSK', 'janani-shishu-suraksha-karyakram-jssk', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'All pregnant women delivering in Government health institutions.\nSick newborns (up to 30 days after birth).\nSick infants (up to 1 year of age) accessing public health facilities', 'Aadhaar Card (if available)\nMother and Child Protection (MCP) Card\nPregnancy registration records\nAny government-issued identity proof (if available)', 'Service Delivery', 'Free normal delivery and Caesarean section (C-section).\nFree medicines and consumables.\nFree diagnostic tests.\nFree blood and blood products, if required.\nFree diet during hospital stay.\nFree transport from home to health facility.\nFree inter-facility transfer (if referred).\nFree drop-back transport from hospital to home.\nFree treatment for sick newborns up to 30 days after birth.\nFree treatment for sick infants up to 1 year of age at public health facilities', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Register pregnancy at the nearest Government health facility.\nVisit a Government hospital/PHC/CHC for delivery or treatment.\nInform hospital staff that you wish to avail JSSK benefits.\nReceive eligible services free of cost', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Women, Children JSSK', 0, 1, 61),
  (62, 'JK-SCH-0062', 'Pradhan Mantri Surakshit Matritva Abhiyan (PMSMA)', 'PMSMA', 'pradhan-mantri-surakshit-matritva-abhiyan-pmsma', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'All pregnant women.\nSpecial focus on women in the 2nd and 3rd trimesters', 'MCP (Mother and Child Protection) Card / ANC Card.\nAadhaar Card or any identity proof (if available).\nPrevious medical records and test reports (if any)', 'In-kind / Material', 'Free comprehensive antenatal check-up\nExamination by doctors, including specialists where available.\nBlood pressure, weight, and pregnancy assessment.\nFree laboratory tests (blood and urine tests).\nScreening for high-risk pregnancies.\nCounseling on nutrition, birth preparedness, and danger signs.\nReferral and follow-up care for high-risk pregnancies.\nEarly detection and management of pregnancy complications', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest Government health facility\nCarry your ANC/MCP card and relevant medical records.\nRegister for PMSMA services.\nReceive free antenatal check-up and counseling', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Women PMSMA', 0, 1, 62),
  (63, 'JK-SCH-0063', 'Rashtriya Bal Swasthya Karyakram (RBSK)', 'RBSK', 'rashtriya-bal-swasthya-karyakram-rbsk', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'Newborns (0–6 weeks)\nChildren (6 weeks–6 years) attending Anganwadi Centres\nSchool-going children (6–18 years) in Government and Government-aided schools', 'Birth Certificate (if available)\nAadhaar Card (if available)\nSchool ID or Anganwadi registration details\nHealth records/MCP Card (if available)', 'Cash Benefit', 'Free health screening for children from birth to 18 years.\nEarly identification of health conditions under the 4 Ds:\nDefects at Birth\nDeficiencies\nDiseases\nDevelopmental Delays & Disabilities\nFree medical examinations and diagnostic services.\nReferral to specialized healthcare facilities when required.\nFree treatment and surgical interventions for identified conditions.\nEarly intervention services for developmental delays and disabilities.\nFollow-up care and monitoring', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Health screening is conducted at:\nPublic health facilities\nAnganwadi Centres\nGovernment and Government-aided schools\nMobile Health Teams conduct regular screenings.\nChildren identified with health conditions are referred for further diagnosis and treatment.\nEligible children receive free treatment and follow-up care', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Children RBSK', 0, 1, 63),
  (64, 'JK-SCH-0064', 'Rashtriya Kishore Swasthya Karyakram (RKSK)', 'RKSK', 'rashtriya-kishore-swasthya-karyakram-rksk', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'Adolescents aged 10–19 years.\nBoth boys and girls', 'No specific documents are generally required for counseling and basic services.\nAadhaar Card or school ID may be requested for certain services or referrals', 'Training', 'Free adolescent-friendly health services and counseling.\nNutrition counseling and prevention of anemia.\nMenstrual health and hygiene support.\nSexual and reproductive health education and counseling.\nMental health counseling and psychosocial support.\nSubstance abuse prevention and counseling.\nInformation on prevention of injuries and violence.\nScreening and referral for health issues.\nPeer education and life-skills education programmes.\nAccess to Adolescent Friendly Health Clinics (AFHCs)', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest Adolescent Friendly Health Clinic (AFHC), PHC, CHC, or District Hospital.\nParticipate in school-based or community-based adolescent health programmes.\nAccess counseling, health screening, and referral services free of cost', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Children, Youth RKSK', 0, 1, 64),
  (65, 'JK-SCH-0065', 'National Programme for Prevention and Control of Non-Communicable Diseases (NP-NCD)', 'NP-NCD', 'national-programme-for-prevention-and-control-of-non-communicable-diseases-np-ncd', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'All citizens, especially adults aged 30 years and above for population-based screening.\nIndividuals at risk of or suffering from NCDs', 'Aadhaar Card or any identity proof (if available).\nABHA ID (if available).\nPrevious medical records/reports (if any)', 'Cash Benefit', 'Free screening for diabetes, hypertension, and common cancers.\nEarly detection and diagnosis of NCDs.\nFree treatment and follow-up services at government health facilities.\nRegular monitoring of blood pressure and blood sugar.\nHealth counseling on diet, exercise, and lifestyle modification.\nReferral services for specialized treatment when required.\nCommunity-based screening for adults aged 30 years and above.\nAwareness and prevention programmes for NCDs.\nAccess to NCD clinics at District Hospitals and Community Health Centres', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest Health & Wellness Centre (HWC), PHC, CHC, or District Hospital.\nUndergo screening for NCDs.\nReceive counseling, diagnosis, treatment, and follow-up services.\nIf necessary, get referred to higher-level facilities for specialized care', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Universal NP-NCD', 0, 1, 65),
  (66, 'JK-SCH-0066', 'National Programme for Palliative Care (NPPC)', 'NPPC', 'national-programme-for-palliative-care-nppc', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'Patients suffering from:\n\nCancer\nAdvanced chronic diseases\nTerminal illnesses\nSevere debilitating conditions requiring palliative care', 'Aadhaar Card or any identity proof (if available)\nMedical records/prescriptions\nReferral documents (if applicable)\nABHA ID (if available)', 'Service Delivery', 'Free or affordable palliative care services.\nPain relief and symptom management.\nHome-based and community-based palliative care support.\nCounseling and psychosocial support for patients and families.\nEnd-of-life care services.\nReferral to specialized palliative care centres.\nSupport for patients with cancer, advanced chronic diseases, and terminal illnesses', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest Government Hospital, District Hospital, Medical College, or Health & Wellness Centre.\nConsult a doctor for assessment.\nIf eligible, receive palliative care services or referral to a specialized palliative care unit.\nFollow-up care and counseling are provided as required', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health PwD/Chronic Diseases NPPC', 0, 1, 66),
  (67, 'JK-SCH-0067', 'National TB Elimination Programme (NTEP)', 'NTEP', 'national-tb-elimination-programme-ntep', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'Any person diagnosed with Tuberculosis (TB).\nPresumptive TB patients requiring testing and diagnosis.\nDrug-sensitive and drug-resistant TB patients', 'Aadhaar Card or any identity proof (preferred but not mandatory for treatment).\nMedical records/test reports.\nBank account details (for DBT benefits).\nMobile number (if available)', 'Cash Benefit', 'Free TB screening and testing.\nFree chest X-ray and diagnostic services (as per guidelines).\nFree TB medicines for drug-sensitive and drug-resistant TB.\nFree treatment and follow-up care.\nNutritional support through Nikshay Poshan Yojana.\nDirect Benefit Transfer (DBT) for eligible TB patients.\nContact tracing and screening of family members.\nCounseling and treatment adherence support.\nFree treatment for multidrug-resistant (MDR) and extensively drug-resistant (XDR) TB.\nCommunity-based TB care and support services', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest Health & Wellness Centre, PHC, CHC, District Hospital, or Government-recognized TB centre.\nUndergo TB screening and diagnostic testing.\nIf diagnosed, enroll under NTEP through the Nikshay system.\nReceive free medicines, treatment, nutritional support, and follow-up care', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health PwD/Chronic Diseases NTEP', 0, 1, 67),
  (68, 'JK-SCH-0068', 'National AIDS Control Programme (NACP)', 'NACP', 'national-aids-control-programme-nacp', NULL, 'National', NULL, 1, 3, NULL, NULL, 2, NULL, 'Ministry of Health and Family Welfare', NULL, 'Active', 1, NULL, 'Any individual seeking HIV counselling and testing.\nPeople diagnosed with HIV who require free ART and related services.\nPregnant women, key populations, and individuals at risk of HIV infection are also eligible for programme services', 'Aadhaar Card or any valid government photo ID (if available)\nAddress proof (if available)\nMobile number\nHIV-positive test report (or confirmation through the government testing facility)\nReferral slip (if referred from another health facility)', 'Service Delivery', 'HIV counselling and testing through Integrated Counselling and Testing Centres (ICTCs).\nAntiretroviral Therapy (ART) for People Living with HIV (PLHIV) to suppress the virus and improve quality of life.\nLaboratory investigations, including CD4 count and viral load testing, for monitoring treatment.\nPrevention of Parent-to-Child Transmission (PPTCT) services for pregnant women living with HIV.\nScreening and treatment of opportunistic infections and management of sexually transmitted infections (STIs).\nAdherence counselling, psychosocial support, and follow-up care to ensure successful treatment.\nFree condoms and HIV prevention services for key and vulnerable populations.\nSafe blood transfusion services through strengthened blood banks.\nLinkage to social welfare schemes and community support services through NACO and State AIDS Control Societies (SACS), wherever applicable', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest Integrated Counselling and Testing Centre (ICTC), government hospital, or designated ART Centre.\nRegister for confidential HIV counselling and testing.\nIf diagnosed with HIV, you will be referred to an ART Centre for registration and clinical assessment.\nSubmit the required identification and contact details (where applicable).\nAfter enrolment, receive free antiretroviral medicines, regular follow-up, laboratory investigations, counselling, and adherence support under the programme', NULL, NULL, 0, NULL, NULL, 'https://naco.gov.in/nacp', 'naco.gov.in', NULL, NULL, 'Health PwD/Chronic Diseases NACP', 0, 1, 68),
  (69, 'JK-SCH-0069', 'Rehabilitation Treatment for the Disabled', NULL, 'rehabilitation-treatment-for-the-disabled', NULL, 'State', 23, 1, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Resident of Meghalaya.\nPerson with a disability requiring rehabilitation or medical treatment.\nUnable to afford the cost of treatment', 'Disability Certificate.\nAadhaar Card or any valid government-issued photo ID.\nProof of residence in Meghalaya.\nMedical records/prescription or treatment recommendation.\nIncome certificate (if required).\nBank account details.\nPassport-size photographs', 'Cash Benefit', 'Financial assistance for medical treatment and rehabilitation.\nSupport for treatment within Meghalaya or outside the state, where required.\nAssistance to economically disadvantaged persons with disabilities who are unable to bear treatment co', NULL, NULL, NULL, NULL, NULL, 'Both', 'Obtain the application form from the District Social Welfare Officer (DSWO) or download it from the Meghalaya Government portal.\nComplete the application form and attach the required documents.\nSubmit the application to the District Social Welfare Officer of your district.\nThe application is verified by the Social Welfare Department, and eligible beneficiaries receive financial assistance', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health PwD/Chronic Diseases', 0, 1, 69),
  (70, 'JK-SCH-0070', 'Implementation of Disability Act – Book Grant, Uniform Grant & Unemployment Allowance for Persons with Disabilities', NULL, 'implementation-of-disability-act-book-grant-uniform-grant-unemployment-allowance-for-persons-with-disabilities', NULL, 'State', 23, 5, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Meghalaya.\nMust possess a valid Disability Certificate issued by the competent authority.\nFor Book, Uniform, and Conveyance Grants: Applicant should be a student with a disability enrolled in a recognized educational institution.\nFor Unemployment Allowance: Applicant should be an unemployed person with a disability and meet the conditions prescribed by the Social Welfare Department', 'Duly filled application form.\nDisability Certificate.\nAadhaar Card or any valid government-issued photo ID.\nProof of residence in Meghalaya.\nRecent passport-size photographs.\nBank account details/passbook.\nFor student benefits: Bonafide certificate or admission certificate from the educational institution.\nFor unemployment allowance: Employment Exchange Registration Certificate (where applicable) and any other documents prescribed by the department', 'Cash Benefit', 'Book Grant for students with disabilities to purchase books and study materials.\nUniform Grant for eligible school-going students with disabilities.\nConveyance Allowance to support transportation to educational institutions.\nUnemployment Allowance for eligible unemployed persons with disabilities to provide financial support', NULL, NULL, 'In-kind', NULL, NULL, 'Both', 'Obtain the prescribed application form from the District Social Welfare Officer (DSWO) or download it from the Meghalaya Social Welfare Department website.\nComplete the application form and attach all required supporting documents.\nSubmit the application to the District Social Welfare Officer of the concerned district.\nAfter verification and approval by the Social Welfare Department, eligible beneficiaries receive the applicable grant or allowance', NULL, NULL, 0, NULL, NULL, 'https://meghalaya.gov.in/index.php/schemes/content/15648', 'meghalaya.gov.in', NULL, NULL, 'Education and Livelihood PwD/Chronic Diseases', 0, 1, 70),
  (71, 'JK-SCH-0071', 'Vocational Training to Persons with Disabilities (PwDs) for Self-Employment', NULL, 'vocational-training-to-persons-with-disabilities-pwds-for-self-employment', NULL, 'State', 23, 9, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Meghalaya.\nMust be a person with a disability possessing a valid Disability Certificate.\nShould be willing to undergo vocational training for self-employment', 'Duly filled application form.\nDisability Certificate.\nAadhaar Card or any valid government-issued photo ID.\nProof of residence in Meghalaya.\nRecent passport-size photographs.\nBank account details (for stipend, if applicable)', 'Scholarship / Fee Support', 'Free vocational training in various trades for persons with disabilities.\nStipend during the training period.\nSkill development to support self-employment and sustainable livelihoods.\nTraining delivered through recognized voluntary organizations in district headquarters', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Obtain the application form from the District Social Welfare Officer (DSWO) of your district.\nComplete the application form and attach the required documents.\nSubmit the application to the DSWO Office.\nEligible applicants are enrolled in vocational training programmes conducted through approved voluntary organizations and receive the training stipend, where applicable', NULL, NULL, 0, NULL, NULL, 'https://meghalaya.gov.in/index.php/schemes/content/15646', 'meghalaya.gov.in', NULL, NULL, 'Livelihood PwD/Chronic Diseases', 0, 1, 71),
  (72, 'JK-SCH-0072', 'Scholarship to Physically Disabled Students', NULL, 'scholarship-to-physically-disabled-students', NULL, 'State', 23, 5, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Meghalaya.\nMust be a student with a disability enrolled in a recognized school, college, or university.\nMust possess a valid Disability Certificate/UDID Card.\nThe scholarship is available for students pursuing education from pre-primary to postgraduate/university level', 'Duly filled application form.\nDisability Certificate or UDID Card.\nAadhaar Card or any valid government-issued photo ID.\nProof of residence in Meghalaya.\nBonafide/Admission Certificate from the educational institution.\nLatest mark sheet (for renewal, where applicable).\nPassport-size photographs.\nBank account details/passbook', 'Scholarship / Fee Support', 'Monthly scholarship for students with disabilities pursuing education from pre-primary to university level.\nScholarship rates vary depending on the level of education and whether the student is a day scholar or hosteller.\nReader\'s allowance is provided to visually impaired students from Class IX onwards.\nState awards are also available for meritorious students with disabilities', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Obtain the application form from the Office of the District Social Welfare Officer (DSWO) in your district.\nComplete the application form and attach all required documents.\nSubmit the application to the DSWO Office.\nAfter verification by the Social Welfare Department, eligible students receive the scholarship through the prescribed payment mechanism', NULL, NULL, 0, NULL, NULL, 'https://meghalaya.gov.in/index.php/schemes/content/15645', 'meghalaya.gov.in', NULL, NULL, 'Education PwD/Chronic Diseases', 0, 1, 72),
  (73, 'JK-SCH-0073', 'Training Centre for Self-Employment for Women', NULL, 'training-centre-for-self-employment-for-women', NULL, 'State', 23, 9, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Women aged 15–45 years.\nResidents of Meghalaya.\nWomen in need of care and protection, including destitute women, widows, deserted women, single parents, orphan girls, and women from poor households.\nSelection is made by a committee based on prescribed eligibility criteria', 'Duly filled application form.\nProof of age (Birth Certificate/School Certificate/Aadhaar).\nAadhaar Card or any valid government-issued photo ID.\nProof of residence in Meghalaya.\nRecent passport-size photographs.\nIncome certificate (if applicable).\nDocuments supporting eligibility (e.g., widow/deserted certificate or recommendation from a recognized organization, where applicable)', 'Scholarship / Fee Support', 'Free vocational training in tailoring, knitting, embroidery, weaving, and other trades.\nMonthly stipend during the training period.\nPractical and theoretical skill development for self-employment and sustainable livelihoods.\nOpportunity to become economically independent through income-generating activities', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Obtain the application form from the Office of the Superintendent, Training Centre for Self-Employment for Women in Need of Care and Protection.\nComplete the application form and attach the required documents.\nSubmit the application to the Superintendent of the Training Centre.\nEligible applicants are selected by the Selection Committee and enrolled in the one-year vocational training programme', NULL, NULL, 0, NULL, NULL, 'https://meghalaya.gov.in/index.php/schemes/content/15642', 'meghalaya.gov.in', NULL, NULL, 'Livelihood Women', 0, 1, 73),
  (74, 'JK-SCH-0074', 'Border Areas Scholarship', NULL, 'border-areas-scholarship', NULL, 'State', 23, 5, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of a notified Indo–Bangladesh border village in Meghalaya.\nMust belong to the Scheduled Caste (SC) or Scheduled Tribe (ST) category.\nMust be pursuing a regular post-matric course in a recognized institution within or outside Meghalaya.\nParent/guardian must be an Indian citizen, and the family\'s income should be derived from the border area.\nApplicant should not be employed in any government or private establishment', 'Duly filled application form (Fresh/Renewal).\nProof of residence in a notified border village.\nSC/ST Certificate.\nPrevious examination mark sheet.\nBonafide/Admission Certificate from the educational institution.\nAadhaar Card or other valid photo ID.\nPassport-size photographs.\nBank account details/passbook.\nAny other documents prescribed by the Directorate of Higher & Technical Education', 'Scholarship / Fee Support', 'Annual scholarship/stipend for eligible students pursuing post-matric education up to the degree level.\nStudents can continue to receive this scholarship along with other eligible scholarship schemes, as it is treated as a grant/subsidy', NULL, NULL, NULL, NULL, NULL, 'Online', 'Obtain the Border Areas Scholarship application form from the Directorate of Higher & Technical Education or download it from the Meghalaya Government portal.\nFill in the application form and attach all required documents.\nSubmit the application through the Head of your Educational Institution.\nThe institution forwards the application to the Directorate of Higher & Technical Education, Shillong, after the annual notification is issued', NULL, NULL, 0, NULL, NULL, 'https://meghalaya.gov.in/index.php/schemes/content/37489', 'meghalaya.gov.in', NULL, NULL, 'Education Minorities', 0, 1, 74),
  (75, 'JK-SCH-0075', 'Primary School Scholarship and Upper Primary Scholarship', NULL, 'primary-school-scholarship-and-upper-primary-scholarship', NULL, 'State', 23, 5, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be studying in Class V (for the Primary Scholarship Examination) or Class VIII (for the Upper Primary Scholarship Examination) in a recognized school in Meghalaya.\nStudents from eligible schools across the state may appear for the scholarship examination conducted by DERT.\nSelection is based on merit in the scholarship examination', 'Duly filled application form.\nBonafide certificate from the school.\nSchool enrolment/student identity details.\nRecent passport-size photograph.\nAadhaar Card or any other valid identity document (if required).\nAny additional documents prescribed by DERT or the Sub-Divisional School Education Officer (SDSEO)', 'Scholarship / Fee Support', 'Financial scholarship awarded to meritorious students selected through a state-level scholarship examination.\nScholarship is tenable for three years, subject to good conduct and satisfactory academic progress.\nEncourages academic excellence and prepares students for future competitive examinations', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Apply through your school using the prescribed application form.\nThe school forwards the applications to the Sub-Divisional School Education Officer (SDSEO).\nDERT conducts the Primary and Upper Primary Scholarship Examination at designated examination centres across the state.\nBased on merit, selected students are awarded scholarships by the Directorate of School Education and Literacy (DSEL)', NULL, NULL, 0, NULL, NULL, 'https://meghalaya.gov.in/index.php/schemes/content/37593', 'meghalaya.gov.in', NULL, NULL, 'Education Children', 0, 1, 75);
INSERT INTO `schemes` (`id`, `scheme_code`, `name`, `short_name`, `slug`, `description`, `scheme_level`, `state_id`, `theme_id`, `service_approach_id`, `priority_id`, `feasibility_id`, `ministry_id`, `department_id`, `ministry_name`, `department_name`, `scheme_status`, `active_enrollment`, `launch_year`, `target_group_summary`, `eligibility_summary`, `benefit_type`, `benefit_description`, `benefit_amount`, `benefit_amount_text`, `benefit_mode`, `benefit_frequency`, `benefit_conditions`, `application_mode`, `application_process`, `application_instructions`, `portal_url`, `csc_available`, `physical_office`, `helpline_number`, `source_url`, `source_website`, `last_verified_date`, `verified_by`, `keywords`, `view_count`, `is_active`, `source_row_no`) VALUES
  (76, 'JK-SCH-0076', 'Chief Minister Housing Assistance Programme (CMHAP)', 'CMHAP', 'chief-minister-housing-assistance-programme-cmhap', NULL, 'State', 23, 15, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a bona fide resident of Meghalaya.\nMust be 18 years or older.\nMust belong to:\nEconomically Weaker Section (EWS): Annual family income up to ₹1,00,000; or\nLow Income Group (LIG): Annual family income between ₹1,00,001 and ₹2,00,000.\nMust not own a pucca house in Meghalaya (for LIG house construction assistance).\nMust own land for construction (where applicable).\nNeither the applicant nor spouse should have received housing assistance or a housing loan from the government under a similar scheme', 'Prescribed application form.\nAadhaar Card.\nEPIC (Voter ID) or other valid proof of residence.\nIncome Certificate.\nLand ownership documents (for house construction).\nBank account details/passbook.\nRecent passport-size photographs.\nDeclaration regarding ownership of house and previous housing assistance, if applicable', 'Credit / Subsidy', 'EWS households: Three bundles of 9-foot GCI roofing sheets as an outright grant to improve existing houses.\nLIG households: Financial assistance of up to ₹75,000 under the Credit Linked Subsidy component for construction of a durable house (minimum carpet area of 19.20 sq. m. with at least two rooms).\nHouses are constructed as per government-approved designs, with additional costs met through the beneficiary\'s own contribution, MGNREGS, SRWP, or bank loans, where applicable', 75000.0, NULL, NULL, NULL, NULL, 'Offline', 'Obtain the prescribed application form from the Block Development Officer (BDO), District Housing Officer (DHO), or Inspector of Housing.\nFill in the application form and attach all required documents.\nSubmit the completed application to the concerned BDO/DHO.\nApplications are scrutinized by the Block/Urban Level Housing Selection and Monitoring Committee, and approved beneficiaries receive assistance as per the scheme guidelines', NULL, NULL, 0, NULL, NULL, 'https://meghalaya.gov.in/index.php/schemes/content/37229', 'meghalaya.gov.in', NULL, NULL, 'Housing Universal CMHAP', 0, 1, 76),
  (77, 'JK-SCH-0077', 'Rural Housing Scheme (RHS)', 'RHS', 'rural-housing-scheme-rhs', NULL, 'State', 23, 15, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Rural households in Meghalaya constructing their own houses with their own resources.\nPriority was given to economically weaker and poor families in rural areas', 'Prescribed application form.\nProof of residence in Meghalaya.\nIdentity proof (Aadhaar Card/EPIC or other valid government-issued ID).\nIncome certificate, if required.\nLand ownership or house construction details.\nPassport-size photographs', 'Cash Benefit', 'Under the original RHS, eligible beneficiaries received three bundles of CGI (Corrugated Galvanized Iron) roofing sheets as a grant to complete the roofing of their houses.\nThe scheme benefited over 71,000 rural households before being discontinued and replaced by CMHAP', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Obtain the application form from the Housing Department or the concerned district office.\nComplete the application and attach the required documents.\nSubmit the application to the concerned district housing authority for verification.\nEligible applicants were provided roofing materials under the scheme. New applications are no longer accepted, as the scheme has been replaced by the Chief Minister\'s Housing Assistance Programme (CMHAP)', NULL, NULL, 0, NULL, NULL, 'https://meghalaya.gov.in/index.php/schemes/content/37226', 'meghalaya.gov.in', NULL, NULL, 'Housing Universal RHS', 0, 1, 77),
  (78, 'JK-SCH-0078', 'FOCUS (Farmers\' Collectivization for Upscaling Production and Marketing Systems)', NULL, 'focus-farmers-collectivization-for-upscaling-production-and-marketing-systems', NULL, 'State', 23, 9, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident farmer of Meghalaya.\nMust be a member of a registered Producer Group (PG).\nShould be engaged in agriculture, horticulture, livestock, fisheries, or allied livelihood activities', 'Aadhaar Card or other valid photo ID.\nBank account details.\nProof of residence.\nProducer Group registration/membership details.\nMobile number', 'Cash Benefit', 'One-time mobilization grant of ₹5,000 to each member of a registered Producer Group.\nSupport for value chain development, aggregation, marketing, transportation, farm machinery, and livelihood enhancement.\nCapacity building and technical support for Producer Groups', 5000.0, NULL, 'One-time', 'One-time', NULL, 'Offline', 'Join or form a Producer Group in your village.\nRegister the group through the implementing agency/Block office.\nSubmit the required documents and bank details.\nAfter verification, eligible members receive the financial assistance through Direct Benefit Transfer (DBT)', NULL, NULL, 0, NULL, NULL, 'https://mymeg.meghalaya.gov.in/', 'mymeg.meghalaya.gov.in', NULL, NULL, 'Livelihood Farmers', 0, 1, 78),
  (79, 'JK-SCH-0079', 'FOCUS+', NULL, 'focus', NULL, 'State', 23, 9, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident producer household in Meghalaya.\nAt least one family member should be registered with a Producer Group.\nMust complete registration under the FOCUS+ programme', 'Aadhaar Card.\nBank account details/passbook.\nProof of residence.\nProducer Group registration details.\nMobile number.\nFOCUS+ registration form', 'Cash Benefit', '₹5,000 cash assistance to each eligible producer household under FOCUS+.\nBenefit is generally released in two instalments (₹1,000 upon registration and ₹4,000 after verification).\nAdditional benefit over and above assistance received under the FOCUS scheme', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'In instalments', NULL, 'Offline', 'Register through your Producer Group or designated Block office during the registration period.\nSubmit the required documents and complete FOCUS+ enrolment.\nAfter verification, a FOCUS+ card is issued to eligible beneficiaries.\nFinancial assistance is transferred directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, 'https://mymeg.meghalaya.gov.in/', 'mymeg.meghalaya.gov.in', NULL, NULL, 'Livelihood Farmers', 0, 1, 79),
  (80, 'JK-SCH-0080', 'Megha Health Insurance Scheme (MHIS)', 'MHIS', 'megha-health-insurance-scheme-mhis', NULL, 'State', 23, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Meghalaya.\nAll citizens of Meghalaya are eligible except State and Central Government employees covered under government reimbursement schemes.\nBeneficiaries can check their eligibility on the MHIS portal or at designated enrolment centres', 'Aadhaar Card (if available).\nEPIC (Voter ID), MGNREGA Job Card, Birth Certificate, or any other government-issued photo ID.\nProof of family relationship (such as Ration Card, Headman\'s Certificate, or other government records listing family members).\nMobile number.\nAdditional documents (e.g., Birth Certificate, Marriage Certificate, or Adoption Certificate) for adding new family members', 'Insurance Cover', 'Cashless hospitalization with health insurance coverage of up to ₹5.3 lakh per family per year on a floater basis.\nCovers secondary and tertiary care, including surgeries, critical care, oncology, and several specialized treatments.\nTreatment available at empanelled government and private hospitals within Meghalaya and at empanelled hospitals across India under the AB-PMJAY network.\nCoverage for pre-existing diseases from the start of enrolment, subject to scheme guidelines', 530000.0, NULL, 'Recurring', 'Annual', NULL, 'Both', 'Check eligibility through the MHIS official portal or visit the nearest MHIS enrolment centre.\nSubmit the required identity and family documents for enrolment.\nAfter successful verification, receive the MHIS/AB-PMJAY card.\nTo avail treatment, visit any empanelled hospital and present your MHIS/AB-PMJAY card along with a valid government-issued photo ID for cashless hospitalization', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Universal MHIS', 0, 1, 80),
  (81, 'JK-SCH-0081', 'Chief Minister\'s Disability Pension Scheme', NULL, 'chief-minister-s-disability-pension-scheme', NULL, 'State', 23, 1, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Meghalaya.\nMust be 18–59 years of age.\nMust possess a valid Disability Certificate issued by the competent authority.\nApplicants receiving the Unemployment Allowance from the Social Welfare Department are not eligible under this scheme', 'Duly filled application form.\nDisability Certificate.\nAadhaar Card or any valid government-issued photo ID.\nProof of residence in Meghalaya.\nPassport-size photographs.\nBank account or Post Office account details.\nAge proof (if required)', 'Pension', 'Monthly pension of ₹500 per eligible beneficiary.\nPension is disbursed quarterly through the beneficiary\'s bank account or post office account.\nBeneficiaries are issued a Pension Card for receiving pension payments', 500.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Obtain the application form from the District Social Welfare Officer (DSWO) or the Child Development Project Officer (CDPO) of the Social Welfare Department.\nComplete the application form and attach all required documents.\nSubmit the application to the DSWO/CDPO for verification.\nUpon approval, a Pension Card is issued, and the pension is credited quarterly to the beneficiary\'s bank or post office account', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health PwD/Chronic Diseases', 0, 1, 81),
  (82, 'JK-SCH-0082', 'CM ELEVATE', NULL, 'cm-elevate', NULL, 'State', 23, 9, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Meghalaya.\nIndividual applicants must be 18–58 years of age.\nMust be eligible for a bank loan and not be a loan defaulter.\nShould not have any pending criminal or legal case.\nRegistered entities (societies, cooperatives, companies) and recognized groups such as SHGs, Village Organizations (VOs), and Producer Groups (PGs) are also eligible under applicable schemes.\nGenerally, only one applicant per family is eligible under the programme', 'Aadhaar Card, Voter ID, Passport, or Driving Licence (proof of identity and residence).\nBank account details/passbook.\nLand ownership/lease documents (where applicable).\nNo Objection Certificate (NOC) from the village headman (where applicable).\nCertificate from the Block Development Officer (BDO) or other competent authority, where required.\nPAN Card, GST registration, Income Tax Returns, and bank statements (if applicable to the enterprise).\nAny additional documents specified under the selected scheme', 'Credit / Subsidy', 'Financial assistance/subsidy ranging from 35% to 75% of the project cost, depending on the scheme.\nAccess to bank credit and interest subvention under eligible schemes.\nEntrepreneurship training, capacity building, mentoring, and handholding support.\nAssistance for establishing or expanding businesses across multiple sectors', NULL, NULL, NULL, NULL, NULL, 'Both', 'Visit the official CM ELEVATE Portal.\nRegister as an Individual, Registered Entity, or Group (SHG/VO/PG).\nSelect the appropriate scheme based on your proposed enterprise.\nComplete the online application and upload the required documents.\nApplications are evaluated by the implementing department, financing bank, and evaluation committee.\nUpon approval, eligible applicants receive financial assistance, loan support, and capacity-building services under the programme', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Universal', 0, 1, 82),
  (83, 'JK-SCH-0083', 'Chief Minister\'s Social Assistance Scheme (CMSAS', NULL, 'chief-minister-s-social-assistance-scheme-cmsas', NULL, 'State', 23, 23, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'For Single Mothers\nMust be a resident of Meghalaya.\nMust be a single mother (widowed, divorced, abandoned, or unmarried with dependent children).\nMust satisfy the eligibility criteria prescribed by the Social Welfare Department.\nFor Infirm Persons\nMust be a resident of Meghalaya.\nMust be medically certified as infirm and unable to earn a livelihood.\nMust not be receiving similar benefits under another government pension scheme', 'Duly filled application form.\nAadhaar Card or proof of Aadhaar enrolment (Aadhaar authentication is required where applicable).\nProof of residence.\nBank account details/passbook.\nRecent passport-size photographs.\nCategory-specific documents:\nDeath certificate/divorce decree/abandonment certificate (for single mothers, where applicable).\nMedical certificate issued by a competent medical authority (for infirm persons)', 'Pension', 'Monthly financial assistance (pension) to eligible beneficiaries.\nSupport is provided under categories such as:\nPension for Single Mothers\nPension for Infirm Persons\nPension is credited directly to the beneficiary\'s bank account', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Both', 'Visit the Meghalaya State Public Services Delivery Commission (MSPSDC) online services portal or the nearest District Social Welfare Office (DSWO).\nComplete the application form and upload or attach the required documents.\nSubmit the application for verification by the Social Welfare Department.\nUpon approval, the pension is sanctioned and transferred directly to the beneficiary\'s bank account', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Women, PwD/Chronic Diseases', 0, 1, 83),
  (84, 'JK-SCH-0084', 'Pre-Matric Scholarship Scheme', NULL, 'pre-matric-scholarship-scheme', NULL, 'State', 34, 5, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a domicile of Uttar Pradesh.\nMust be studying in Class IX or X in a recognized school.\nMust belong to an eligible category (SC, ST, OBC, General/EWS, or Minority) under the respective scholarship scheme.\nMust satisfy the prescribed annual family income limit.\nMust have an Aadhaar-linked bank account for DBT', 'Aadhaar Card.\nDomicile Certificate.\nIncome Certificate.\nCaste Certificate (where applicable).\nPrevious year\'s mark sheet.\nCurrent school admission/enrolment certificate.\nAadhaar-linked bank account/passbook.\nPassport-size photograph.\nMobile number and email ID', 'Scholarship / Fee Support', 'Financial assistance for educational expenses, including maintenance allowance and other admissible school-related costs.\nScholarship amount is transferred directly to the student\'s Aadhaar-linked bank account through Direct Benefit Transfer (DBT).\nScholarship amount varies depending on the student\'s category and the applicable departmental scheme', NULL, NULL, NULL, NULL, NULL, 'Both', 'Visit the official Uttar Pradesh Scholarship & Fee Reimbursement Portal (Saksham).\nRegister as a Fresh or Renewal applicant.\nFill in the online application form and upload the required documents.\nSubmit the application online and print a copy.\nSubmit the signed application along with supporting documents to your school for verification.\nAfter verification by the institution and the concerned department, the scholarship amount is credited to the student\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Children, Youth', 0, 1, 84),
  (85, 'JK-SCH-0085', 'Post-Matric Scholarship Scheme', NULL, 'post-matric-scholarship-scheme', NULL, 'State', 34, 5, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a domicile of Uttar Pradesh.\nMust be studying in Class XI or above (Intermediate, UG, PG, Diploma, ITI, Professional courses) in a recognized institution.\nMust belong to an eligible category (SC, ST, OBC, General/EWS, or Minority).\nAnnual family income should generally not exceed:\n₹2,50,000 for SC/ST students.\n₹2,00,000 for General, OBC, and Minority students.\nMust have an Aadhaar-linked bank account', 'Aadhaar Card.\nDomicile Certificate.\nIncome Certificate.\nCaste Certificate (where applicable).\nPrevious qualifying examination mark sheet.\nAdmission/Bonafide Certificate from the institution.\nFee receipt.\nAadhaar-linked bank passbook.\nPassport-size photograph.\nMobile number and email ID', 'Scholarship / Fee Support', 'Scholarship for maintenance and educational expenses.\nReimbursement of tuition and other admissible fees as per scheme guidelines.\nDirect Benefit Transfer (DBT) of the scholarship amount to the student\'s Aadhaar-linked bank account.\nAvailable for students belonging to SC, ST, OBC, General (EWS), and Minority categories under the respective departmental schemes', NULL, NULL, NULL, NULL, NULL, 'Both', 'Visit the official Uttar Pradesh Scholarship & Fee Reimbursement Portal (Saksham).\nRegister as a Fresh or Renewal applicant.\nComplete the online application form and upload the required documents.\nSubmit the application online and print the completed form.\nSubmit the signed application and supporting documents to your educational institution for verification.\nAfter verification by the institution and the concerned department, the scholarship amount is transferred directly to the student\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Youth, Minorities', 0, 1, 85),
  (86, 'JK-SCH-0086', 'Old Age Pension Scheme (Vridhavastha Pension Yojana)', NULL, 'old-age-pension-scheme-vridhavastha-pension-yojana', NULL, 'State', 34, 18, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Uttar Pradesh.\nMust be 60 years of age or above.\nAnnual family income should not exceed:\n₹46,080 (Rural)\n₹56,460 (Urban)\nShould not be receiving benefits under any other government pension scheme', 'Aadhaar Card.\nAge proof (Birth Certificate, Aadhaar, Voter ID, etc.).\nDomicile Certificate.\nIncome Certificate.\nAadhaar-linked bank account/passbook.\nPassport-size photograph.\nMobile number', 'Pension', '₹1,000 per month as pension, credited directly to the beneficiary\'s Aadhaar-linked bank account through Direct Benefit Transfer (DBT).\nPension is generally disbursed on a quarterly basis.\nProvides financial support to elderly persons who have no regular source of income', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 'Both', 'Visit the official Uttar Pradesh Integrated Social Pension Portal (SSPY).\nSelect Old Age Pension (Vridhavastha Pension) and click on Apply Online.\nComplete the online application form and upload the required documents.\nSubmit the application and note the registration number for future reference.\nThe application is verified by the concerned authorities, and upon approval, the pension is credited directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, 'https://sspy.up.in/up-old-age-pension/', 'sspy.up.in', NULL, NULL, 'Old Age Protection Elderly', 0, 1, 86),
  (87, 'JK-SCH-0087', 'National Family Benefit Scheme (Rashtriya Parivarik Labh Yojana)', NULL, 'national-family-benefit-scheme-rashtriya-parivarik-labh-yojana', NULL, 'State', 34, 21, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Uttar Pradesh.\nThe deceased must have been the primary/sole earning member of the family.\nThe deceased should have been 18–59 years of age at the time of death.\nThe family must belong to the Below Poverty Line (BPL) category.\nAnnual family income should not exceed:\n₹46,080 (Rural)\n₹56,460 (Urban)\nThe application must be submitted within one year from the date of death', 'Aadhaar Card of the applicant.\nDeath Certificate of the deceased earning member.\nIncome Certificate.\nResidence/Domicile Certificate.\nBPL/Ration Card (where applicable).\nAadhaar-linked bank account/passbook.\nPassport-size photograph.\nMobile number', 'Cash Benefit', 'One-time financial assistance of ₹30,000 to the eligible dependent family member.\nThe amount is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT).\nDesigned to help families meet immediate financial needs after the loss of the main breadwinner', 30000.0, NULL, 'One-time', 'One-time', NULL, 'Both', 'Visit the official National Family Benefit Scheme Portal of the Uttar Pradesh Government.\nRegister as a new applicant and complete Aadhaar verification.\nFill in the online application form and upload the required documents.\nSubmit the application and note the registration number.\nThe application is verified by the concerned authorities, and upon approval, ₹30,000 is transferred directly to the beneficiary\'s bank account through DBT. The state has digitized the process to improve transparency and aims to complete disbursal within 75 days of application', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Insurance Universal', 0, 1, 87),
  (88, 'JK-SCH-0088', 'Chief Minister\'s Mass Marriage Scheme (Mukhyamantri Samuhik Vivah Yojana)', NULL, 'chief-minister-s-mass-marriage-scheme-mukhyamantri-samuhik-vivah-yojana', NULL, 'State', 34, 23, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Both the bride and groom must be permanent residents of Uttar Pradesh.\nThe bride must be 18 years or older, and the groom must be 21 years or older on the date of marriage.\nThe annual family income should be within the limit prescribed by the Government (currently up to ₹3 lakh under the revised guidelines).\nThe scheme is open to all eligible economically weaker families, including SC, ST, OBC, General (EWS), Minority, widows, divorced, and abandoned women seeking marriage or remarriage', 'Aadhaar Cards of the bride and groom.\nProof of age (Birth Certificate, School Certificate, Aadhaar, or Voter ID).\nDomicile/Residence Certificate.\nIncome Certificate.\nBank account details of the bride.\nPassport-size photographs of both applicants.\nCaste Certificate (where applicable).\nWidow/Divorce certificate (if applicable)', 'Cash Benefit', 'Financial assistance of up to ₹1,00,000 per eligible couple (as per the latest revised provisions), which includes:\n₹75,000 transferred directly to the bride\'s bank account.\n₹10,000 for clothes, gifts, and essential household items.\n₹15,000 towards the organization of the mass marriage ceremony.\nMarriage ceremonies are conducted according to the customs and traditions of different religions and communities', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Both', 'Visit the official Mukhyamantri Samuhik Vivah Yojana Portal.\nComplete Aadhaar-based registration and fill in the online application form.\nUpload the required documents and submit the application.\nThe application is verified by the concerned district authorities.\nUpon approval, the couple participates in a government-organized mass marriage ceremony, and the financial assistance is released as per the scheme guidelines', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Women', 0, 1, 88),
  (89, 'JK-SCH-0089', 'Mukhyamantri Abhyuday Scheme', NULL, 'mukhyamantri-abhyuday-scheme', NULL, 'State', 34, 5, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Uttar Pradesh.\nShould be preparing for one of the eligible competitive examinations.\nMust possess the minimum educational qualification required for the respective examination (e.g., Class XII for JEE/NEET, Graduation/Final Year for UPSC/UPPSC).\nPreference is given to meritorious students from economically weaker sections', 'Aadhaar Card.\nDomicile Certificate.\nEducational qualification certificates/mark sheets.\nPassport-size photograph.\nMobile number and email ID.\nCaste Certificate (if applicable).\nIncome Certificate (where applicable)', 'Service Delivery', 'Free online and offline coaching for competitive examinations such as UPSC, UPPSC, JEE, NEET, NDA, CDS, SSC, Banking, TET, and other government recruitment exams.\nFree study materials, e-learning resources, previous years\' question papers, mock tests, and doubt-clearing sessions.\nGuidance and mentoring by IAS, IPS, IFS officers and subject experts.\nMock interviews and career counselling for shortlisted candidates', NULL, NULL, 'In-kind', NULL, NULL, 'Both', 'Visit the official Abhyuday Portal: abhyuday.up.gov.in.\nRegister as a new applicant using your basic details.\nSelect the competitive examination for which coaching is required.\nFill in the online application form and upload the required documents.\nSubmit the application. Eligible candidates are enrolled for online coaching, while selection for offline coaching may be based on an online screening test, depending on the course', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Youth', 0, 1, 89),
  (90, 'JK-SCH-0090', 'Financial Assistance for Scheduled Castes / Scheduled Tribes Affected by Atrocities', NULL, 'financial-assistance-for-scheduled-castes-scheduled-tribes-affected-by-atrocities', NULL, 'State', 34, 29, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must belong to the Scheduled Caste (SC) or Scheduled Tribe (ST) community.\nMust be a victim (or dependent family member of a victim) of an offence registered under the SC/ST (Prevention of Atrocities) Act, 1989 or the Protection of Civil Rights Act, 1955.\nAn FIR must be registered under the relevant provisions of the Act', 'Duly filled application form (where applicable).\nAadhaar Card or other valid identity proof.\nCaste Certificate.\nCopy of the FIR registered under the SC/ST (Prevention of Atrocities) Act.\nMedical report/injury certificate (where applicable).\nDeath certificate (in case of death of the victim).\nBank account details/passbook.\nPassport-size photograph.\nAny other documents required by the District Social Welfare Department', 'Cash Benefit', 'Financial assistance ranging from ₹22,500 to ₹8,25,000, depending on the nature and severity of the offence, as prescribed under the SC/ST (Prevention of Atrocities) Rules.\nRelief is provided in stages linked to the progress of the criminal case (e.g., after FIR, charge sheet, and trial).\nAdditional support may include rehabilitation and other assistance as provided under the Act and Rules', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Offline', 'Report the offence and register an FIR at the nearest police station under the SC/ST (Prevention of Atrocities) Act, 1989.\nApproach the District Social Welfare Office or the designated authority for relief and rehabilitation.\nSubmit the required documents, including the FIR, caste certificate, identity proof, and bank details.\nAfter verification by the district authorities, financial assistance is sanctioned and transferred to the beneficiary\'s bank account in accordance with the prescribed stages of the scheme', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Protection and Safety Minorities', 0, 1, 90),
  (91, 'JK-SCH-0091', 'Grant Scheme for Marriage of Daughters of Scheduled Castes and General Category Poor Persons (Shaadi Anudan Yojana)', NULL, 'grant-scheme-for-marriage-of-daughters-of-scheduled-castes-and-general-category-poor-persons-shaadi-anudan-yojana', NULL, 'State', 34, 23, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Uttar Pradesh.\nThe applicant must belong to the Scheduled Caste (SC) or General Category from an economically weaker family.\nThe bride must be at least 18 years of age and the groom at least 21 years of age.\nAnnual family income should not exceed:\n₹46,080 (Rural)\n₹56,460 (Urban)\nAssistance is available for up to two daughters in a family', 'Aadhaar Card of the applicant and bride.\nDomicile Certificate.\nIncome Certificate.\nCaste Certificate (for SC applicants).\nProof of age of the bride and groom.\nMarriage invitation card or Marriage Certificate (where applicable).\nBank account details/passbook.\nPassport-size photographs.\nMobile number', 'Cash Benefit', 'One-time financial assistance of ₹20,000 per eligible daughter\'s marriage.\nA maximum of two daughters per family are eligible for assistance.\nThe assistance is intended to reduce the financial burden on poor families', 20000.0, NULL, 'One-time', 'One-time', NULL, 'Both', 'Visit the official Shaadi Anudan Portal.\nRegister and complete the online application form.\nUpload the required documents.\nSubmit the application within the prescribed timeline.\nAfter verification by the district authorities, the approved grant is released to the eligible beneficiary', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Minorities, Women', 0, 1, 91),
  (92, 'JK-SCH-0092', 'Mukhyamantri Kanya Sumangala Yojana (MKSY)', 'MKSY', 'mukhyamantri-kanya-sumangala-yojana-mksy', NULL, 'State', 34, 5, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Uttar Pradesh.\nThe girl child must be born on or after 1 April 2019.\nAnnual family income should not exceed ₹3 lakh.\nA maximum of two girl children per family are eligible (with certain exceptions, such as multiple births).\nThe beneficiary must meet the educational or age-related criteria applicable to each stage of the scheme', 'Aadhaar Card of the parents/guardian and the girl child (where available).\nBirth Certificate of the girl child.\nDomicile Certificate.\nIncome Certificate.\nBank account details.\nPassport-size photograph.\nImmunization certificate (for Stage II).\nSchool/college admission certificate (for applicable stages)', 'Cash Benefit', 'Financial assistance of ₹25,000 per eligible girl, disbursed in six stages:\n\nStage I: ₹5,000 – At the birth of a girl child.\nStage II: ₹2,000 – After completion of one year of age and full immunization.\nStage III: ₹3,000 – On admission to Class I.\nStage IV: ₹3,000 – On admission to Class VI.\nStage V: ₹5,000 – On admission to Class IX.\nStage VI: ₹7,000 – On admission to a degree, diploma, or certificate course after passing Class XII (or a two-year diploma)', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Both', 'Visit the official Mukhyamantri Kanya Sumangala Portal: https://mksy.up.gov.in.\nRegister using a mobile number and create a user account.\nComplete the online application form for the relevant stage and upload the required documents.\nSubmit the application online.\nAfter verification by the concerned authorities, the financial assistance is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', NULL, 'https://mksy.up.gov.in', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Children MKSY', 0, 1, 92),
  (93, 'JK-SCH-0093', 'Widow Pension Scheme (Nirashrit Mahila Pension Yojana)', NULL, 'widow-pension-scheme-nirashrit-mahila-pension-yojana', NULL, 'State', 34, 25, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Uttar Pradesh.\nMust be a widow or destitute woman aged 18 years or above.\nMust have no regular source of income.\nAnnual family income should not exceed:\n₹46,080 (Rural)\n₹56,460 (Urban)\nShould not be receiving any other government pension', 'Aadhaar Card.\nHusband\'s Death Certificate.\nDomicile/Residence Certificate.\nIncome Certificate.\nAadhaar-linked bank account/passbook.\nPassport-size photograph.\nMobile number.\nAge proof (if required)', 'Pension', 'Monthly pension of ₹1,000, credited directly to the beneficiary\'s bank account through DBT.\nFinancial support to help meet basic living expenses.\nPension is subject to periodic verification and renewal as per government guidelines', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 'Both', 'Visit the official Uttar Pradesh Social Pension Portal (SSPY).\nSelect Nirashrit Mahila Pension and click Apply Online.\nFill in the application form and upload the required documents.\nSubmit the application and save the registration number for future reference.\nAfter verification by the concerned authorities, the pension is sanctioned and transferred directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Women\'s Welfare Women', 0, 1, 93),
  (94, 'JK-SCH-0094', 'Divyang Pension Scheme (Viklang/Divyang Pension Yojana)', NULL, 'divyang-pension-scheme-viklang-divyang-pension-yojana', NULL, 'State', 34, 23, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Uttar Pradesh.\nMust be 18 years of age or above.\nMust have at least 40% disability, certified by a competent government medical authority.\nShould belong to an economically weaker household and satisfy the prescribed income criteria.\nShould not be receiving another government disability pension', 'Aadhaar Card.\nDisability Certificate (40% or more) or UDID Card (if available).\nDomicile/Residence Certificate.\nIncome Certificate.\nAadhaar-linked bank account/passbook.\nPassport-size photograph.\nMobile number.\nAge proof (if required)', 'Pension', 'Monthly pension of ₹1,000 to eligible beneficiaries.\nPension is transferred directly to the beneficiary\'s Aadhaar-linked bank account through Direct Benefit Transfer (DBT).\nPension is generally disbursed on a quarterly basis', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 'Both', 'Visit the official Uttar Pradesh Social Pension Portal (SSPY).\nSelect Divyang Pension and complete the online application form.\nUpload the required documents and submit the application.\nThe application is verified by the concerned district authorities.\nUpon approval, the pension is credited directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance PwD/Chronic Diseases', 0, 1, 94),
  (95, 'JK-SCH-0095', 'Mukhyamantri Bal Seva Yojana', NULL, 'mukhyamantri-bal-seva-yojana', NULL, 'State', 34, 29, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Uttar Pradesh.\nChild should generally be below 18 years of age (higher education support may continue up to 23 years for eligible students).\nEligible categories include:\nChildren who have lost one or both parents or a legal guardian.\nChildren orphaned due to COVID-19 or other reasons (as per scheme provisions).\nChildren rescued from child labour, child trafficking, child begging, or other exploitative situations.\nChildren restored from Child Care Institutions or Observation Homes.\nWhere one parent is alive, the prescribed annual family income limit must be met', 'Duly filled application form.\nAadhaar Card or valid identity proof.\nBirth Certificate or age proof of the child.\nDeath certificate(s) of parent(s)/legal guardian (where applicable).\nResidence/Domicile Certificate.\nIncome Certificate (where applicable).\nSchool/College enrolment certificate.\nBank account details/passbook.\nPassport-size photographs.\nAny additional documents as prescribed for the relevant category', 'Training', 'Monthly financial assistance of:\n₹4,000 under the COVID category.\n₹2,500 under the General category.\nFree education up to Class XII and admission to residential schools for eligible children.\nOne-time tablet/laptop for eligible students studying in Class IX and above or pursuing vocational education.\nMarriage assistance of ₹1,01,000 for eligible girl beneficiaries (COVID category).\nContinued financial support for eligible students pursuing higher education up to 23 years of age under prescribed conditions.\nRehabilitation support for children rescued from child labour, child trafficking, child begging, and those restored from Child Care Institutions', NULL, 'Multiple amounts specified (see benefit description)', 'Both', 'Monthly', NULL, 'Both', 'Visit the Mukhyamantri Bal Seva Yojana online portal or obtain the application form from the District Probation Office.\nComplete the application form and attach the required documents.\nSubmit the application online or through the Gram Panchayat/Block Office (rural areas) or Tehsil/District Probation Office (urban areas).\nThe application is verified by the concerned authorities and approved by the District Level Committee.\nUpon approval, benefits are transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Protection and Safety Children', 0, 1, 95),
  (96, 'JK-SCH-0096', 'Mukhyamantri Krishak Durghatna Kalyan Yojana', NULL, 'mukhyamantri-krishak-durghatna-kalyan-yojana', NULL, 'State', 34, 23, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Uttar Pradesh.\nMust be a farmer aged 18–70 years.\nEligible beneficiaries include:\nLand-owning farmers (Khatedar/Co-khatedar).\nTenant farmers/sharecroppers (Bataidar).\nLeaseholders and eligible farmer family members as per scheme guidelines.\nThe accident must fall under the covered categories specified by the scheme', 'Duly filled application form.\nAadhaar Card.\nResidence/Domicile Certificate.\nLand records (Khatauni) or proof of tenancy/sharecropping, where applicable.\nBank account details/passbook.\nDeath Certificate (in case of death).\nDisability Certificate or medical report (in case of disability).\nFIR, post-mortem report, or Panchnama, where applicable.\nPassport-size photograph', 'Cash Benefit', '₹5 lakh in case of accidental death.\n₹5 lakh for permanent total disability.\n₹2.5 lakh for permanent partial disability (as prescribed under the scheme).\nCovers accidents such as road accidents, drowning, lightning, snakebite, animal attacks, electrocution, fire, floods, and other notified accidental causes', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Offline', 'Obtain the application form from the Tehsil Office or the office of the District Magistrate/Revenue Department.\nComplete the application form and attach the required documents.\nSubmit the application to the Tehsildar or the designated revenue authority within the prescribed time limit after the accident.\nAfter verification by the district authorities, the approved financial assistance is transferred directly to the beneficiary\'s bank account', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Farmers', 0, 1, 96),
  (97, 'JK-SCH-0097', 'Chief Minister Jan Arogya Abhiyan (Mukhyamantri Jan Arogya Abhiyan – MMJAA)', NULL, 'chief-minister-jan-arogya-abhiyan-mukhyamantri-jan-arogya-abhiyan-mmjaa', NULL, 'State', 34, 1, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Uttar Pradesh.\nFamily must be listed in the MMJAA beneficiary database maintained by SACHIS.\nMust not already be covered under AB-PMJAY.\nEligible families are identified by the Government based on notified criteria; there is no separate enrolment process', 'Aadhaar Card.\nAadhaar-linked mobile number.\nRation Card.\nFamily identification details as available in the MMJAA/SACHIS records.\nAny additional identity document required for beneficiary verification', 'Insurance Cover', 'Cashless health insurance coverage of up to ₹5 lakh per family per year.\nCovers secondary and tertiary hospitalization at empanelled government and private hospitals.\nCovers pre-existing diseases from Day 1.\nNo restriction on family size.\nTreatment available across India through the PM-JAY empanelled hospital network with national portability', 500000.0, NULL, 'Recurring', 'Annual', NULL, 'Both', 'Check your eligibility through the Ayushman Bharat Beneficiary Portal or at a Common Service Centre (CSC) or an empanelled hospital.\nIf your family is listed as eligible, generate your Ayushman Card using Aadhaar verification.\nVisit any empanelled government or private hospital with your Ayushman Card and valid photo ID.\nAfter verification, eligible beneficiaries can avail cashless treatment under the scheme', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Universal', 0, 1, 97),
  (98, 'JK-SCH-0098', 'Rani Lakshmibai Mahila Evam Bal Samman Kosh', NULL, 'rani-lakshmibai-mahila-evam-bal-samman-kosh', NULL, 'State', 34, 29, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Women and girl children who are victims of heinous crimes, including rape, gang rape, acid attacks, offences under the POCSO Act, and other serious crimes.\nDependent children of eligible victims may receive educational and medical assistance.\nIn exceptional circumstances, women or girl children requiring urgent social and economic rehabilitation may also be considered under the scheme', 'Duly filled application form (where applicable).\nAadhaar Card or other valid identity proof.\nCopy of the FIR.\nMedical report/injury certificate.\nBank account details/passbook.\nPassport-size photograph.\nDeath certificate (where applicable).\nAny additional documents required by the District Probation Officer or District Level Committee', 'Cash Benefit', 'Financial assistance ranging from ₹1 lakh to ₹10 lakh, depending on the nature and severity of the offence.\nFree medical treatment, including reconstructive surgery where required.\nEducational and medical assistance for the minor children of victims, where applicable.\nRehabilitation and other support services to help survivors recover and reintegrate into society', NULL, 'Multiple amounts specified (see benefit description)', 'In-kind', NULL, NULL, 'Offline', 'Report the incident to the police and ensure registration of an FIR.\nApproach the District Probation Officer (DPO) or District Magistrate\'s Office for assistance under the scheme.\nSubmit the required documents, including the FIR, identity proof, medical records, and bank account details.\nThe District Level Steering Committee examines the case and recommends assistance.\nUpon approval, financial assistance is transferred directly to the beneficiary\'s bank account, while medical and rehabilitation support is coordinated through the concerned departments', NULL, NULL, 0, NULL, NULL, 'http://www.msk.upsdc.gov.in', 'www.msk.upsdc.gov.in', NULL, NULL, 'Protection and Safety Women, Children', 0, 1, 98),
  (99, 'JK-SCH-0099', 'Uttar Pradesh Building and Other Construction Workers (BOCW) Welfare Schemes', 'BOCW', 'uttar-pradesh-building-and-other-construction-workers-bocw-welfare-schemes', NULL, 'State', 34, 32, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Uttar Pradesh.\nMust be 18–60 years of age.\nMust have worked in building or construction work for at least 90 days during the preceding 12 months.\nMust be registered with the Uttar Pradesh Building and Other Construction Workers Welfare Board (UPBOCW).\nRegistration must be renewed periodically to continue receiving benefits', 'Aadhaar Card.\nPassport-size photograph.\nProof of age.\nProof of residence.\nBank account details/passbook.\nProof of construction work (certificate from employer/contractor, work certificate, or self-declaration as prescribed).\nMobile number.\nAny additional documents required for specific welfare schemes', 'Pension', 'Financial assistance for children\'s education and scholarships.\nMarriage assistance for workers and their daughters.\nMaternity and paternity benefits.\nAccident, disability, and death compensation.\nPension after attaining the eligible age.\nHousing assistance and toilet construction support.\nMedical assistance and treatment.\nToolkits, skill development, and vocational training.\nAssistance for bicycles, safety equipment, and other welfare measures', NULL, NULL, 'In-kind', NULL, NULL, 'Both', 'Register as a construction worker on the UPBOCW portal or through a Common Service Centre (CSC).\nSubmit the required documents and proof of construction work.\nAfter approval, obtain the Labour Card (Shramik Card).\nLog in to the portal and apply online for the specific welfare scheme(s) for which you are eligible.\nAfter verification by the Labour Department, eligible benefits are transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Worker Welfare Universal BOCW', 0, 1, 99),
  (100, 'JK-SCH-0100', 'Mukhyamantri Yuva Swarozgar Yojana', NULL, 'mukhyamantri-yuva-swarozgar-yojana', NULL, 'State', 34, 9, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Uttar Pradesh.\nAge should be 18–40 years.\nMust have passed at least High School (Class 10).\nShould be unemployed and intending to establish a new enterprise.\nShould not be a defaulter of any bank or financial institution.\nShould not have availed benefits under similar self-employment schemes such as PMRY, PMEGP, or other State/Central Government self-employment schemes', 'Aadhaar Card.\nDomicile Certificate.\nHigh School (Class 10) certificate/mark sheet.\nPassport-size photograph.\nBank account details.\nProject Report/Business Plan.\nCaste Certificate (if applicable).\nDisability Certificate (if applicable).\nAffidavit regarding eligibility.\nMobile number and email ID', 'Credit / Subsidy', 'Bank loan up to ₹25 lakh for manufacturing/industrial projects.\nBank loan up to ₹10 lakh for service sector enterprises.\nMargin money subsidy:\n15% of the project cost (General category).\n25% of the project cost (SC/ST/OBC/Minorities/Women/Ex-servicemen/Persons with Disabilities), subject to prescribed limits.\nSubsidy is released after successful establishment and operation of the enterprise as per scheme guidelines', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Both', 'Visit the Directorate of Industries & Enterprise Promotion / Nivesh Mitra portal.\nRegister as a new applicant.\nComplete the online application form and upload the required documents.\nSubmit the business project report and application.\nThe application is scrutinized by the District Level Task Force Committee and forwarded to the financing bank.\nUpon approval by the bank and the competent authority, the loan and eligible subsidy are sanctioned', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Youth', 0, 1, 100);
INSERT INTO `schemes` (`id`, `scheme_code`, `name`, `short_name`, `slug`, `description`, `scheme_level`, `state_id`, `theme_id`, `service_approach_id`, `priority_id`, `feasibility_id`, `ministry_id`, `department_id`, `ministry_name`, `department_name`, `scheme_status`, `active_enrollment`, `launch_year`, `target_group_summary`, `eligibility_summary`, `benefit_type`, `benefit_description`, `benefit_amount`, `benefit_amount_text`, `benefit_mode`, `benefit_frequency`, `benefit_conditions`, `application_mode`, `application_process`, `application_instructions`, `portal_url`, `csc_available`, `physical_office`, `helpline_number`, `source_url`, `source_website`, `last_verified_date`, `verified_by`, `keywords`, `view_count`, `is_active`, `source_row_no`) VALUES
  (101, 'JK-SCH-0101', 'Mukhyamantri Nirashrit Besahara Govansh Sahbhagita Yojana', NULL, 'mukhyamantri-nirashrit-besahara-govansh-sahbhagita-yojana', NULL, 'State', 34, 9, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Uttar Pradesh.\nShould have adequate space and facilities to rear the adopted cattle.\nFarmers, livestock rearers, Self-Help Groups (SHGs), and other eligible individuals are eligible to apply.\nApplicants should be capable of properly caring for the adopted cattle', 'Aadhaar Card.\nResidence/Domicile Certificate.\nBank account details/passbook.\nPassport-size photograph.\nMobile number.\nAny additional documents required by the local Animal Husbandry Department or Gaushala authority', 'Cash Benefit', '₹1,500 per month per adopted cow (₹50 per day) is provided through Direct Benefit Transfer (DBT).\nFinancial assistance is available for adopting up to four destitute cows.\nPromotes sustainable livestock rearing and provides an additional source of income through dairy products and organic manure', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 'Offline', 'Visit the nearest Gaushala (Cow Shelter) or the District Animal Husbandry Office.\nSubmit an application expressing willingness to adopt destitute cattle.\nProvide the required documents for verification.\nAfter verification of eligibility and cattle-rearing facilities, the cattle are allotted to the applicant.\nUpon successful adoption, the monthly maintenance assistance is transferred directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Farmers', 0, 1, 101),
  (102, 'JK-SCH-0102', 'Rupashree Prakalpa', NULL, 'rupashree-prakalpa', NULL, 'State', 36, 23, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of West Bengal (born in the state, resident for at least 5 years, or with parents who are permanent residents).\nThe bride must be 18 years or older and unmarried at the time of application.\nThe proposed marriage must be her first marriage.\nThe prospective groom must be 21 years or older.\nAnnual family income should not exceed ₹1.5 lakh.\nThe applicant must have an active bank account in her own name', 'Proof of age of the applicant (Birth Certificate, Aadhaar, Voter ID, etc.).\nSelf-declaration of unmarried status.\nIncome certificate/self-declaration certified by the competent authority.\nProof of residence.\nBank passbook (showing account details and IFSC code).\nProof of proposed marriage (Marriage Invitation Card or Notice of Marriage Registration).\nProof of age of the prospective groom.\nPassport-size photographs of the bride and groom', 'Cash Benefit', 'One-time financial assistance of ₹25,000.\nAmount is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT).\nEncourages marriage only after the legal age and supports women\'s social and economic security', 25000.0, NULL, 'One-time', 'One-time', NULL, 'Both', 'Obtain the application form from the Block Development Office (BDO), Sub-Divisional Office (SDO), or Municipal Office, or apply through the official Rupashree Portal.\nComplete the application form and attach the required documents.\nSubmit the application 30–60 days before the proposed date of marriage.\nThe application is verified through a field enquiry by the designated authority.\nUpon approval, the ₹25,000 grant is transferred directly to the applicant\'s bank account, generally before the date of marriage', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Women', 0, 1, 102),
  (103, 'JK-SCH-0103', 'Annapurna Bhandar Scheme', NULL, 'annapurna-bhandar-scheme', NULL, 'State', 36, 23, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of West Bengal.\nWomen aged 25–60 years.\nShould satisfy the eligibility criteria notified by the State Government.\nExisting eligible Lakshmir Bhandar beneficiaries continue under the scheme without submitting a fresh application, subject to verification', 'Aadhaar Card.\nAadhaar-linked bank account details.\nProof of residence.\nMobile number.\nPassport-size photograph.\nAny additional documents prescribed by the Government during verification', 'Cash Benefit', '₹3,000 per month is provided to eligible women through Direct Benefit Transfer (DBT).\nThe assistance can be used for food, healthcare, education, and other household needs.\nExisting eligible beneficiaries of Lakshmir Bhandar are automatically migrated to the new scheme after verification', 3000.0, NULL, 'Recurring', 'Monthly', NULL, 'Both', 'Visit the official Annapurna Bhandar Portal or designated government facilitation centres.\nRegister and complete the online application form (for new applicants).\nUpload or submit the required documents.\nAfter verification by the concerned authorities, eligible applicants receive the monthly assistance through DBT.\nExisting eligible Lakshmir Bhandar beneficiaries are automatically migrated and generally do not need to submit a fresh application unless specifically notified', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Women', 0, 1, 103),
  (104, 'JK-SCH-0104', 'Yuvasree Scheme (Yuvasree Prakalpa)', NULL, 'yuvasree-scheme-yuvasree-prakalpa', NULL, 'State', 36, 9, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of West Bengal.\nMust be 18–45 years of age.\nMust be unemployed and registered as a job seeker in the Employment Bank.\nMust have passed at least Class VIII.\nShould not have received financial assistance or loans under any other State/Central Government self-employment scheme.\nOnly one member per family is eligible', 'Completed application form (Annexure I).\nUnemployment Certificate (Annexure II) issued by a Group A Officer.\nSelf-declaration (Annexure III).\nAadhaar Card or other identity proof.\nProof of age (Birth Certificate/Class X Admit Card/Certificate).\nProof of residence.\nEducational qualification certificates/mark sheets.\nBank account details.\nPassport-size photograph.\nCaste Certificate (if applicable).\nDisability Certificate (if applicable)', 'Training', 'Monthly unemployment assistance of ₹1,500 through Direct Benefit Transfer (DBT).\nAccess to Employment Bank for job opportunities.\nSkill development and vocational training to improve employability.\nPlacement support for employment in government and private sectors', 1500.0, NULL, 'Recurring', 'Monthly', NULL, 'Online', 'Register as a Job Seeker on the Employment Bank, West Bengal portal.\nObtain a valid Employment Bank registration number.\nLog in and apply for the Yuvasree Scheme online.\nUpload the required documents and submit the application.\nAfter verification by the Labour Department, eligible beneficiaries are enrolled, and the monthly assistance is transferred directly to their bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Youth', 0, 1, 104),
  (105, 'JK-SCH-0105', 'Kanyashree Prakalpa', NULL, 'kanyashree-prakalpa', NULL, 'State', 36, 5, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of West Bengal.\nMust be unmarried.\nK1: Girls aged 13–18 years enrolled in a recognized educational institution.\nK2: Girls aged 18 years or above who are unmarried and continuing education or vocational training.\nFamily annual income should generally not exceed ₹1.2 lakh. The income criterion is relaxed for girls with disabilities, orphan girls, and girls residing in Child Care Institutions', 'Birth Certificate or other proof of age.\nAadhaar Card (where applicable).\nProof of residence.\nIncome Certificate.\nSchool/College enrolment certificate.\nDeclaration of unmarried status.\nBank account details in the applicant\'s name.\nPassport-size photograph.\nDisability certificate (if applicable)', 'Scholarship / Fee Support', 'K1: Annual scholarship of ₹1,000 for eligible unmarried girls aged 13–18 years enrolled in school or equivalent educational/vocational institutions.\nK2: One-time grant of ₹25,000 to eligible unmarried girls after attaining 18 years of age, provided they are continuing education or vocational training.\nK3: Higher education scholarship for girls pursuing undergraduate/postgraduate studies under notified institutions (amount as per prevailing government guidelines)', NULL, 'Multiple amounts specified (see benefit description)', 'One-time', 'One-time', NULL, 'Online', 'Obtain the application form from the school, college, or educational institution where the applicant is enrolled, or apply through the official Kanyashree portal.\nComplete the application form and attach the required documents.\nSubmit the application to the Head of the Institution for verification.\nThe institution forwards the verified application to the concerned authorities.\nUpon approval, the scholarship/grant is credited directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Children, Women', 0, 1, 105),
  (106, 'JK-SCH-0106', 'Swasthya Sathi', NULL, 'swasthya-sathi', NULL, 'State', 36, 1, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of West Bengal.\nFamilies eligible under the State\'s enrolment criteria can avail benefits.\nCertain categories already covered under specific government medical reimbursement schemes may not be eligible under the general enrolment process', 'Aadhaar Card of family members.\nProof of residence (such as Aadhaar, Ration Card, or other approved documents).\nFamily identity documents (e.g., Ration Card/Khadya Sathi Card, if applicable).\nPassport-size photograph.\nMobile number.\nAny additional documents required during enrolment or verification', 'Insurance Cover', 'Cashless health coverage up to ₹5 lakh per family per year.\nCovers secondary and tertiary hospitalization, including surgeries, diagnostics, and specialized treatments.\nNo premium is payable by beneficiaries; the entire premium is borne by the State Government.\nCovers pre-existing diseases from the date of enrolment.\nTreatment is available at empanelled government and private hospitals', 500000.0, NULL, 'Recurring', 'Annual', NULL, 'Offline', 'Visit the nearest Bangla Sahayata Kendra (BSK) or designated enrolment centre.\nSubmit the required identity and family documents.\nComplete biometric and document verification.\nAfter successful verification, the Swasthya Sathi Smart Card is issued.\nThe card can then be used to avail cashless treatment at empanelled hospitals across West Bengal', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Universal', 0, 1, 106),
  (107, 'JK-SCH-0107', 'Janma Mrityu Tathya Portal', NULL, 'janma-mrityu-tathya-portal', NULL, 'State', 36, 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Applicable to all births and deaths occurring within West Bengal.\nBirths and deaths should be registered under the Registration of Births and Deaths Act, 1969.\nDelayed registration is permitted as per the prescribed legal procedure', 'For Birth Registration\n\nBirth report from the hospital/institution or medical practitioner.\nIdentity proof of parents.\nProof of residence.\nMobile number.\nSupporting documents for delayed registration (if applicable).\n\nFor Death Registration\n\nMedical Certificate of Cause of Death (where applicable).\nIdentity proof of the deceased/informant.\nProof of residence.\nCremation/Burial certificate (where applicable).\nSupporting documents for delayed registration', 'In-kind / Material', 'Online registration of births and deaths.\nDownload of digitally signed birth and death certificates.\nFacility for certificate correction, delayed registration, status tracking, and certificate verification.\nQR code-enabled certificates for easy authentication', NULL, NULL, NULL, NULL, NULL, 'Both', 'Visit the official Janma Mrityu Tathya Portal.\nRegister using your mobile number and OTP.\nSelect the required service (Birth or Death Registration).\nComplete the online application and upload the required documents.\nTrack the application status online.\nOnce approved, download the digitally signed certificate from the portal or obtain it from the concerned registration authority', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Universal', 0, 1, 107),
  (108, 'JK-SCH-0108', 'Swasthya Ingit Telemedicine', NULL, 'swasthya-ingit-telemedicine', NULL, 'State', 36, 1, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of West Bengal.\nPatients visiting government Health & Wellness Centres (Swasthya Kendras), Primary Health Centres (PHCs), or other participating government health facilities are eligible.\nThe service is available based on referral and clinical assessment by the attending healthcare provider', 'Aadhaar Card or another valid government-issued photo ID (if required).\nHealth records, previous prescriptions, diagnostic reports, and investigation results (if available).\nMobile number (where applicable for communication or follow-up)', 'Service Delivery', 'Free teleconsultation with specialist doctors at government health facilities.\nAccess to specialist services in cardiology, neurology, oncology, paediatrics, obstetrics & gynaecology, psychiatry, nephrology, gastroenterology, tuberculosis, viral hepatitis, breast diseases, and other specialties.\nReduces travel time and out-of-pocket medical expenses for rural patients.\nFacilitates follow-up consultations, early diagnosis, timely referrals, and continuity of care. The programme has provided over 7 crore teleconsultations through more than 11,000 Health & Wellness Centres, supported by 63 specialist hubs and over 9,000 doctors', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest Government Health & Wellness Centre (Swasthya Kendra), Primary Health Centre (PHC), or participating government health facility.\nUndergo an initial examination by the attending Community Health Officer (CHO) or Medical Officer.\nIf specialist consultation is required, the healthcare provider schedules a Swasthya Ingit teleconsultation.\nConsult the specialist doctor through the telemedicine platform and receive prescriptions, advice, investigations, or referrals as needed.\nReturn to the local health facility for follow-up care or further referral, if advised', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Universal', 0, 1, 108),
  (109, 'JK-SCH-0109', 'Sishu Saathi', NULL, 'sishu-saathi', NULL, 'State', 36, 1, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of West Bengal.\nChild should be 0–18 years of age.\nMust be diagnosed with an eligible condition under the scheme through government screening or an empanelled hospital', 'Aadhaar Card (if available).\nProof of residence.\nBirth Certificate or age proof of the child.\nMedical records and diagnostic reports.\nPassport-size photograph.\nMobile number of the parent/guardian', 'Service Delivery', 'Free treatment and surgeries for eligible children at empanelled government and private hospitals.\nCovers major conditions such as:\nCongenital heart diseases (paediatric cardiac surgery)\nNeurosurgical conditions\nCongenital cataract and other critical eye surgeries\nOther notified congenital disorders under the scheme.\nCovers the entire cost of treatment, including hospitalization and surgery, with no out-of-pocket expenditure for the family', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Visit the nearest government health facility or empanelled hospital for screening, or participate in health screening conducted under RBSK in schools and Anganwadi centres.\nIf the child is diagnosed with a covered condition, the case is referred to an empanelled treatment centre.\nSubmit the required documents for verification.\nUpon approval, the child receives cashless treatment and surgery at the designated hospital under the Sishu Saathi Scheme', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Health Children', 0, 1, 109),
  (110, 'JK-SCH-0110', 'Swami Vivekananda Merit-cum-Means Scholarship (SVMCM)', 'SVMCM', 'swami-vivekananda-merit-cum-means-scholarship-svmcm', NULL, 'State', 36, 5, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of West Bengal.\nMust be enrolled in a recognized educational institution in West Bengal.\nAnnual family income should not exceed ₹2.5 lakh.\nMinimum qualifying marks:\n60% in the last qualifying examination for Higher Secondary, Diploma, and Undergraduate courses.\n53% in Honours at the undergraduate level for Postgraduate courses (General).\n55% for Engineering/Technical Postgraduate courses.\nApplicants should not be receiving any other government scholarship for the same course', 'Aadhaar Card.\nDomicile proof (Aadhaar Card/Voter ID/Ration Card/Domicile Certificate).\nIncome Certificate.\nLast qualifying examination mark sheet.\nCurrent admission receipt/enrolment certificate.\nBank passbook (first page showing account number and IFSC).\nPassport-size photograph and signature.\nInstitution declaration (if applicable, e.g., gap year)', 'Scholarship / Fee Support', 'Monthly scholarship ranging from ₹1,000 to ₹8,000, depending on the course and level of study.\nFinancial assistance is provided through Direct Benefit Transfer (DBT) to the student\'s bank account.\nAvailable for students pursuing Higher Secondary, UG, PG, Engineering, Medical, Polytechnic, Technical, Professional, and eligible Research courses', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 'Both', 'Visit the official SVMCM Scholarship Portal.\nRegister as a new applicant and complete the online application form.\nUpload the required documents.\nSubmit the application online and note the application ID for future reference.\nThe application is verified by the educational institution and the concerned department.\nUpon approval, the scholarship amount is credited directly to the student\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Children, Youth SVMCM', 0, 1, 110),
  (111, 'JK-SCH-0111', 'West Bengal Freeship Scheme (WBFS)', 'WBFS', 'west-bengal-freeship-scheme-wbfs', NULL, 'State', 36, 5, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a domicile of West Bengal.\nMust have secured admission to an eligible undergraduate Engineering, Technology, Pharmacy, or Architecture course in a self-financing private technical institution in West Bengal.\nAdmission must be based on a State-level or National-level entrance examination.\nAnnual family income must not exceed ₹2.5 lakh.\nStudents already receiving benefits under the AICTE Tuition Fee Waiver (TFW) Scheme or the Swami Vivekananda Merit-cum-Means Scholarship (SVMCM) are not eligible under WBFS', 'Aadhaar Card.\nDomicile Certificate.\nIncome Certificate.\nEntrance examination rank card.\nAdmission letter and fee receipt.\nPassport-size photograph.\nBank account details.\nMobile number and email ID', NULL, 'Full or partial waiver of tuition fees, depending on eligibility and availability.\nApplicable only to tuition fees; other fees (hostel, examination, library, etc.) must be borne by the student.\nReduces the financial burden of pursuing professional technical education', NULL, NULL, NULL, NULL, NULL, 'Both', 'Visit the official West Bengal Freeship Scheme (WBFS) Portal.\nRegister as a new applicant using your mobile number and email ID.\nComplete the online application form and upload the required documents.\nSubmit the application and note the Applicant ID for future reference.\nThe institution verifies the application and forwards it to the Directorate for approval.\nEligible students receive the approved tuition fee waiver as per the scheme guidelines', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Youth WBFS', 0, 1, 111),
  (112, 'JK-SCH-0112', 'Banglashree Scheme', NULL, 'banglashree-scheme', NULL, 'State', 36, 9, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a Micro, Small, or Medium Manufacturing Enterprise located in West Bengal.\nThe enterprise should meet the eligibility criteria prescribed under the Banglashree Scheme.\nApplicable to new units, expansion, modernization, or diversification projects.\nThe unit should possess valid Udyam Registration and other statutory registrations.\nCertain industries included in the scheme\'s negative list are not eligible', 'Udyam Registration Certificate.\nPAN Card of the enterprise.\nGST Registration Certificate.\nProject Report.\nLand/building ownership or lease documents.\nTerm loan sanction letter (where applicable).\nBank account details.\nInvoices and proof of investment in plant and machinery.\nAny additional documents prescribed by the MSME Department', 'Credit / Subsidy', 'State Capital Investment Subsidy for eligible new and expanding MSMEs.\nInterest Subsidy on term loans for eligible enterprises.\nReimbursement of Stamp Duty and Registration Fees.\nNet SGST reimbursement for eligible manufacturing units.\nPower subsidy and incentives for energy efficiency and environmental compliance.\nAdditional incentives for women, SC/ST, and minority entrepreneurs in eligible categories', NULL, NULL, NULL, NULL, NULL, 'Online', 'Apply through the West Bengal MSME & Textiles Department or the SilpaSathi Single Window Portal.\nRegister the enterprise and complete the online application for the relevant Banglashree incentive.\nUpload the required documents and submit the application.\nThe application is scrutinized by the concerned department.\nUpon approval, eligible subsidies and incentives are released to the beneficiary as per the scheme guidelines', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Entrepreneurs', 0, 1, 112),
  (113, 'JK-SCH-0113', 'Jai Johar Scheme', NULL, 'jai-johar-scheme', NULL, 'State', 36, 18, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of West Bengal.\nMust belong to the Scheduled Tribe (ST) community.\nMust be 60 years of age or above.\nShould not be receiving any other government social security pension or pension from any government organization', 'Aadhaar Card.\nScheduled Tribe (ST) Caste Certificate.\nProof of residence/Domicile.\nDigital Ration Card.\nProof of age (Voter ID/Birth Certificate or other valid document).\nBank account passbook.\nPassport-size photograph.\nMobile number', 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nPension is credited directly to the beneficiary\'s bank account.\nProvides financial support to elderly ST beneficiaries for meeting basic living expenses', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Obtain the application form from the Block Development Office (BDO), Sub-Divisional Office (SDO), Municipality, Kolkata Municipal Corporation, or a Bangla Sahayata Kendra (BSK).\nFill in the application form and attach the required documents.\nSubmit the completed application to the designated office.\nThe application is verified by the concerned authorities.\nUpon approval, the ₹1,000 monthly pension is transferred directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Old Age Protection Minorities', 0, 1, 113),
  (114, 'JK-SCH-0114', 'Taposhili Bandhu Pension Scheme', NULL, 'taposhili-bandhu-pension-scheme', NULL, 'State', 36, 18, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of West Bengal.\nMust belong to the Scheduled Caste (SC) community.\nMust be 60 years of age or above.\nShould not be receiving any other government social security pension or pension from any government organization', 'Aadhaar Card.\nScheduled Caste (SC) Certificate.\nProof of residence.\nDigital Ration Card.\nProof of age (Birth Certificate, Voter ID, or other valid document).\nBank account passbook.\nPassport-size photograph.\nMobile number', 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nPension is credited directly to the beneficiary\'s bank account.\nProvides financial support for meeting basic living expenses', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Obtain the application form from the Block Development Office (BDO), Sub-Divisional Office (SDO), Municipality, Kolkata Municipal Corporation, or a Bangla Sahayata Kendra (BSK).\nFill in the application form and attach the required documents.\nSubmit the completed application to the designated office.\nThe application is verified by the concerned authorities.\nUpon approval, the ₹1,000 monthly pension is transferred directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Old Age Protection Minorities', 0, 1, 114),
  (115, 'JK-SCH-0115', 'Manabik Pension Scheme', NULL, 'manabik-pension-scheme', NULL, 'State', 36, 23, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of West Bengal.\nMust have 40% or more disability, certified by a competent medical authority.\nMust possess a valid Disability Certificate/UDID Card.\nShould not be receiving another government disability pension or similar social security pension, as per scheme guidelines', 'Aadhaar Card.\nDisability Certificate/UDID Card.\nProof of residence/Domicile.\nDigital Ration Card (if applicable).\nBank account passbook.\nPassport-size photograph.\nMobile number.\nIncome Certificate (if required by the competent authority)', 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nPension is credited directly to the beneficiary\'s bank account.\nProvides regular financial support to meet basic living expenses and improve social security', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Obtain the application form from the Block Development Office (BDO), Municipality, Sub-Divisional Office (SDO), or Duare Sarkar Camp.\nComplete the application form and attach the required documents.\nSubmit the application to the designated office for verification.\nAfter approval by the competent authority, the pension is credited directly to the beneficiary\'s bank account through DBT.\nPension is credited directly to the beneficiary\'s bank account.\nProvides regular financial support to meet basic living expenses and improve social security', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Minorities', 0, 1, 115),
  (116, 'JK-SCH-0116', 'Krishak Bandhu (Natun) Scheme', NULL, 'krishak-bandhu-natun-scheme', NULL, 'State', 36, 23, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of West Bengal.\nMust be a farmer with cultivable land recorded in official land records (RoR/Patta/Forest Patta) or an eligible registered sharecropper (Bhagchasi).\nThe applicant must have a valid Aadhaar-linked bank account for DBT benefits', 'Aadhaar Card.\nRecord of Rights (RoR)/Patta/Forest Patta or registered sharecropper documents.\nVoter ID or other identity proof.\nBank passbook (first page).\nPassport-size photograph.\nMobile number', 'Cash Benefit', '₹10,000 per year (paid in two equal instalments during the Kharif and Rabi seasons) for farmers with 1 acre or more of cultivable land.\nFarmers with less than 1 acre of cultivable land receive pro-rata assistance, subject to a minimum of ₹4,000 per year.\n₹2 lakh one-time death benefit to the nominee/legal heir if a registered farmer aged 18–60 years dies.\nRegistered farmers may also receive preference under certain state agricultural support programmes', NULL, 'Multiple amounts specified (see benefit description)', 'Both', 'Annual', NULL, 'Offline', 'Obtain the application form from the Gram Panchayat Office, Block Agriculture Office, or the office of the Assistant Director of Agriculture.\nFill out the application form and attach the required documents.\nSubmit the completed application to the designated Agriculture Department office or Gram Panchayat.\nThe application and land records are verified by the concerned authorities.\nUpon approval, financial assistance and other benefits are transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Farmers', 0, 1, 116),
  (117, 'JK-SCH-0117', 'Bangla Shasya Bima', NULL, 'bangla-shasya-bima', NULL, 'State', 36, 21, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of West Bengal.\nLoanee and non-loanee farmers cultivating notified crops are eligible.\nIncludes owner cultivators, sharecroppers, and tenant farmers, subject to scheme guidelines.\nLoanee farmers are covered as per the notified provisions', 'Aadhaar Card.\nVoter ID or other identity proof.\nLand records/Record of Rights (RoR) or land possession certificate.\nProof of cultivation (including tenancy/sharecropping documents, where applicable).\nBank account details.\nMobile number.\nInsurance certificate/application details (for claims)', 'Insurance Cover', 'Free crop insurance with no premium payable by the farmer.\nCompensation for crop loss due to:\nPrevented/failed sowing.\nMid-season adversity.\nNatural calamities affecting standing crops.\nPost-harvest losses for notified crops.\nCoverage for both Kharif and Rabi notified crops', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Obtain the application form from the Gram Panchayat, Block Agriculture Office, or other designated Agriculture Department offices during the enrolment period.\nComplete the application form and attach the required documents.\nSubmit the application to the designated authority before the notified deadline for the relevant crop season.\nAfter enrolment, farmers receive confirmation of insurance coverage.\nIn case of crop loss, report the damage within the prescribed time to the Agriculture Department or the designated insurance agency to initiate the claim process', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Insurance Farmers', 0, 1, 117),
  (118, 'JK-SCH-0118', 'State Social Security Scheme (Old Age, Widow & Disability Pension)', NULL, 'state-social-security-scheme-old-age-widow-disability-pension', NULL, 'State', 36, 23, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of West Bengal.\nMust belong to one of the following categories:\nOld Age Pension: 60 years or above (55 years in certain disability-related cases).\nWidow Pension: Widowed women with limited means of livelihood.\nDisability Pension: Persons with 40% or more disability certified by a competent authority.\nShould not be receiving another government social security pension for the same purpose', 'Aadhaar Card.\nProof of residence.\nBank account/passbook.\nPassport-size photograph.\nAge proof (for old-age pension).\nHusband\'s death certificate (for widow pension).\nDisability Certificate/UDID Card (for disability pension).\nIncome certificate (if applicable)', 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nFinancial support for:\nSenior citizens.\nWidows.\nPersons with disabilities.\nPension is credited directly to the beneficiary\'s bank account', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Obtain the application form from the Block Development Office (BDO), Municipality, Sub-Divisional Office (SDO), or Bangla Sahayata Kendra (BSK).\nFill in the application form and attach the required documents.\nSubmit the application to the designated authority.\nThe application is verified by the concerned department.\nUpon approval, the pension is credited directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Elderly, Women, PwD/Chronic Diseases', 0, 1, 118),
  (119, 'JK-SCH-0119', 'Sabooj Sathi', NULL, 'sabooj-sathi', NULL, 'State', 36, 5, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a student of Class IX, X, XI, or XII.\nMust be enrolled in a government or government-aided school in West Bengal.\nMust be a resident of West Bengal.\nPreference is generally given to students in rural and economically weaker households', 'School certificate or bonafide certificate from the institution.\nAadhaar Card (if available).\nProof of residence.\nStudent identity card.\nPassport-size photograph.\nBank details (if required by the school/authority for verification purposes)', 'In-kind / Material', 'Free bicycle provided to eligible students studying in Class IX–XII.\nHelps reduce travel time and transportation barriers to school.\nPromotes school attendance, retention, and gender equality in education', NULL, NULL, 'In-kind', NULL, NULL, 'Online', 'The school identifies eligible students based on enrolment in Classes IX–XII.\nStudent details are submitted by the school to the education department through the official Sabooj Sathi portal.\nDistrict authorities verify the list of beneficiaries.\nBicycles are procured and distributed through schools or designated distribution camps.\nStudents receive the bicycle free of cost from the government', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Children, Youth', 0, 1, 119),
  (120, 'JK-SCH-0120', 'Karma Sathi Prakalpa', NULL, 'karma-sathi-prakalpa', NULL, 'State', 36, 9, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of West Bengal.\nAge should be 18–50 years.\nMust have passed at least Class VIII.\nShould be an intending entrepreneur proposing a new manufacturing, service, or trading venture.\nOnly one member per family is eligible to apply.\nPreference is given to applicants registered with the Employment Bank', 'Aadhaar Card.\nProof of residence.\nEducational qualification certificate (minimum Class VIII).\nPassport-size photograph.\nProject report/business plan.\nBank account details.\nEmployment Bank registration (if applicable).\nMobile number and email ID', 'Credit / Subsidy', 'Soft loan up to ₹2 lakh for establishing a new enterprise.\nProject subsidy of 15% of the project cost, subject to a maximum of ₹25,000.\nInterest subsidy:\n50% of the interest for timely loan repayment (up to 3 years).\n40% of the interest in other eligible cases (up to 3 years).\nLoan is disbursed through the West Bengal State Cooperative Bank and affiliated cooperative banks', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Online', 'Apply online through the Karma Sathi Prakalpa Portal or submit the prescribed application form to the District MSME Facilitation Centre (MFC).\nFill in the application form and upload/attach the required documents.\nSubmit the project report for evaluation.\nThe application is scrutinized by the competent authority and forwarded to the financing cooperative bank.\nUpon approval, the loan and eligible subsidies are sanctioned and disbursed as per the scheme guidelines', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Entrepreneurs', 0, 1, 120),
  (121, 'JK-SCH-0121', 'Anandadhara (West Bengal State Rural Livelihoods Mission – WBSRLM)', NULL, 'anandadhara-west-bengal-state-rural-livelihoods-mission-wbsrlm', NULL, 'State', 36, 9, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of rural West Bengal.\nPrimarily intended for poor and vulnerable rural households, especially women.\nApplicants should become members of an Anandadhara Self-Help Group (SHG).\nEligibility is determined according to NRLM/WBSRLM guidelines', 'Aadhaar Card.\nProof of residence.\nBank account details.\nPassport-size photograph.\nMobile number.\nAny additional documents required for SHG membership or specific livelihood interventions', 'Credit / Subsidy', 'Formation and strengthening of Self-Help Groups (SHGs) and their federations.\nAccess to bank credit, microfinance, and revolving funds.\nSkill development and vocational training for livelihood enhancement.\nSupport for micro-enterprises, agriculture, livestock, fisheries, and producer groups.\nMarket linkage, value chain development, and entrepreneurship support for SHG members', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Contact the Gram Panchayat, Block Mission Management Unit (BMMU), or District Mission Management Unit (DMMU) under Anandadhara.\nEnrol as a member of an existing Self-Help Group (SHG) or form a new SHG with eligible members.\nComplete the registration process and submit the required documents.\nParticipate in SHG meetings, capacity-building programmes, and livelihood planning.\nEligible members can then access credit, training, livelihood support, and other benefits available under the Anandadhara/WBSRLM programme', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Universal, Women', 0, 1, 121),
  (122, 'JK-SCH-0122', 'Khadya Sathi Scheme', NULL, 'khadya-sathi-scheme', NULL, 'State', 36, 14, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of West Bengal.\nMust possess or be eligible for a valid ration card under the Public Distribution System.\nEligibility is determined based on the beneficiary category notified by the Department of Food & Supplies (such as Antyodaya Anna Yojana (AAY), Priority Household (PHH/SPHH), or Rajya Khadya Suraksha Yojana (RKSY))', 'Aadhaar Card.\nRation Card (or application for a new ration card).\nProof of residence.\nIdentity proof (e.g., Voter ID).\nBirth certificate (for addition of children, where applicable).\nPassport-size photograph', 'Cash Benefit', 'Rice and wheat at highly subsidized rates (generally ₹2 per kg for eligible beneficiaries under applicable categories).\nFood grain entitlement varies according to the beneficiary\'s ration card category (e.g., AAY, PHH/SPHH, RKSY).\nAccess through physical or digital (e-Ration) cards.\nEnsures regular supply of essential food grains to eligible households', 2.0, NULL, NULL, NULL, NULL, 'Online', 'Apply for a new ration card or update an existing one through the Department of Food & Supplies, Government of West Bengal or the e-District/Online Ration Card Portal.\nSubmit the prescribed application form along with the required documents.\nThe application is verified by the concerned authorities.\nUpon approval, a Khadya Sathi/Digital Ration Card is issued.\nEligible beneficiaries can collect subsidized food grains every month from their designated Fair Price Shop (Ration Shop)', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Food Security Universal', 0, 1, 122),
  (123, 'JK-SCH-0123', 'Savitribai Phule Kishori Samriddhi Yojana', NULL, 'savitribai-phule-kishori-samriddhi-yojana', NULL, 'State', 15, 5, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Jharkhand.\nMust be a girl enrolled in Classes VIII to XII in a recognized school.\nShould meet the eligibility criteria prescribed by the Department, including continuation of education and compliance with the scheme conditions for the final installment.\nThe applicant must have an Aadhaar-linked bank account', 'Aadhaar Card.\nResidence (Domicile) Certificate.\nSchool admission/enrolment certificate.\nRecent passport-size photograph.\nBank account details/passbook.\nMobile number.\nBirth certificate or age proof.\nAny other documents prescribed by the Department', 'Cash Benefit', 'Financial assistance is provided in stages:\n₹2,500 for girls studying in Class VIII.\n₹2,500 for girls studying in Class IX.\n₹5,000 each for girls studying in Classes X, XI, and XII.\nOne-time grant of ₹20,000 when the beneficiary attains 18 years of age and fulfills the scheme conditions.\nThe total assistance under the scheme is up to ₹40,000, transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', NULL, 'Multiple amounts specified (see benefit description)', 'One-time', 'One-time', NULL, 'Both', 'Apply through the Savitribai Phule Kishori Samriddhi Yojana Portal or through the concerned school/Block office.\nFill in the application form and upload/submit the required documents.\nThe application is verified by the school and the concerned district authorities.\nUpon approval, the eligible financial assistance is credited directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Children', 0, 1, 123),
  (124, 'JK-SCH-0124', 'Guruji Student Credit Card (GSCC) Scheme', 'GSCC', 'guruji-student-credit-card-gscc-scheme', NULL, 'State', 15, 5, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a domicile of Jharkhand.\nAge should not exceed 40 years.\nMust have passed:\nClass 10 from a recognized school in Jharkhand (for diploma courses), or\nClasses 10 and 12 from recognized schools in Jharkhand (for undergraduate and higher courses).\nMust have secured admission to an eligible recognized institution in India or abroad, as per the scheme guidelines (including specified institutions or those meeting prescribed NIRF/NAAC criteria).\nShould not have previously availed benefits under the GSCC for the same course', 'Aadhaar Card.\nDomicile Certificate.\nClass 10 and 12 mark sheets/certificates (as applicable).\nAdmission letter and fee receipt.\nCourse fee structure/prospectus.\nPAN Card.\nPassport-size photograph and signature.\nCo-applicant\'s identity/address proof and photograph.\nBank account details', 'Credit / Subsidy', 'Education loan up to ₹15 lakh without collateral.\nSubsidized simple interest rate of 4% per annum.\nNo processing fee.\nRepayment period of up to 15 years, including a one-year moratorium after course completion or employment (whichever is earlier).\nLoan covers tuition fees, hostel charges, books, laptops, and other approved education-related expenses', 1500000.0, NULL, 'Recurring', 'Annual', NULL, 'Both', 'Visit the official Guruji Student Credit Card (GSCC) Portal and register as a new applicant.\nComplete the online application form and upload the required documents.\nSubmit the application for verification by the Department of Higher and Technical Education.\nUpon approval, the application is forwarded to the designated bank for loan sanction.\nAfter the loan is sanctioned, the amount is disbursed as per the approved education expenses', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Youth GSCC', 0, 1, 124),
  (125, 'JK-SCH-0125', 'Universal Pension Scheme (Sarvajan Pension Yojana)', NULL, 'universal-pension-scheme-sarvajan-pension-yojana', NULL, 'State', 15, 23, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Jharkhand.\nEligible categories include:\nSenior citizens aged 60 years and above.\nWidows aged 18 years and above.\nPersons with at least 40% disability.\nEligible single/abandoned women and persons living with HIV/AIDS.\nThe applicant or an immediate family member should not be an income tax payer.\nThe applicant or an immediate family member should not be a permanent employee of the Central/State Government or a Public Sector Undertaking (PSU)', 'Aadhaar Card.\nResidence (Domicile) Certificate.\nBank account passbook.\nPassport-size photograph.\nProof of age (for old-age pension).\nHusband\'s Death Certificate (for widow pension).\nDisability Certificate (for disability pension).\nMedical certificate from an ART Centre/Government Hospital (for HIV/AIDS pension).\nMobile number', 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nCovers the following categories:\nOld Age Pension (60 years and above).\nWidow Pension.\nDisability Pension (40% or more disability).\nSingle/abandoned women (as per scheme guidelines).\nPension for persons living with HIV/AIDS.\nPension is credited directly to the beneficiary\'s bank account every mon', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 'Both', 'Visit the Jharkhand Social Security Pension Portal or the nearest Block Development Office (BDO), Pragya Kendra/Common Service Centre (CSC), or District Social Security Office.\nSelect the appropriate pension category and complete the application form.\nUpload or submit the required documents.\nThe application is verified by the concerned authorities.\nUpon approval, the pension is transferred directly to the beneficiary\'s bank account through DBT', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Elderly, Women, PwD/Chronic Diseases', 0, 1, 125);
INSERT INTO `schemes` (`id`, `scheme_code`, `name`, `short_name`, `slug`, `description`, `scheme_level`, `state_id`, `theme_id`, `service_approach_id`, `priority_id`, `feasibility_id`, `ministry_id`, `department_id`, `ministry_name`, `department_name`, `scheme_status`, `active_enrollment`, `launch_year`, `target_group_summary`, `eligibility_summary`, `benefit_type`, `benefit_description`, `benefit_amount`, `benefit_amount_text`, `benefit_mode`, `benefit_frequency`, `benefit_conditions`, `application_mode`, `application_process`, `application_instructions`, `portal_url`, `csc_available`, `physical_office`, `helpline_number`, `source_url`, `source_website`, `last_verified_date`, `verified_by`, `keywords`, `view_count`, `is_active`, `source_row_no`) VALUES
  (126, 'JK-SCH-0126', 'Mukhyamantri Maiya Samman Yojana', NULL, 'mukhyamantri-maiya-samman-yojana', NULL, 'State', 15, 23, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Jharkhand.\nMust be a woman aged 18–50 years.\nAnnual family income should generally not exceed ₹8 lakh.\nMust possess an Aadhaar-linked bank account.\nThe applicant or her family should not include an income tax payer, a regular Central/State Government or PSU employee, or a recipient of certain government pensions, as per the scheme guidelines', 'Aadhaar Card.\nVoter ID.\nRation Card.\nResidence (Domicile) Certificate.\nAadhaar-linked bank passbook.\nPassport-size photograph.\nMobile number.\nSelf-declaration/undertaking as prescribed by the Government', 'Cash Benefit', '₹2,500 per month (₹30,000 per year) transferred directly to the beneficiary\'s Aadhaar-linked bank account through DBT.\nPromotes women\'s financial independence and supports household expenses.\nNo contribution is required from the beneficiary', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 'Offline', 'Obtain the application form from the Gram Panchayat, Block Office, Anganwadi Centre, Pragya Kendra (CSC), or designated enrolment camp.\nFill in the application form and attach the required documents.\nSubmit the application to the designated authority for verification.\nAfter successful verification and approval, the financial assistance is credited directly to the beneficiary\'s Aadhaar-linked bank account through DBT', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance Women', 0, 1, 126),
  (127, 'JK-SCH-0127', 'Abua Awas Yojana', NULL, 'abua-awas-yojana', NULL, 'State', 15, 15, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Jharkhand.\nMust be homeless or living in a kutcha house.\nIncludes Particularly Vulnerable Tribal Groups (PVTGs), released bonded labourers, victims of natural calamities, and other eligible vulnerable households.\nShould not have received benefits under PMAY-G, Birsa Awas Yojana, Indira Awas Yojana, or other notified government housing schemes.\nFamilies owning a pucca house or meeting certain exclusion criteria (such as specified assets or government employment) are not eligible', 'Aadhaar Card.\nDomicile/Residence Certificate.\nIncome Certificate.\nBank account details/passbook.\nMobile number.\nLand ownership/possession documents (where applicable).\nCaste Certificate (if applicable).\nPassport-size photograph', 'Cash Benefit', 'Financial assistance of ₹2 lakh for construction of a pucca house.\nHouse of approximately 31 sq. metres with three rooms, a kitchen, and a toilet.\n95 days of MGNREGA wages for eligible beneficiaries to support house construction.\nFinancial assistance is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', 200000.0, NULL, NULL, NULL, NULL, 'Offline', 'Obtain the application form free of cost from the Gram Panchayat, Block Office, or designated government camps.\nFill in the application form and attach the required documents.\nSubmit the application to the designated authority.\nThe Gram Sabha and concerned officials verify the applicant\'s eligibility.\nUpon approval, financial assistance is released in instalments directly to the beneficiary\'s bank account as construction progresses', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Housing Minorities', 0, 1, 127),
  (128, 'JK-SCH-0128', 'Jharkhand State Food Security Scheme (JSFSS)', 'JSFSS', 'jharkhand-state-food-security-scheme-jsfss', NULL, 'State', 15, 14, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Jharkhand.\nMust belong to an economically vulnerable household as per state eligibility criteria.\nMust possess or be eligible for a Green Card issued under the Jharkhand State Food Security Scheme (JSFSS).\nHouseholds already covered under the National Food Security Act (NFSA) are generally not eligible under JSFSS', 'Aadhaar Card.\nResidence (Domicile) Certificate.\nGreen Card (or documents required for Green Card issuance).\nIncome Certificate (where applicable).\nBank account details (if required).\nPassport-size photograph', 'Insurance Cover', 'Subsidized or free rice for eligible Green Card holders.\nMonthly distribution of food grains through the Public Distribution System (PDS).\nEnsures food security for economically weaker and vulnerable households excluded from NFSA coverage', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Visit the nearest Fair Price Shop (PDS Dealer), Block Office, or Common Service Centre (CSC)/Pragya Kendra.\nObtain and complete the Green Card/JSFSS application form.\nSubmit the required documents for verification.\nAfter approval, a Green Card is issued to the eligible household.\nBeneficiaries can collect their monthly food grain entitlement from the designated Fair Price Shop', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Food Security Universal JSFSS', 0, 1, 128),
  (129, 'JK-SCH-0129', 'Birsa Harit Gram Yojana (BHGY)', 'BHGY', 'birsa-harit-gram-yojana-bhgy', NULL, 'State', 15, 9, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Jharkhand.\nMust possess a valid MGNREGA Job Card.\nPriority is given to:\nScheduled Castes (SC) and Scheduled Tribes (ST).\nSmall and marginal farmers.\nLandless and Below Poverty Line (BPL) families.\nWomen-headed households.\nPersons with disabilities.\nPMAY beneficiaries and other vulnerable rural households, as per scheme guidelines', 'Aadhaar Card.\nMGNREGA Job Card.\nResidence (Domicile) Certificate.\nCaste Certificate (if applicable).\nLand ownership/possession certificate or landlessness certificate (as applicable).\nBank account passbook.\nPassport-size photograph', 'In-kind / Material', 'Plantation of fruit-bearing and fodder trees on eligible land.\nUp to 100 days of wage employment under MGNREGA for plantation and maintenance activities.\nUsufruct rights (right to use and benefit from the produce) for eligible beneficiaries.\nPromotes long-term income generation through horticulture and agroforestry while improving environmental sustainability', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Contact the Gram Panchayat, Mukhiya, Village Head, MGNREGA Office, or Block Development Office (BDO).\nSubmit the prescribed application along with the required documents.\nBeneficiaries are identified and approved by the Gram Sabha.\nAfter verification, plantation activities are undertaken under the MGNREGA framework.\nEligible beneficiaries receive wage payments and long-term benefits from the plantation as per the scheme guidelines', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Minorities, Women, Farmers, PwD/Chronic Diseases BHGY', 0, 1, 129),
  (130, 'JK-SCH-0130', 'Mukhyamantri Pashudhan Vikas Yojana (MPVY)', 'MPVY', 'mukhyamantri-pashudhan-vikas-yojana-mpvy', NULL, 'State', 15, 9, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Jharkhand.\nMust be a farmer or livestock rearer.\nPreference is given to SC/ST, economically weaker households, women, widows, persons with disabilities, and other vulnerable groups.\nApplicant should have adequate land/shelter and basic facilities for rearing livestock.\nLivestock training may be required for certain components of the scheme', 'Aadhaar Card.\nDomicile (Residence) Certificate.\nRation Card.\nCaste Certificate (if applicable).\nLand ownership/possession documents.\nBank account passbook.\nPassport-size photograph.\nMobile number.\nLivestock training certificate (where applicable).\nDisability/Widow certificate (if applicable)', 'Training', 'Subsidy for the purchase of milch cattle (cow/buffalo), goats, pigs, ducks, and poultry.\nSubsidy up to 90% for eligible women, widows, persons with disabilities, and other notified vulnerable categories; up to 75% for other eligible beneficiaries (as per prevailing government norms).\nSupport for animal care training and scientific livestock management.\nPromotes self-employment and sustainable livelihood opportunities in rural areas', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Visit the nearest District Animal Husbandry Office, Block Animal Husbandry Office, or designated livestock development centre.\nObtain and complete the prescribed application form.\nAttach the required documents and submit the application.\nThe application is verified by the concerned authorities, and beneficiaries are selected according to the scheme guidelines.\nUpon approval, the subsidy and livestock assistance are provided through the implementing department', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Livelihood Farmers, Minorities MPVY', 0, 1, 130),
  (131, 'JK-SCH-0131', 'Phoolo-Jhano Ashirwad Abhiyan', NULL, 'phoolo-jhano-ashirwad-abhiyan', NULL, 'State', 15, 25, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Jharkhand.\nWomen who are engaged in the production or sale of traditional liquor (Hadiya/Daru) and are willing to shift to an alternative livelihood.\nPreference is given to women associated with or willing to join Self-Help Groups (SHGs)/Sakhi Mandals under JSLPS', 'Aadhaar Card.\nResidence (Domicile) Certificate.\nBank account passbook (Aadhaar-linked).\nPassport-size photograph.\nMobile number.\nSelf-Help Group (SHG) membership details (where applicable).\nAny additional documents required by JSLPS or the District Administration', 'Credit / Subsidy', 'Interest-free loan of up to ₹10,000 to start an alternative livelihood or micro-enterprise.\nCounselling, skill development, and handholding support for transitioning to sustainable occupations.\nLinkage with Self-Help Groups (Sakhi Mandals) and JSLPS for financial inclusion and livelihood support.\nAssistance in starting activities such as agriculture, animal husbandry, poultry, grocery shops, tailoring, forest produce enterprises, and other income-generating businesses', 10000.0, NULL, 'In-kind', NULL, NULL, 'Offline', 'Contact the Gram Panchayat, Block Development Office (BDO), or the nearest JSLPS/SHG (Sakhi Mandal).\nParticipate in the identification and counselling process conducted by JSLPS or district officials.\nSubmit the prescribed application form with the required documents.\nAfter verification, eligible women are linked with SHGs and provided skill training, counselling, and livelihood support.\nUpon approval, the interest-free loan and livelihood assistance are provided to establish an alternative source of income', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Women Empowerment Women', 0, 1, 131),
  (132, 'JK-SCH-0132', 'Jharkhand Building and Other Construction Workers Welfare Schemes (JBOCWWB)', 'JBOCWWB', 'jharkhand-building-and-other-construction-workers-welfare-schemes-jbocwwb', NULL, 'State', 15, 32, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a resident of Jharkhand.\nMust be a building or construction worker aged 18–60 years.\nMust have worked for at least 90 days in the preceding 12 months in building or construction work.\nMust be registered with the Jharkhand Building and Other Construction Workers Welfare Board (JBOCWWB) and possess a valid Labour Card', 'Aadhaar Card.\nResidence (Domicile) Certificate.\nAge proof.\nPassport-size photograph.\nBank account passbook.\nEmployment/Construction Worker Certificate from employer/contractor or other prescribed proof.\nLabour Card/JBOCWWB Registration Certificate.\nAdditional documents as required for the specific welfare scheme (e.g., medical records, educational certificates, death certificate, etc.)', 'Pension', 'Financial assistance for education, maternity, marriage, and medical treatment.\nAccident, disability, and death assistance for registered workers and their families.\nTool kit assistance, bicycle assistance, pension, housing assistance, and other welfare benefits under various schemes.\nSkill development and livelihood support for construction workers', NULL, NULL, 'In-kind', NULL, NULL, 'Both', 'Register as a construction worker with the Jharkhand Building and Other Construction Workers Welfare Board (JBOCWWB) through the Labour Department portal, District Labour Office, or Common Service Centre (CSC).\nObtain a valid Labour Card/Registration Certificate.\nApply for the specific welfare scheme online or through the District Labour Office/CSC by submitting the prescribed application form and required documents.\nThe application is verified by the concerned authorities.\nUpon approval, eligible benefits are provided through Direct Benefit Transfer (DBT) or as specified under the respective welfare scheme', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Worker Empowerment Universal JBOCWWB', 0, 1, 132),
  (133, 'JK-SCH-0133', 'Pre-Matric and Post-Matric Scholarship Schemes', NULL, 'pre-matric-and-post-matric-scholarship-schemes', NULL, 'State', 15, 5, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Jharkhand.\nMust belong to the SC, ST, BC, or Minority category.\nPre-Matric: Students studying in Classes I–X in a recognized school.\nPost-Matric: Students studying in Class XI or above in a recognized institution.\nMust satisfy the income criteria prescribed by the Government for the respective scholarship category', 'Aadhaar Card.\nDomicile (Residence) Certificate.\nCaste Certificate (where applicable).\nIncome Certificate.\nPrevious examination mark sheet.\nBonafide/Admission Certificate from the institution.\nBank account passbook (Aadhaar-linked).\nPassport-size photograph.\nMobile number', 'Scholarship / Fee Support', 'Financial assistance towards tuition fees, maintenance allowance, hostel fees, and other educational expenses.\nPre-Matric Scholarship: For students studying from Class I to Class X.\nPost-Matric Scholarship: For students pursuing Class XI onwards, including Intermediate, ITI, Diploma, Undergraduate, Postgraduate, Professional, and Technical courses.\nScholarship amount is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', NULL, NULL, NULL, NULL, NULL, 'Both', 'Visit the e-Kalyan Jharkhand Portal.\nRegister as a new applicant and complete the online application form.\nUpload the required documents.\nSubmit the application for verification by the educational institution and district authorities.\nUpon approval, the scholarship amount is credited directly to the beneficiary\'s bank account through DBT', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Education Minorities', 0, 1, 133),
  (134, 'JK-SCH-0134', 'Mukhyamantri Sukhad Rahat Yojana (MSRY)', 'MSRY', 'mukhyamantri-sukhad-rahat-yojana-msry', NULL, 'State', 15, 23, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Must be a permanent resident of Jharkhand.\nMust be a farmer cultivating agricultural land in a drought-affected notified area.\nBoth land-owning farmers and eligible sharecroppers/tenant farmers may apply, subject to government guidelines.\nThe applicant should not be an income tax payer or fall under other exclusion criteria prescribed by the State Government\nResidents of Manipur belonging to eligible low-income households who are not covered under other government health insurance schemes', 'Aadhaar Card.\nResidence (Domicile) Certificate.\nLand records or proof of cultivation (where applicable).\nBank account passbook (Aadhaar-linked).\nPassport-size photograph.\nMobile number.\nRation Card (if required for verification)\nPermanent resident of Manipur belonging to an eligible low-income household and fulfilling the prescribed scheme criteria', 'Insurance Cover', 'One-time drought relief assistance of ₹3,500 to eligible farmer families affected by drought.\nFinancial assistance is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT).\nSupports farmers in meeting immediate livelihood and agricultural expenses after crop loss due to drought\nCashless health insurance coverage for secondary and tertiary medical treatment at empanelled hospitals, subject to scheme guidelines', 3500.0, NULL, 'One-time', 'One-time', NULL, 'Both', 'Visit the Mukhyamantri Sukhad Rahat Yojana Portal or the nearest Common Service Centre (CSC)/Pragya Kendra, Gram Panchayat, or Block Agriculture Office.\nComplete the registration/application form and upload or submit the required documents.\nThe application is verified by the concerned district and agriculture authorities.\nAfter approval, the relief amount is credited directly to the beneficiary\'s bank account through DBT\nApply through designated CMHT enrolment centres/Common Service Centres (CSCs) or the Health Department with required documents', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Financial Assistance, Health Insurance Farmers, Low-income Families MSRY', 0, 1, 134),
  (135, 'JK-SCH-0135', 'Start-up Manipur', NULL, 'start-up-manipur', NULL, 'State', 22, 11, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Aspiring and existing entrepreneurs in Manipur', 'Applicant must be above 18 years and a business person', 'Cash Benefit', '1) Idea-stage startups: Grant funding up to ₹3 lakh. 2) Revenue-stage startups: Grant funding up to ₹100 lakh', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 'Online', 'Apply through the Start-up Manipur portal or the concerned implementing department with the required documents', NULL, NULL, 0, NULL, NULL, 'https://startupmanipur.in', 'startupmanipur.in', NULL, NULL, 'Entrepreneurship & Livelihood Entrepreneurs', 0, 1, 135),
  (136, 'JK-SCH-0136', 'Ima Nongthangleima Yaipha Tengbang', NULL, 'ima-nongthangleima-yaipha-tengbang', NULL, 'State', 22, 17, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Eligible women of Manipur, particularly economically vulnerable women aged 40 years and above', 'Permanent resident of Manipur and fulfilling the eligibility criteria prescribed by the Government under the scheme', 'Cash Benefit', 'Monthly financial assistance to eligible women to enhance their social and economic security', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Apply through the Department of Social Welfare or the concerned District Social Welfare Office with the prescribed application form and supporting documents', NULL, NULL, 0, NULL, NULL, 'https://socialwelfare.mn.gov.in/', 'socialwelfare.mn.gov.in', NULL, NULL, 'Social Security / Financial Assistance Women', 0, 1, 136),
  (137, 'JK-SCH-0137', 'Chief Ministergi Shontharabasingi Tengbang (CMST)', 'CMST', 'chief-ministergi-shontharabasingi-tengbang-cmst', NULL, 'State', 22, 17, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Persons with disabilities and vulnerable elderly people', 'Persons with disabilities and vulnerable elderly people', 'Scholarship / Fee Support', 'Scholarship for students with disabilities; Caregiver allowance for persons with severe disabilities; Maintenance grant for homeless older persons', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Apply through the Department of Social Welfare, Government of Manipur or the concerned District Social Welfare Office with the prescribed application form and supporting documents', NULL, NULL, 0, NULL, NULL, 'https://socialwelfare.mn.gov.in/', 'socialwelfare.mn.gov.in', NULL, NULL, 'Social Security Persons with Disabilities and Senior Citizens CMST', 0, 1, 137),
  (138, 'JK-SCH-0138', 'Chief Ministergi Artistsinggi Tengbang (CMAT)', 'CMAT', 'chief-ministergi-artistsinggi-tengbang-cmat', NULL, 'State', 22, 17, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Eligible artists and cultural practitioners of Manipur', 'Permanent resident of Manipur engaged in art and culture and fulfilling the eligibility criteria prescribed by the Government', 'Cash Benefit', 'Financial assistance and welfare support for eligible artists, including support during hardship, subject to scheme guidelines', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Apply through the Department of Art & Culture or the designated district office with the prescribed application form and supporting documents', NULL, NULL, 0, NULL, NULL, 'https://artandculture.mn.gov.in/', 'artandculture.mn.gov.in', NULL, NULL, 'Social Security / Livelihood Support Artists CMAT', 0, 1, 138),
  (139, 'JK-SCH-0139', 'Vocational Training of Destitute Women and Adolescent Girl Scheme', NULL, 'vocational-training-of-destitute-women-and-adolescent-girl-scheme', NULL, 'State', 22, 6, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Economically vulnerable destitute women and adolescent girls in Manipur', 'Destitute women and adolescent girls who are permanent residents of Manipur and meet the eligibility criteria prescribed by the Department', 'Training', 'Free vocational training in income-generating trades to enhance employability and promote self-employment', NULL, NULL, 'In-kind', NULL, NULL, 'Offline', 'Apply through the Directorate/Department of Social Welfare or the concerned District Social Welfare Office with the prescribed application form and supporting documents', NULL, NULL, 0, NULL, NULL, 'https://socialwelfare.mn.gov.in/', 'socialwelfare.mn.gov.in', NULL, NULL, 'Skill Development & Livelihood Destitute Women and Adolescent Girls', 0, 1, 139),
  (140, 'JK-SCH-0140', 'Orunodoi', NULL, 'orunodoi', NULL, 'State', 4, 17, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Low-income households headed by women', 'Permanent resident of Assam; economically weaker household; woman as primary beneficiary; not ordinarily an income-tax payer or government employee/pensioner (as per Government guidelines)', 'Cash Benefit', 'Monthly financial assistance through Direct Benefit Transfer (DBT) to support essential household expenses such as food, medicines, and utilities', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Beneficiaries are identified and verified by district administration/local authorities; eligible beneficiaries are enrolled by the Government', NULL, NULL, 0, NULL, NULL, 'https://finance.assam.gov.in', 'finance.assam.gov.in', NULL, NULL, 'Social Protection / Cash Transfer Women', 0, 1, 140),
  (141, 'JK-SCH-0141', 'Nijut Moina', NULL, 'nijut-moina', NULL, 'State', 4, 5, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Girl students pursuing Higher Secondary and higher education', 'Permanent resident of Assam; enrolled in eligible institution in Assam; studying in eligible course as notified by Government', 'Cash Benefit', 'Monthly financial assistance through DBT to eligible girl students to encourage continuation of higher education and discourage child marriage', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Eligible students are identified through educational institutions; institutions verify records and submit details to Government for approval and DBT', NULL, NULL, 0, NULL, NULL, 'https://highereducation.assam.gov.in', 'highereducation.assam.gov.in', NULL, NULL, 'Education / Girl Child Empowerment Women', 0, 1, 141),
  (142, 'JK-SCH-0142', 'Abhinandan', NULL, 'abhinandan', NULL, 'State', 4, 5, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Students with eligible education loans', 'Permanent resident of Assam; education loan from a scheduled commercial bank/recognized financial institution for higher studies; fulfills Government eligibility criteria', 'Credit / Subsidy', 'One-time education loan subsidy of ₹50,000 credited towards the eligible education loan account', 50000.0, NULL, 'One-time', 'One-time', NULL, 'Offline', 'Eligible education loan accounts are identified through participating banks or as per Government notification; verification is carried out before release of subsidy', NULL, NULL, 0, NULL, NULL, 'https://highereducation.assam.gov.in', 'highereducation.assam.gov.in', NULL, NULL, 'Education / Financial Assistance Universal', 0, 1, 142),
  (143, 'JK-SCH-0143', 'Atmanirbhar Asom', NULL, 'atmanirbhar-asom', NULL, 'State', 4, 9, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Educated unemployed youth, aspiring entrepreneurs and eligible MSMEs', 'Permanent resident of Assam; eligible unemployed youth or entrepreneur; fulfills Government criteria; viable business proposal under eligible sectors', 'Training', 'Financial assistance, capital subsidy, entrepreneurship support, skill development and bank linkage for setting up or expanding enterprises', NULL, NULL, NULL, NULL, NULL, 'Online', 'Apply through the notified Government portal/department. Applications are verified by district/state authorities before approval and release of assistance', NULL, NULL, 0, NULL, NULL, 'https://industries.assam.gov.in', 'industries.assam.gov.in', NULL, NULL, 'Livelihood / Entrepreneurship Universal', 0, 1, 143),
  (144, 'JK-SCH-0144', 'Mukhyamantri Mahila Udyamita Abhiyan (MMUA)', 'MMUA', 'mukhyamantri-mahila-udyamita-abhiyan-mmua', NULL, 'State', 4, 25, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Women members of Self-Help Groups (SHGs) under ASRLM', 'Permanent resident of Assam; active member of an eligible SHG under Assam State Rural Livelihoods Mission (ASRLM); fulfills scheme guidelines', 'Cash Benefit', 'Financial assistance to establish or expand income-generating activities, livelihood support, enterprise development, and capacity building for eligible SHG women', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Applications are processed through ASRLM, Block Mission Management Units (BMMUs), and Panchayat & Rural Development Department after verification of eligibility', NULL, NULL, 0, NULL, NULL, 'https://pnrd.assam.gov.in', 'pnrd.assam.gov.in', NULL, NULL, 'Women Entrepreneurship / Livelihood Women MMUA', 0, 1, 144),
  (145, 'JK-SCH-0145', 'Kanaklata Mahila Sabalikaran Yojana (KMSY)', 'KMSY', 'kanaklata-mahila-sabalikaran-yojana-kmsy', NULL, 'State', 4, 25, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Women members of Self-Help Groups (SHGs)', 'Permanent resident of Assam; active member of an eligible SHG under Assam State Rural Livelihoods Mission (ASRLM); SHG must meet eligibility norms prescribed by the Government', 'Credit / Subsidy', 'Financial assistance, revolving fund support, bank credit linkage, capacity building, entrepreneurship promotion, and livelihood support for eligible SHGs', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Eligible SHGs are identified through ASRLM. Applications are processed through Village Organisations, Block Mission Management Units (BMMUs), and the Panchayat & Rural Development Department after verification', NULL, NULL, 0, NULL, NULL, 'https://pnrd.assam.gov.in', 'pnrd.assam.gov.in', NULL, NULL, 'Women Empowerment / Financial Inclusion / Livelihood Women KMSY', 0, 1, 145),
  (146, 'JK-SCH-0146', 'Assam Micro Finance Incentive and Relief Scheme (AMFIRS)', 'AMFIRS', 'assam-micro-finance-incentive-and-relief-scheme-amfirs', NULL, 'State', 4, 24, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Women members of Self-Help Groups (SHGs) with eligible microfinance loans', 'Permanent resident of Assam; woman SHG member with an eligible microfinance loan from a recognized MFI/bank; fulfills Government eligibility criteria', 'Credit / Subsidy', 'Financial incentive and relief for eligible microfinance borrowers, including support for repayment and reduction of loan burden as per Government guidelines', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Eligible beneficiaries are identified through Microfinance Institutions (MFIs), banks, and Government records. Applications/verification are processed as per Government guidelines before release of assistance', NULL, NULL, 0, NULL, NULL, 'https://finance.assam.gov.in', 'finance.assam.gov.in', NULL, NULL, 'Financial Inclusion / Women Empowerment Women AMFIRS', 0, 1, 146),
  (147, 'JK-SCH-0147', 'Apun Bahan Scheme', NULL, 'apun-bahan-scheme', NULL, 'State', 4, 33, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Eligible women employees of the Government of Assam and notified organizations', 'Permanent resident of Assam; eligible woman employee of the Government of Assam or notified organization; vehicle loan from a participating bank; fulfills scheme guidelines', 'Credit / Subsidy', 'Interest subsidy on vehicle loan for purchase of a new vehicle to improve safe and affordable mobility', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Apply for a vehicle loan through a participating bank. After employer and bank verification, eligible beneficiaries receive the interest subsidy as per Government guidelines', NULL, NULL, 0, NULL, NULL, 'https://finance.assam.gov.in', 'finance.assam.gov.in', NULL, NULL, 'Transport Support / Women Empowerment Women', 0, 1, 147),
  (148, 'JK-SCH-0148', 'Pragyan Bharati Scheme', NULL, 'pragyan-bharati-scheme', NULL, 'State', 4, 5, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Students pursuing Higher Secondary and higher education in eligible institutions', 'Permanent resident of Assam; enrolled in a recognized educational institution; fulfills eligibility criteria prescribed by the Government for the relevant academic year', NULL, 'Educational assistance through digital learning support (such as laptops/tablets or other notified benefits) to promote higher education and digital access', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Eligible students are identified through educational institutions and examination records. The Higher Education Department verifies eligibility and distributes benefits as per Government guidelines', NULL, NULL, 0, NULL, NULL, 'https://highereducation.assam.gov.in', 'highereducation.assam.gov.in', NULL, NULL, 'Education / Digital Inclusion Universal', 0, 1, 148),
  (149, 'JK-SCH-0149', 'Bhasha Gaurav Scheme', NULL, 'bhasha-gaurav-scheme', NULL, 'State', 4, 5, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Students studying approved indigenous languages in recognized schools', 'Permanent resident of Assam; enrolled in a recognized school in Assam; studying an approved indigenous language as per Government guidelines', 'Scholarship / Fee Support', 'Educational incentive/scholarship to encourage students to study and preserve indigenous languages of Assam', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Eligible students are identified through their schools. Schools submit beneficiary details to the Secondary Education Department for verification and sanction', NULL, NULL, 0, NULL, NULL, 'https://secondaryeducation.assam.gov.in', 'secondaryeducation.assam.gov.in', NULL, NULL, 'Education / Language Promotion Universal', 0, 1, 149),
  (150, 'JK-SCH-0150', 'Swahid Kushal Konwar Universal Old Age Pension Scheme', NULL, 'swahid-kushal-konwar-universal-old-age-pension-scheme', NULL, 'State', 4, 17, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Senior Citizens (60 years and above)', 'Permanent resident of Assam; 60 years or above; fulfills eligibility criteria prescribed by the Government of Assam; not receiving similar pension where restricted', 'Pension', 'Monthly social security pension through Direct Benefit Transfer (DBT) to eligible senior citizens', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Eligible persons apply through the Gaon Panchayat, Urban Local Body, Block Office, or District Social Welfare Office. Applications are verified before approval and sanction', NULL, NULL, 0, NULL, NULL, 'https://socialjustice.assam.gov.in', 'socialjustice.assam.gov.in', NULL, NULL, 'Social Security / Old Age Pension Universal', 0, 1, 150);
