  (151, 'JK-SCH-0151', 'Indira Miri Universal Widow Pension Scheme', NULL, 'indira-miri-universal-widow-pension-scheme', NULL, 'State', 4, 17, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Widowed women', 'Permanent resident of Assam; widow; fulfills eligibility criteria prescribed by the Government of Assam', 'Pension', 'Monthly social security pension through Direct Benefit Transfer (DBT) to eligible widowed women', NULL, NULL, 'Recurring', 'Monthly', NULL, 'Offline', 'Apply through the Gaon Panchayat, Urban Local Body, Block Office, or District Social Welfare Office. Applications are verified before approval and sanction', NULL, NULL, 0, NULL, NULL, 'https://socialjustice.assam.gov.in', 'socialjustice.assam.gov.in', NULL, NULL, 'Social Security / Widow Pension Women', 0, 1, 151),
  (152, 'JK-SCH-0152', 'Deen Dayal Divyangjan Achoni (DDDA)', 'DDDA', 'deen-dayal-divyangjan-achoni-ddda', NULL, 'State', 4, 20, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Persons with Disabilities (PwDs)', 'Permanent resident of Assam; valid Disability Certificate/UDID; fulfills eligibility criteria prescribed by the Government of Assam', 'Cash Benefit', 'Financial assistance, rehabilitation support, assistive devices, and linkage with disability welfare services for eligible persons with disabilities', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Apply through the District Social Welfare Office or designated authority. Applications are verified based on disability certificate and eligibility before approval', NULL, NULL, 0, NULL, NULL, 'https://socialjustice.assam.gov.in', 'socialjustice.assam.gov.in', NULL, NULL, 'Disability Support / Social Security Universal DDDA', 0, 1, 152),
  (153, 'JK-SCH-0153', 'Arogya Nidhi', NULL, 'arogya-nidhi', NULL, 'State', 4, 1, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Economically weaker patients requiring treatment for serious illnesses', 'Permanent resident of Assam; economically weaker patient requiring treatment for a serious illness; fulfills eligibility criteria prescribed by the Government', 'Cash Benefit', 'Financial assistance for treatment, surgery, medicines, diagnostics, and hospitalization for eligible patients as per Government guidelines', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Apply through the treating Government hospital or designated authority with required medical documents. Applications are verified before sanction of financial assistance', NULL, NULL, 0, NULL, NULL, 'https://health.assam.gov.in', 'health.assam.gov.in', NULL, NULL, 'Health Care / Medical Financial Assistance Universal', 0, 1, 153),
  (154, 'JK-SCH-0154', 'Eti Koli Duti Paat Scheme', NULL, 'eti-koli-duti-paat-scheme', NULL, 'State', 4, 9, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Registered tea garden workers in Assam', 'Permanent resident of Assam; registered worker of a recognized tea garden/estate; fulfills Government eligibility criteria', 'Cash Benefit', 'Financial assistance through Direct Benefit Transfer (DBT) and welfare support to improve livelihood and socio-economic security of tea garden workers', NULL, NULL, NULL, NULL, NULL, 'Offline', 'Eligible beneficiaries are identified through tea garden management and district authorities. Verification is carried out before release of assistance through DBT', NULL, NULL, 0, NULL, NULL, 'https://ttwd.assam.gov.in', 'ttwd.assam.gov.in', NULL, NULL, 'Livelihood / Tea Garden Welfare Universal', 0, 1, 154),
  (155, 'JK-SCH-0155', 'Wage Compensation Scheme for Pregnant Women (PW) in Tea Garden Areas', 'PW', 'wage-compensation-scheme-for-pregnant-women-pw-in-tea-garden-areas', NULL, 'State', 4, 1, 4, NULL, NULL, NULL, NULL, NULL, NULL, 'Active', 1, NULL, 'Pregnant Women & Lactating Mothers', 'Applies to casual or permanent resident pregnant women in tea garden areas. The scheme is limited to the first two living children, and beneficiaries must be at least 18 years old', 'Cash Benefit', 'A total cash assistance of ₹15,000 provided in four installments', 15000.0, NULL, 'Recurring', 'In instalments', NULL, 'Offline', 'Register pregnancy through ASHA/ANM at the nearest Government Health Facility. Eligibility is verified, and benefits are provided through DBT upon meeting scheme conditions', NULL, NULL, 0, NULL, NULL, 'https://nhm.assam.gov.in/schemes/wage-compensation-scheme', 'nhm.assam.gov.in', NULL, NULL, 'Health Care Women PW', 0, 1, 155),
