INSERT INTO `scheme_benefits` (`scheme_id`, `benefit_type`, `description`, `amount`, `amount_text`, `mode`, `frequency`, `conditions`, `sort_order`) VALUES
  (1, 'Cash Benefit', 'Cash incentive of ₹5,000 in three installments: ₹1,000 on early pregnancy registration, ₹2,000 after six months, and ₹2,000 post-birth for meeting health requirements', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'In instalments', NULL, 1),
  (2, 'In-kind / Material', 'Supplementary Nutrition (SNP),\nHealth & Nutrition Check-Up,\nImmunization,\nNon-Formal Education for Children in Pre-School,\nHealth and Nutrition Education,\nReferral services', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (3, 'Training', 'To give training to grass root level ICDS functionaries on Infant and young child feeding practices.\nTo generate awareness on Infant Young Child Feeding Practices', NULL, NULL, NULL, NULL, NULL, 1),
  (4, 'In-kind / Material', 'health services, nutritional support, educational support, and awareness programme', NULL, NULL, NULL, NULL, NULL, 1),
  (5, NULL, '1. Safe Accommodation\n2. Affordable Rent\n3.Additional facilities\n4. Empowerment', NULL, NULL, NULL, NULL, NULL, 1),
  (6, 'In-kind / Material', 'Prevent and reduce Stunting in children (0- 6 years)\nPrevent and reduce under-nutrition (underweight prevalence) in children (0-6 years)\nReduce the prevalence of anemia among young Children(6-59 months)\nReduce the prevalence of anemia among Women and Adolescent Girls in the age group of 15-49 years\nReduce Low Birth Weight (LBW)', NULL, NULL, NULL, NULL, NULL, 1),
  (7, 'Cash Benefit', '1. Immediate financial assistance or relief to cover urgent needs.\n2. Access to shelter and temporary accommodation.\n3. Legal aid and counseling services.\n4. Medical support and access to healthcare facilities.\n5. Assistance with filing complaints and navigating the legal system', NULL, NULL, NULL, NULL, NULL, 1),
  (8, 'Service Delivery', '1. Immediate emergency assistance and support.\n2. Access to counseling and guidance for dealing with distressing situations.\n3. Connection to local services such as police, legal aid, and medical facilities.\n4. Support for filing complaints and obtaining protection if necessary', NULL, NULL, NULL, NULL, NULL, 1),
  (9, 'In-kind / Material', '1. Financial incentives and support for the education of girl children.\n2. Awareness programs and community outreach to improve attitudes towards the education and well-being of girls.\n3. Health and nutrition support for girls.\n4. Support for ensuring the safety and protection of girls from gender-based violence and discrimination', NULL, NULL, NULL, NULL, NULL, 1),
  (10, 'Service Delivery', '1. Medical Assistance\n2. Legal Aid\n3. Counseling Services\n4. Shelter\n5. Referral Services', NULL, NULL, NULL, NULL, NULL, 1),
  (11, 'Training', '1. Information and Counseling\n2. Training and Capacity Building\n3. Support Services\n4. Coordination of Services\n5. Awareness Programs', NULL, NULL, NULL, NULL, NULL, 1),
  (12, 'Service Delivery', '1. Financial Compensation\n2. Medical Support\n3. Legal Aid\n4. Rehabilitation Support\n5. Counseling Services', NULL, NULL, NULL, NULL, NULL, 1),
  (13, 'In-kind / Material', '1. Nutritional Support\n2. Breastfeeding Promotion\n3. Complementary Feeding\n4. Health Monitoring\n5. Counseling and Education', NULL, NULL, NULL, NULL, NULL, 1),
  (14, 'Training', '1. Nutritional Support\n2. Health Services\n3. Educational Support\n4. Skill Development\n5. Awareness Programs', NULL, NULL, NULL, NULL, NULL, 1),
  (15, 'Training', '1. Financial compensation to cover medical expenses, rehabilitation, and other related costs.\n2. Support for reconstructive surgery and long-term medical treatment.\n3. Assistance with psychological counseling and support services.\n4. Aid for reintegration into society, including vocational training and education if required', NULL, NULL, NULL, NULL, NULL, 1),
  (16, NULL, 'Compensation/immediate first-aid facility or medical benefits/any other interim relief (including interim monetary compensation)', NULL, NULL, NULL, NULL, NULL, 1),
  (17, NULL, 'Compensation/Free Legal Aid', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (18, 'Training', 'Ministry of Labour & Employment has developed eShram portal for creating a National Database of Unorganized Workers (NDUW), which will be seeded with Aadhaar. It will have details of name, occupation, address, occupation type, educational qualification, skill types etc. for optimum realization of their employability and extend the benefits of the social security schemes to them. It is the first-ever national database of unorganised workers including migrant workers, construction workers, gig and platform workers, etc', NULL, NULL, NULL, NULL, NULL, 1),
  (19, 'Pension', 'The scheme provides a minimum pension of ₹3,000 per month after age 60, with the Central Government contributing an equal amount to your monthly contribution', 3000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (20, 'Pension', 'Under the schemes, beneficiaries are entitled to receive monthly assured pension of Rs.3000/- after attaining the age of 60 years', 3000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (21, 'Cash Benefit', 'Rs.2 lakh on death due to any cause\nPremium @ Rs.436/- year', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1),
  (22, 'Insurance Cover', 'The risk coverage under the scheme is Rs. 2 lakh for accidental death and full disability and Rs. 1 lakh for partial disability.\nPremium @ 20/- year', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1),
  (23, 'Pension', 'The contributor on his choice, can attain a pension of 1000-5000 rupees, or he can also get an accumulated sum of the pension after his death.\nThe accumulated amount will be given to the spouse or if the spouse is dead as well then to the nominee', NULL, NULL, 'Recurring', NULL, NULL, 1),
  (24, 'In-kind / Material', '35 kg of rice or wheat every month, while a household above the poverty line is entitled to 15 kg of food grain on a monthly basis', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (25, NULL, 'Assistance provided to the Beneficiary to the tune of 1.2 Lakhs in plain areas and 1.3 Lakhs in Hilly Areas', NULL, NULL, NULL, NULL, NULL, 1);
INSERT INTO `scheme_benefits` (`scheme_id`, `benefit_type`, `description`, `amount`, `amount_text`, `mode`, `frequency`, `conditions`, `sort_order`) VALUES
  (26, 'Pension', 'Central Contribution @ Rs 300 to Rs 500 for different age group.\nMonthly pension ranges from Rs 1000 to rs 3000/ depending upon state’s contribution', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 1),
  (27, 'Insurance Cover', 'Health coverage of Rs. 5 lakhs per family per year for secondary and tertiary care hospitalization free of cost', 500000.0, NULL, 'Recurring', 'Annual', NULL, 1),
  (28, 'Insurance Cover', 'The beneficiaries would avail a package of Rs 15,000 that includes both pre-existing diseases and new diseases. The division in terms of disbursement of the amount according to the medical conditions stands as- Maternity benefits (per child for the first two)- Rs 2500, Eye treatment – Rs 75, Spectacles – Rs 250, Domiciliary Hospitalisation- Rs 4000, Ayurvedic/Unnani/Homeopathic/Siddha- Rs 4000, Hospitalization (including pre and post)- Rs 15000, Baby coverage-500, OPD and limit per illness- Rs 7500', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1),
  (29, 'Pension', 'Assured pension of Rs. 3000/- month\nVoluntary and Contributory Pension Scheme\nMatching Contribution by the Government of India', 3000.0, NULL, 'Recurring', NULL, NULL, 1),
  (30, 'Scholarship / Fee Support', 'The manual scavenger and the dependents (as defined in para 2.3.2) shall be provided, free of cost, skill training of their choice from the list of such trainings organized by the National Safai Karmacharis Finance and Development Corporation (NSKFDC) from time to time . A monthly stipend of Rs. 3000/-(Rupees three thousand only) or any such amount as may be decided from time to time to shall be remitted by NSKFDC', 3000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (31, 'Scholarship / Fee Support', 'NSKFDC gives low-interest loans through banks/State agencies for income activities such as:\n\nSmall business / shop / vending\nSanitation-related machinery or services\nE-rickshaw / green business\nAny viable self-employment activity/"Skill development training programs\nStipend during training (as per scheme rules)\nAwareness camps and job fairs\nSupport for rehabilitation activities', NULL, NULL, NULL, NULL, NULL, 1),
  (32, 'In-kind / Material', 'Any applicant is entitled to work within 15 days, for as many as he/she has applied, subject to a limit of 100 days per household per year.\nWage rate (220) has been increased and to be incorporated', NULL, NULL, 'Recurring', 'Annual', NULL, 1),
  (33, 'Training', 'Deen Dayal Upadhyaya Grameen Kaushalya Yojana (DDU-GKY) aims to skill rural youth who are poor and provide them with jobs having regular monthly wages or above the minimum wages', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (34, 'Credit / Subsidy', 'Organizing poor women into Self-Help Groups (SHGs).\nProviding access to bank loans and financial services.\nSkill development and livelihood promotion.\nSupport for entrepreneurship and income-generating activities.\nSpecial focus on vulnerable groups and women\'s economic empowerment./"Urban poor obtain skill training and wage employment.\nIndividuals and groups start micro-enterprises through bank-linked loans.\nUrban homeless access shelters and support services.\nStreet vendors access credit, social security, and livelihood support', NULL, NULL, NULL, NULL, NULL, 1),
  (35, 'Credit / Subsidy', 'To facilitate working capital loan up to 10,000.\nTo incentivize regular repayment.\nTo reward digital transactions', NULL, NULL, NULL, NULL, NULL, 1),
  (36, 'Training', 'Free skill training\nGovernment-recognized certification\nTraining in sectors such as IT, electronics, healthcare, retail, construction, AI, cybersecurity, drones, and more.\nCareer guidance and industry-relevant skills', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (37, 'Credit / Subsidy', 'PMEGP (Prime Minister Employment Generation Programme) helps individuals start a new business or micro-enterprise by providing a bank loan with a government subsidy of up to 35% of the project cost. It supports self-employment, entrepreneurship, and job creation in both rural and urban areas', NULL, NULL, NULL, NULL, NULL, 1),
  (38, 'Pension', 'A monthly pension of ₹ 200 up to 79 years and ₹ 500 thereafter', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 1),
  (39, 'Pension', 'A pension of Rs.300/- per month is provided to Widows between 40 years and 79 years. For persons who are 80 years and above the pension is Rs.500/- per month', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 1),
  (40, 'Insurance Cover', 'Establish unique identity across different healthcare providers within the healthcare ecosystem/Link all healthcare benefits ranging from public health programmes to insurance schemes to your unique ABHA number/Avoid long lines for registration in healthcare facilities across the country/Seamless sign up for PHR (Personal Health Records) applications such as ABDM application for health data sharing', NULL, NULL, NULL, NULL, NULL, 1),
  (41, 'Cash Benefit', 'The assistance amount depends on the state and whether the area is rural or urban. Common benefits include:\n\nCash assistance for institutional delivery.\nSupport through ASHA workers.\nAssistance for eligible home deliveries in certain cases', NULL, NULL, NULL, NULL, NULL, 1),
  (42, 'In-kind / Material', 'Highly subsidized food grains through ration shops.\nPHH beneficiaries: 5 kg food grains per person per month.\nAAY households: 35 kg food grains per household per month', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (43, 'Pension', 'Single national disability identity card.\nEasier access to disability-related schemes and benefits.\nOnline verification of disability certificates.\nReduces the need to carry multiple documents.\nFacilitates access to pensions, scholarships, assistive devices, travel concessions, and other government programs', NULL, NULL, NULL, NULL, NULL, 1),
  (44, 'Cash Benefit', 'Free LPG connection for eligible women.\nFinancial assistance for LPG connection setup.\nReduced indoor air pollution and smoke exposure.\nImproved health outcomes for women and children.\nCleaner and safer cooking fuel.\nTime saved from collecting traditional fuels.\nEnhanced convenience in cooking.\nWomen\'s empowerment through ownership of the LPG connection.\nReduced dependence on firewood, coal, and biomass fuels.\nEnvironmental benefits through cleaner energy use.\nAccess to subsidized LPG refills as per government policy', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (45, 'Credit / Subsidy', 'Government-backed savings scheme.\nAttractive interest rate notified by the Government from time to time.\nTax benefits under applicable provisions of the Income Tax Act.\nDeposits can be made until the account completes 15 years from opening.\nThe account matures 21 years from the date of opening or upon eligible closure conditions', NULL, NULL, NULL, NULL, NULL, 1),
  (46, 'Training', 'Safe shelter/accommodation\nFood and clothing\nMedical care and health services\nPsychological counseling\nLegal aid and guidance\nVocational training and skill development\nEconomic and social rehabilitation support', NULL, NULL, NULL, NULL, NULL, 1),
  (47, 'Training', 'Nutritional support (Take Home Ration/Hot Cooked Meal, depending on local implementation)\nIron and Folic Acid (IFA) supplementation\nHealth check-ups and referral services\nNutrition and health education\nLife skills education\nGuidance on public services, education, hygiene, and vocational skills', NULL, NULL, NULL, NULL, NULL, 1),
  (48, 'Training', 'Agricultural infrastructure development\nFarm machinery support\nCapacity building and training\nIrrigation and watershed development\nPost-harvest management facilities\nStartup incubation, mentoring, and funding support for agri-innovations', NULL, NULL, NULL, NULL, NULL, 1),
  (49, 'Insurance Cover', 'Insurance coverage for notified crops.\nFinancial assistance in case of crop loss due to drought, flood, cyclone, hailstorm, pest attack, disease, and other covered risks.\nStabilizes farmers\' income and encourages continued farming', NULL, NULL, 'Service', NULL, NULL, 1),
  (50, 'Training', 'Distribution of certified and quality seeds.\nCluster demonstrations and technology demonstrations.\nFarm machinery and agricultural implements.\nMicronutrients and soil amendments.\nPlant protection measures.\nTraining and capacity building programs', NULL, NULL, NULL, NULL, NULL, 1);
INSERT INTO `scheme_benefits` (`scheme_id`, `benefit_type`, `description`, `amount`, `amount_text`, `mode`, `frequency`, `conditions`, `sort_order`) VALUES
  (51, NULL, 'Free or subsidized soil testing.\nPersonalized fertilizer recommendations.\nInformation on soil amendments such as lime, gypsum, and organic manure.\nBetter crop yields and reduced input costs.\nLong-term improvement in soil health', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (52, NULL, 'Har Khet Ko Pani (HKKP) – Bringing irrigation water to every farm.\nPer Drop More Crop (PDMC) – Promoting efficient irrigation systems.\nWatershed Development – Soil and water conservation in rainfed areas.\nAccelerated Irrigation Benefit Programme (AIBP) – Completion of major and medium irrigation projects', NULL, NULL, NULL, NULL, NULL, 1),
  (53, 'Scholarship / Fee Support', '₹12,000 per year (₹1,000 per month) for selected students.\nThe scholarship is awarded from Class IX and can be renewed up to Class XII, subject to eligibility and academic performance', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 1),
  (54, 'Training', 'Free textbooks and uniforms for eligible students.\nConstruction of classrooms, toilets, drinking water facilities, and other school infrastructure.\nTeacher recruitment, training, and capacity building.\nInclusive education for children with special needs.\nICT and digital learning initiatives.\nVocational education from secondary classes onwards', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (55, 'Insurance Cover', 'Tuition fees\nLiving/maintenance allowance\nVisa fees\nMedical insurance\nAirfare and related travel expenses\nOther approved academic expenses', NULL, NULL, NULL, NULL, NULL, 1),
  (56, 'Insurance Cover', 'Corpus fund created for each eligible child.\nLump-sum financial support provided when the child reaches 23 years of age.\nMonthly stipend from age 18 to 23 years for personal needs./Admission in nearest Government or Kendriya Vidyalaya school.\nPayment of school fees, uniforms, books, and educational expenses where applicable.\nSupport for higher education through scholarships and educational loans./Coverage under Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana (AB-PMJAY).\nHealth insurance cover of ₹5 lakh per year.\nPremium paid by PM CARES', 500000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (57, 'Cash Benefit', 'Financial assistance of up to ₹4,000 per month per child (subject to state implementation and assessment).\nSupport for:\nEducation expenses\nNutrition\nHealthcare\nClothing and basic needs\nRehabilitation and family strengthening', 4000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (58, 'Training', 'Prenatal and postnatal healthcare.\nInstitutional delivery services.\nMedical examinations and treatment.\nNutrition support during pregnancy and after childbirth./Trauma counseling.\nMental health support.\nFamily counseling and rehabilitation services./Safe accommodation where required.\nPlacement in appropriate child care institutions if necessary./Legal aid and assistance during investigation and trial.\nSupport persons to assist the child through the judicial process./Continuation of schooling.\nVocational training and skill development where appropriate.\nSocial reintegration support./Financial support for care and rehabilitation needs as per approved norms and case assessment', NULL, NULL, NULL, NULL, NULL, 1),
  (59, 'Training', 'Safe accommodation and shelter.\nFood and clothing.\nMedical care and health services.\nPsychological counseling.\nLegal aid and support.\nEducation and skill development.\nVocational training and livelihood assistance.\nAssistance in opening bank accounts and accessing social security schemes', NULL, NULL, NULL, NULL, NULL, 1),
  (60, 'Service Delivery', 'Free or affordable mental health consultations.\nCounseling and psychological support.\nDiagnosis and treatment of mental illnesses.\nMedicines for mental health conditions through public health facilities.\nDistrict Mental Health Programme (DMHP) services at district hospitals.\nReferral to specialist psychiatric care when needed.\nCommunity awareness and mental health promotion activities.\n24×7 tele-counseling through Tele-MANAS (14416).\nRehabilitation and follow-up support for persons with mental illness.\nMental health services integrated with primary healthcare facilities', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (61, 'Service Delivery', 'Free normal delivery and Caesarean section (C-section).\nFree medicines and consumables.\nFree diagnostic tests.\nFree blood and blood products, if required.\nFree diet during hospital stay.\nFree transport from home to health facility.\nFree inter-facility transfer (if referred).\nFree drop-back transport from hospital to home.\nFree treatment for sick newborns up to 30 days after birth.\nFree treatment for sick infants up to 1 year of age at public health facilities', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (62, 'In-kind / Material', 'Free comprehensive antenatal check-up\nExamination by doctors, including specialists where available.\nBlood pressure, weight, and pregnancy assessment.\nFree laboratory tests (blood and urine tests).\nScreening for high-risk pregnancies.\nCounseling on nutrition, birth preparedness, and danger signs.\nReferral and follow-up care for high-risk pregnancies.\nEarly detection and management of pregnancy complications', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (63, 'Cash Benefit', 'Free health screening for children from birth to 18 years.\nEarly identification of health conditions under the 4 Ds:\nDefects at Birth\nDeficiencies\nDiseases\nDevelopmental Delays & Disabilities\nFree medical examinations and diagnostic services.\nReferral to specialized healthcare facilities when required.\nFree treatment and surgical interventions for identified conditions.\nEarly intervention services for developmental delays and disabilities.\nFollow-up care and monitoring', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (64, 'Training', 'Free adolescent-friendly health services and counseling.\nNutrition counseling and prevention of anemia.\nMenstrual health and hygiene support.\nSexual and reproductive health education and counseling.\nMental health counseling and psychosocial support.\nSubstance abuse prevention and counseling.\nInformation on prevention of injuries and violence.\nScreening and referral for health issues.\nPeer education and life-skills education programmes.\nAccess to Adolescent Friendly Health Clinics (AFHCs)', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (65, 'Cash Benefit', 'Free screening for diabetes, hypertension, and common cancers.\nEarly detection and diagnosis of NCDs.\nFree treatment and follow-up services at government health facilities.\nRegular monitoring of blood pressure and blood sugar.\nHealth counseling on diet, exercise, and lifestyle modification.\nReferral services for specialized treatment when required.\nCommunity-based screening for adults aged 30 years and above.\nAwareness and prevention programmes for NCDs.\nAccess to NCD clinics at District Hospitals and Community Health Centres', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (66, 'Service Delivery', 'Free or affordable palliative care services.\nPain relief and symptom management.\nHome-based and community-based palliative care support.\nCounseling and psychosocial support for patients and families.\nEnd-of-life care services.\nReferral to specialized palliative care centres.\nSupport for patients with cancer, advanced chronic diseases, and terminal illnesses', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (67, 'Cash Benefit', 'Free TB screening and testing.\nFree chest X-ray and diagnostic services (as per guidelines).\nFree TB medicines for drug-sensitive and drug-resistant TB.\nFree treatment and follow-up care.\nNutritional support through Nikshay Poshan Yojana.\nDirect Benefit Transfer (DBT) for eligible TB patients.\nContact tracing and screening of family members.\nCounseling and treatment adherence support.\nFree treatment for multidrug-resistant (MDR) and extensively drug-resistant (XDR) TB.\nCommunity-based TB care and support services', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (68, 'Service Delivery', 'HIV counselling and testing through Integrated Counselling and Testing Centres (ICTCs).\nAntiretroviral Therapy (ART) for People Living with HIV (PLHIV) to suppress the virus and improve quality of life.\nLaboratory investigations, including CD4 count and viral load testing, for monitoring treatment.\nPrevention of Parent-to-Child Transmission (PPTCT) services for pregnant women living with HIV.\nScreening and treatment of opportunistic infections and management of sexually transmitted infections (STIs).\nAdherence counselling, psychosocial support, and follow-up care to ensure successful treatment.\nFree condoms and HIV prevention services for key and vulnerable populations.\nSafe blood transfusion services through strengthened blood banks.\nLinkage to social welfare schemes and community support services through NACO and State AIDS Control Societies (SACS), wherever applicable', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (69, 'Cash Benefit', 'Financial assistance for medical treatment and rehabilitation.\nSupport for treatment within Meghalaya or outside the state, where required.\nAssistance to economically disadvantaged persons with disabilities who are unable to bear treatment co', NULL, NULL, NULL, NULL, NULL, 1),
  (70, 'Cash Benefit', 'Book Grant for students with disabilities to purchase books and study materials.\nUniform Grant for eligible school-going students with disabilities.\nConveyance Allowance to support transportation to educational institutions.\nUnemployment Allowance for eligible unemployed persons with disabilities to provide financial support', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (71, 'Scholarship / Fee Support', 'Free vocational training in various trades for persons with disabilities.\nStipend during the training period.\nSkill development to support self-employment and sustainable livelihoods.\nTraining delivered through recognized voluntary organizations in district headquarters', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (72, 'Scholarship / Fee Support', 'Monthly scholarship for students with disabilities pursuing education from pre-primary to university level.\nScholarship rates vary depending on the level of education and whether the student is a day scholar or hosteller.\nReader\'s allowance is provided to visually impaired students from Class IX onwards.\nState awards are also available for meritorious students with disabilities', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (73, 'Scholarship / Fee Support', 'Free vocational training in tailoring, knitting, embroidery, weaving, and other trades.\nMonthly stipend during the training period.\nPractical and theoretical skill development for self-employment and sustainable livelihoods.\nOpportunity to become economically independent through income-generating activities', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (74, 'Scholarship / Fee Support', 'Annual scholarship/stipend for eligible students pursuing post-matric education up to the degree level.\nStudents can continue to receive this scholarship along with other eligible scholarship schemes, as it is treated as a grant/subsidy', NULL, NULL, NULL, NULL, NULL, 1),
  (75, 'Scholarship / Fee Support', 'Financial scholarship awarded to meritorious students selected through a state-level scholarship examination.\nScholarship is tenable for three years, subject to good conduct and satisfactory academic progress.\nEncourages academic excellence and prepares students for future competitive examinations', NULL, NULL, NULL, NULL, NULL, 1);
INSERT INTO `scheme_benefits` (`scheme_id`, `benefit_type`, `description`, `amount`, `amount_text`, `mode`, `frequency`, `conditions`, `sort_order`) VALUES
  (76, 'Credit / Subsidy', 'EWS households: Three bundles of 9-foot GCI roofing sheets as an outright grant to improve existing houses.\nLIG households: Financial assistance of up to ₹75,000 under the Credit Linked Subsidy component for construction of a durable house (minimum carpet area of 19.20 sq. m. with at least two rooms).\nHouses are constructed as per government-approved designs, with additional costs met through the beneficiary\'s own contribution, MGNREGS, SRWP, or bank loans, where applicable', 75000.0, NULL, NULL, NULL, NULL, 1),
  (77, 'Cash Benefit', 'Under the original RHS, eligible beneficiaries received three bundles of CGI (Corrugated Galvanized Iron) roofing sheets as a grant to complete the roofing of their houses.\nThe scheme benefited over 71,000 rural households before being discontinued and replaced by CMHAP', NULL, NULL, NULL, NULL, NULL, 1),
  (78, 'Cash Benefit', 'One-time mobilization grant of ₹5,000 to each member of a registered Producer Group.\nSupport for value chain development, aggregation, marketing, transportation, farm machinery, and livelihood enhancement.\nCapacity building and technical support for Producer Groups', 5000.0, NULL, 'One-time', 'One-time', NULL, 1),
  (79, 'Cash Benefit', '₹5,000 cash assistance to each eligible producer household under FOCUS+.\nBenefit is generally released in two instalments (₹1,000 upon registration and ₹4,000 after verification).\nAdditional benefit over and above assistance received under the FOCUS scheme', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'In instalments', NULL, 1),
  (80, 'Insurance Cover', 'Cashless hospitalization with health insurance coverage of up to ₹5.3 lakh per family per year on a floater basis.\nCovers secondary and tertiary care, including surgeries, critical care, oncology, and several specialized treatments.\nTreatment available at empanelled government and private hospitals within Meghalaya and at empanelled hospitals across India under the AB-PMJAY network.\nCoverage for pre-existing diseases from the start of enrolment, subject to scheme guidelines', 530000.0, NULL, 'Recurring', 'Annual', NULL, 1),
  (81, 'Pension', 'Monthly pension of ₹500 per eligible beneficiary.\nPension is disbursed quarterly through the beneficiary\'s bank account or post office account.\nBeneficiaries are issued a Pension Card for receiving pension payments', 500.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (82, 'Credit / Subsidy', 'Financial assistance/subsidy ranging from 35% to 75% of the project cost, depending on the scheme.\nAccess to bank credit and interest subvention under eligible schemes.\nEntrepreneurship training, capacity building, mentoring, and handholding support.\nAssistance for establishing or expanding businesses across multiple sectors', NULL, NULL, NULL, NULL, NULL, 1),
  (83, 'Pension', 'Monthly financial assistance (pension) to eligible beneficiaries.\nSupport is provided under categories such as:\nPension for Single Mothers\nPension for Infirm Persons\nPension is credited directly to the beneficiary\'s bank account', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (84, 'Scholarship / Fee Support', 'Financial assistance for educational expenses, including maintenance allowance and other admissible school-related costs.\nScholarship amount is transferred directly to the student\'s Aadhaar-linked bank account through Direct Benefit Transfer (DBT).\nScholarship amount varies depending on the student\'s category and the applicable departmental scheme', NULL, NULL, NULL, NULL, NULL, 1),
  (85, 'Scholarship / Fee Support', 'Scholarship for maintenance and educational expenses.\nReimbursement of tuition and other admissible fees as per scheme guidelines.\nDirect Benefit Transfer (DBT) of the scholarship amount to the student\'s Aadhaar-linked bank account.\nAvailable for students belonging to SC, ST, OBC, General (EWS), and Minority categories under the respective departmental schemes', NULL, NULL, NULL, NULL, NULL, 1),
  (86, 'Pension', '₹1,000 per month as pension, credited directly to the beneficiary\'s Aadhaar-linked bank account through Direct Benefit Transfer (DBT).\nPension is generally disbursed on a quarterly basis.\nProvides financial support to elderly persons who have no regular source of income', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (87, 'Cash Benefit', 'One-time financial assistance of ₹30,000 to the eligible dependent family member.\nThe amount is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT).\nDesigned to help families meet immediate financial needs after the loss of the main breadwinner', 30000.0, NULL, 'One-time', 'One-time', NULL, 1),
  (88, 'Cash Benefit', 'Financial assistance of up to ₹1,00,000 per eligible couple (as per the latest revised provisions), which includes:\n₹75,000 transferred directly to the bride\'s bank account.\n₹10,000 for clothes, gifts, and essential household items.\n₹15,000 towards the organization of the mass marriage ceremony.\nMarriage ceremonies are conducted according to the customs and traditions of different religions and communities', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1),
  (89, 'Service Delivery', 'Free online and offline coaching for competitive examinations such as UPSC, UPPSC, JEE, NEET, NDA, CDS, SSC, Banking, TET, and other government recruitment exams.\nFree study materials, e-learning resources, previous years\' question papers, mock tests, and doubt-clearing sessions.\nGuidance and mentoring by IAS, IPS, IFS officers and subject experts.\nMock interviews and career counselling for shortlisted candidates', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (90, 'Cash Benefit', 'Financial assistance ranging from ₹22,500 to ₹8,25,000, depending on the nature and severity of the offence, as prescribed under the SC/ST (Prevention of Atrocities) Rules.\nRelief is provided in stages linked to the progress of the criminal case (e.g., after FIR, charge sheet, and trial).\nAdditional support may include rehabilitation and other assistance as provided under the Act and Rules', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1),
  (91, 'Cash Benefit', 'One-time financial assistance of ₹20,000 per eligible daughter\'s marriage.\nA maximum of two daughters per family are eligible for assistance.\nThe assistance is intended to reduce the financial burden on poor families', 20000.0, NULL, 'One-time', 'One-time', NULL, 1),
  (92, 'Cash Benefit', 'Financial assistance of ₹25,000 per eligible girl, disbursed in six stages:\n\nStage I: ₹5,000 – At the birth of a girl child.\nStage II: ₹2,000 – After completion of one year of age and full immunization.\nStage III: ₹3,000 – On admission to Class I.\nStage IV: ₹3,000 – On admission to Class VI.\nStage V: ₹5,000 – On admission to Class IX.\nStage VI: ₹7,000 – On admission to a degree, diploma, or certificate course after passing Class XII (or a two-year diploma)', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1),
  (93, 'Pension', 'Monthly pension of ₹1,000, credited directly to the beneficiary\'s bank account through DBT.\nFinancial support to help meet basic living expenses.\nPension is subject to periodic verification and renewal as per government guidelines', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (94, 'Pension', 'Monthly pension of ₹1,000 to eligible beneficiaries.\nPension is transferred directly to the beneficiary\'s Aadhaar-linked bank account through Direct Benefit Transfer (DBT).\nPension is generally disbursed on a quarterly basis', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (95, 'Training', 'Monthly financial assistance of:\n₹4,000 under the COVID category.\n₹2,500 under the General category.\nFree education up to Class XII and admission to residential schools for eligible children.\nOne-time tablet/laptop for eligible students studying in Class IX and above or pursuing vocational education.\nMarriage assistance of ₹1,01,000 for eligible girl beneficiaries (COVID category).\nContinued financial support for eligible students pursuing higher education up to 23 years of age under prescribed conditions.\nRehabilitation support for children rescued from child labour, child trafficking, child begging, and those restored from Child Care Institutions', NULL, 'Multiple amounts specified (see benefit description)', 'Both', 'Monthly', NULL, 1),
  (96, 'Cash Benefit', '₹5 lakh in case of accidental death.\n₹5 lakh for permanent total disability.\n₹2.5 lakh for permanent partial disability (as prescribed under the scheme).\nCovers accidents such as road accidents, drowning, lightning, snakebite, animal attacks, electrocution, fire, floods, and other notified accidental causes', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1),
  (97, 'Insurance Cover', 'Cashless health insurance coverage of up to ₹5 lakh per family per year.\nCovers secondary and tertiary hospitalization at empanelled government and private hospitals.\nCovers pre-existing diseases from Day 1.\nNo restriction on family size.\nTreatment available across India through the PM-JAY empanelled hospital network with national portability', 500000.0, NULL, 'Recurring', 'Annual', NULL, 1),
  (98, 'Cash Benefit', 'Financial assistance ranging from ₹1 lakh to ₹10 lakh, depending on the nature and severity of the offence.\nFree medical treatment, including reconstructive surgery where required.\nEducational and medical assistance for the minor children of victims, where applicable.\nRehabilitation and other support services to help survivors recover and reintegrate into society', NULL, 'Multiple amounts specified (see benefit description)', 'In-kind', NULL, NULL, 1),
  (99, 'Pension', 'Financial assistance for children\'s education and scholarships.\nMarriage assistance for workers and their daughters.\nMaternity and paternity benefits.\nAccident, disability, and death compensation.\nPension after attaining the eligible age.\nHousing assistance and toilet construction support.\nMedical assistance and treatment.\nToolkits, skill development, and vocational training.\nAssistance for bicycles, safety equipment, and other welfare measures', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (100, 'Credit / Subsidy', 'Bank loan up to ₹25 lakh for manufacturing/industrial projects.\nBank loan up to ₹10 lakh for service sector enterprises.\nMargin money subsidy:\n15% of the project cost (General category).\n25% of the project cost (SC/ST/OBC/Minorities/Women/Ex-servicemen/Persons with Disabilities), subject to prescribed limits.\nSubsidy is released after successful establishment and operation of the enterprise as per scheme guidelines', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1);
INSERT INTO `scheme_benefits` (`scheme_id`, `benefit_type`, `description`, `amount`, `amount_text`, `mode`, `frequency`, `conditions`, `sort_order`) VALUES
  (101, 'Cash Benefit', '₹1,500 per month per adopted cow (₹50 per day) is provided through Direct Benefit Transfer (DBT).\nFinancial assistance is available for adopting up to four destitute cows.\nPromotes sustainable livestock rearing and provides an additional source of income through dairy products and organic manure', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 1),
  (102, 'Cash Benefit', 'One-time financial assistance of ₹25,000.\nAmount is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT).\nEncourages marriage only after the legal age and supports women\'s social and economic security', 25000.0, NULL, 'One-time', 'One-time', NULL, 1),
  (103, 'Cash Benefit', '₹3,000 per month is provided to eligible women through Direct Benefit Transfer (DBT).\nThe assistance can be used for food, healthcare, education, and other household needs.\nExisting eligible beneficiaries of Lakshmir Bhandar are automatically migrated to the new scheme after verification', 3000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (104, 'Training', 'Monthly unemployment assistance of ₹1,500 through Direct Benefit Transfer (DBT).\nAccess to Employment Bank for job opportunities.\nSkill development and vocational training to improve employability.\nPlacement support for employment in government and private sectors', 1500.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (105, 'Scholarship / Fee Support', 'K1: Annual scholarship of ₹1,000 for eligible unmarried girls aged 13–18 years enrolled in school or equivalent educational/vocational institutions.\nK2: One-time grant of ₹25,000 to eligible unmarried girls after attaining 18 years of age, provided they are continuing education or vocational training.\nK3: Higher education scholarship for girls pursuing undergraduate/postgraduate studies under notified institutions (amount as per prevailing government guidelines)', NULL, 'Multiple amounts specified (see benefit description)', 'One-time', 'One-time', NULL, 1),
  (106, 'Insurance Cover', 'Cashless health coverage up to ₹5 lakh per family per year.\nCovers secondary and tertiary hospitalization, including surgeries, diagnostics, and specialized treatments.\nNo premium is payable by beneficiaries; the entire premium is borne by the State Government.\nCovers pre-existing diseases from the date of enrolment.\nTreatment is available at empanelled government and private hospitals', 500000.0, NULL, 'Recurring', 'Annual', NULL, 1),
  (107, 'In-kind / Material', 'Online registration of births and deaths.\nDownload of digitally signed birth and death certificates.\nFacility for certificate correction, delayed registration, status tracking, and certificate verification.\nQR code-enabled certificates for easy authentication', NULL, NULL, NULL, NULL, NULL, 1),
  (108, 'Service Delivery', 'Free teleconsultation with specialist doctors at government health facilities.\nAccess to specialist services in cardiology, neurology, oncology, paediatrics, obstetrics & gynaecology, psychiatry, nephrology, gastroenterology, tuberculosis, viral hepatitis, breast diseases, and other specialties.\nReduces travel time and out-of-pocket medical expenses for rural patients.\nFacilitates follow-up consultations, early diagnosis, timely referrals, and continuity of care. The programme has provided over 7 crore teleconsultations through more than 11,000 Health & Wellness Centres, supported by 63 specialist hubs and over 9,000 doctors', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (109, 'Service Delivery', 'Free treatment and surgeries for eligible children at empanelled government and private hospitals.\nCovers major conditions such as:\nCongenital heart diseases (paediatric cardiac surgery)\nNeurosurgical conditions\nCongenital cataract and other critical eye surgeries\nOther notified congenital disorders under the scheme.\nCovers the entire cost of treatment, including hospitalization and surgery, with no out-of-pocket expenditure for the family', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (110, 'Scholarship / Fee Support', 'Monthly scholarship ranging from ₹1,000 to ₹8,000, depending on the course and level of study.\nFinancial assistance is provided through Direct Benefit Transfer (DBT) to the student\'s bank account.\nAvailable for students pursuing Higher Secondary, UG, PG, Engineering, Medical, Polytechnic, Technical, Professional, and eligible Research courses', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 1),
  (111, NULL, 'Full or partial waiver of tuition fees, depending on eligibility and availability.\nApplicable only to tuition fees; other fees (hostel, examination, library, etc.) must be borne by the student.\nReduces the financial burden of pursuing professional technical education', NULL, NULL, NULL, NULL, NULL, 1),
  (112, 'Credit / Subsidy', 'State Capital Investment Subsidy for eligible new and expanding MSMEs.\nInterest Subsidy on term loans for eligible enterprises.\nReimbursement of Stamp Duty and Registration Fees.\nNet SGST reimbursement for eligible manufacturing units.\nPower subsidy and incentives for energy efficiency and environmental compliance.\nAdditional incentives for women, SC/ST, and minority entrepreneurs in eligible categories', NULL, NULL, NULL, NULL, NULL, 1),
  (113, 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nPension is credited directly to the beneficiary\'s bank account.\nProvides financial support to elderly ST beneficiaries for meeting basic living expenses', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (114, 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nPension is credited directly to the beneficiary\'s bank account.\nProvides financial support for meeting basic living expenses', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (115, 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nPension is credited directly to the beneficiary\'s bank account.\nProvides regular financial support to meet basic living expenses and improve social security', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (116, 'Cash Benefit', '₹10,000 per year (paid in two equal instalments during the Kharif and Rabi seasons) for farmers with 1 acre or more of cultivable land.\nFarmers with less than 1 acre of cultivable land receive pro-rata assistance, subject to a minimum of ₹4,000 per year.\n₹2 lakh one-time death benefit to the nominee/legal heir if a registered farmer aged 18–60 years dies.\nRegistered farmers may also receive preference under certain state agricultural support programmes', NULL, 'Multiple amounts specified (see benefit description)', 'Both', 'Annual', NULL, 1),
  (117, 'Insurance Cover', 'Free crop insurance with no premium payable by the farmer.\nCompensation for crop loss due to:\nPrevented/failed sowing.\nMid-season adversity.\nNatural calamities affecting standing crops.\nPost-harvest losses for notified crops.\nCoverage for both Kharif and Rabi notified crops', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (118, 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nFinancial support for:\nSenior citizens.\nWidows.\nPersons with disabilities.\nPension is credited directly to the beneficiary\'s bank account', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 1),
  (119, 'In-kind / Material', 'Free bicycle provided to eligible students studying in Class IX–XII.\nHelps reduce travel time and transportation barriers to school.\nPromotes school attendance, retention, and gender equality in education', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (120, 'Credit / Subsidy', 'Soft loan up to ₹2 lakh for establishing a new enterprise.\nProject subsidy of 15% of the project cost, subject to a maximum of ₹25,000.\nInterest subsidy:\n50% of the interest for timely loan repayment (up to 3 years).\n40% of the interest in other eligible cases (up to 3 years).\nLoan is disbursed through the West Bengal State Cooperative Bank and affiliated cooperative banks', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1),
  (121, 'Credit / Subsidy', 'Formation and strengthening of Self-Help Groups (SHGs) and their federations.\nAccess to bank credit, microfinance, and revolving funds.\nSkill development and vocational training for livelihood enhancement.\nSupport for micro-enterprises, agriculture, livestock, fisheries, and producer groups.\nMarket linkage, value chain development, and entrepreneurship support for SHG members', NULL, NULL, NULL, NULL, NULL, 1),
  (122, 'Cash Benefit', 'Rice and wheat at highly subsidized rates (generally ₹2 per kg for eligible beneficiaries under applicable categories).\nFood grain entitlement varies according to the beneficiary\'s ration card category (e.g., AAY, PHH/SPHH, RKSY).\nAccess through physical or digital (e-Ration) cards.\nEnsures regular supply of essential food grains to eligible households', 2.0, NULL, NULL, NULL, NULL, 1),
  (123, 'Cash Benefit', 'Financial assistance is provided in stages:\n₹2,500 for girls studying in Class VIII.\n₹2,500 for girls studying in Class IX.\n₹5,000 each for girls studying in Classes X, XI, and XII.\nOne-time grant of ₹20,000 when the beneficiary attains 18 years of age and fulfills the scheme conditions.\nThe total assistance under the scheme is up to ₹40,000, transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', NULL, 'Multiple amounts specified (see benefit description)', 'One-time', 'One-time', NULL, 1),
  (124, 'Credit / Subsidy', 'Education loan up to ₹15 lakh without collateral.\nSubsidized simple interest rate of 4% per annum.\nNo processing fee.\nRepayment period of up to 15 years, including a one-year moratorium after course completion or employment (whichever is earlier).\nLoan covers tuition fees, hostel charges, books, laptops, and other approved education-related expenses', 1500000.0, NULL, 'Recurring', 'Annual', NULL, 1),
  (125, 'Pension', 'Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).\nCovers the following categories:\nOld Age Pension (60 years and above).\nWidow Pension.\nDisability Pension (40% or more disability).\nSingle/abandoned women (as per scheme guidelines).\nPension for persons living with HIV/AIDS.\nPension is credited directly to the beneficiary\'s bank account every mon', 1000.0, NULL, 'Recurring', 'Monthly', NULL, 1);
INSERT INTO `scheme_benefits` (`scheme_id`, `benefit_type`, `description`, `amount`, `amount_text`, `mode`, `frequency`, `conditions`, `sort_order`) VALUES
  (126, 'Cash Benefit', '₹2,500 per month (₹30,000 per year) transferred directly to the beneficiary\'s Aadhaar-linked bank account through DBT.\nPromotes women\'s financial independence and supports household expenses.\nNo contribution is required from the beneficiary', NULL, 'Multiple amounts specified (see benefit description)', 'Recurring', 'Monthly', NULL, 1),
  (127, 'Cash Benefit', 'Financial assistance of ₹2 lakh for construction of a pucca house.\nHouse of approximately 31 sq. metres with three rooms, a kitchen, and a toilet.\n95 days of MGNREGA wages for eligible beneficiaries to support house construction.\nFinancial assistance is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', 200000.0, NULL, NULL, NULL, NULL, 1),
  (128, 'Insurance Cover', 'Subsidized or free rice for eligible Green Card holders.\nMonthly distribution of food grains through the Public Distribution System (PDS).\nEnsures food security for economically weaker and vulnerable households excluded from NFSA coverage', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (129, 'In-kind / Material', 'Plantation of fruit-bearing and fodder trees on eligible land.\nUp to 100 days of wage employment under MGNREGA for plantation and maintenance activities.\nUsufruct rights (right to use and benefit from the produce) for eligible beneficiaries.\nPromotes long-term income generation through horticulture and agroforestry while improving environmental sustainability', NULL, NULL, NULL, NULL, NULL, 1),
  (130, 'Training', 'Subsidy for the purchase of milch cattle (cow/buffalo), goats, pigs, ducks, and poultry.\nSubsidy up to 90% for eligible women, widows, persons with disabilities, and other notified vulnerable categories; up to 75% for other eligible beneficiaries (as per prevailing government norms).\nSupport for animal care training and scientific livestock management.\nPromotes self-employment and sustainable livelihood opportunities in rural areas', NULL, NULL, NULL, NULL, NULL, 1),
  (131, 'Credit / Subsidy', 'Interest-free loan of up to ₹10,000 to start an alternative livelihood or micro-enterprise.\nCounselling, skill development, and handholding support for transitioning to sustainable occupations.\nLinkage with Self-Help Groups (Sakhi Mandals) and JSLPS for financial inclusion and livelihood support.\nAssistance in starting activities such as agriculture, animal husbandry, poultry, grocery shops, tailoring, forest produce enterprises, and other income-generating businesses', 10000.0, NULL, 'In-kind', NULL, NULL, 1),
  (132, 'Pension', 'Financial assistance for education, maternity, marriage, and medical treatment.\nAccident, disability, and death assistance for registered workers and their families.\nTool kit assistance, bicycle assistance, pension, housing assistance, and other welfare benefits under various schemes.\nSkill development and livelihood support for construction workers', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (133, 'Scholarship / Fee Support', 'Financial assistance towards tuition fees, maintenance allowance, hostel fees, and other educational expenses.\nPre-Matric Scholarship: For students studying from Class I to Class X.\nPost-Matric Scholarship: For students pursuing Class XI onwards, including Intermediate, ITI, Diploma, Undergraduate, Postgraduate, Professional, and Technical courses.\nScholarship amount is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT)', NULL, NULL, NULL, NULL, NULL, 1),
  (134, 'Insurance Cover', 'One-time drought relief assistance of ₹3,500 to eligible farmer families affected by drought.\nFinancial assistance is transferred directly to the beneficiary\'s bank account through Direct Benefit Transfer (DBT).\nSupports farmers in meeting immediate livelihood and agricultural expenses after crop loss due to drought\nCashless health insurance coverage for secondary and tertiary medical treatment at empanelled hospitals, subject to scheme guidelines', 3500.0, NULL, 'One-time', 'One-time', NULL, 1),
  (135, 'Cash Benefit', '1) Idea-stage startups: Grant funding up to ₹3 lakh. 2) Revenue-stage startups: Grant funding up to ₹100 lakh', NULL, 'Multiple amounts specified (see benefit description)', NULL, NULL, NULL, 1),
  (136, 'Cash Benefit', 'Monthly financial assistance to eligible women to enhance their social and economic security', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (137, 'Scholarship / Fee Support', 'Scholarship for students with disabilities; Caregiver allowance for persons with severe disabilities; Maintenance grant for homeless older persons', NULL, NULL, NULL, NULL, NULL, 1),
  (138, 'Cash Benefit', 'Financial assistance and welfare support for eligible artists, including support during hardship, subject to scheme guidelines', NULL, NULL, NULL, NULL, NULL, 1),
  (139, 'Training', 'Free vocational training in income-generating trades to enhance employability and promote self-employment', NULL, NULL, 'In-kind', NULL, NULL, 1),
  (140, 'Cash Benefit', 'Monthly financial assistance through Direct Benefit Transfer (DBT) to support essential household expenses such as food, medicines, and utilities', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (141, 'Cash Benefit', 'Monthly financial assistance through DBT to eligible girl students to encourage continuation of higher education and discourage child marriage', NULL, NULL, 'Recurring', 'Monthly', NULL, 1),
  (142, 'Credit / Subsidy', 'One-time education loan subsidy of ₹50,000 credited towards the eligible education loan account', 50000.0, NULL, 'One-time', 'One-time', NULL, 1),
  (143, 'Training', 'Financial assistance, capital subsidy, entrepreneurship support, skill development and bank linkage for setting up or expanding enterprises', NULL, NULL, NULL, NULL, NULL, 1),
  (144, 'Cash Benefit', 'Financial assistance to establish or expand income-generating activities, livelihood support, enterprise development, and capacity building for eligible SHG women', NULL, NULL, NULL, NULL, NULL, 1),
  (145, 'Credit / Subsidy', 'Financial assistance, revolving fund support, bank credit linkage, capacity building, entrepreneurship promotion, and livelihood support for eligible SHGs', NULL, NULL, NULL, NULL, NULL, 1),
  (146, 'Credit / Subsidy', 'Financial incentive and relief for eligible microfinance borrowers, including support for repayment and reduction of loan burden as per Government guidelines', NULL, NULL, NULL, NULL, NULL, 1),
  (147, 'Credit / Subsidy', 'Interest subsidy on vehicle loan for purchase of a new vehicle to improve safe and affordable mobility', NULL, NULL, NULL, NULL, NULL, 1),
  (148, NULL, 'Educational assistance through digital learning support (such as laptops/tablets or other notified benefits) to promote higher education and digital access', NULL, NULL, NULL, NULL, NULL, 1),
  (149, 'Scholarship / Fee Support', 'Educational incentive/scholarship to encourage students to study and preserve indigenous languages of Assam', NULL, NULL, NULL, NULL, NULL, 1),
  (150, 'Pension', 'Monthly social security pension through Direct Benefit Transfer (DBT) to eligible senior citizens', NULL, NULL, 'Recurring', 'Monthly', NULL, 1);
