  (154, 'Cash Benefit', 'Financial assistance through Direct Benefit Transfer (DBT) and welfare support to improve livelihood and socio-economic security of tea garden workers', NULL, NULL, NULL, NULL, NULL, 1),
  (155, 'Cash Benefit', 'A total cash assistance of ₹15,000 provided in four installments', 15000.0, NULL, 'Recurring', 'In instalments', NULL, 1),
